-- Records of aiedu_aitool
-- ----------------------------
INSERT INTO `aiedu_aitool` VALUES (1, 'see-face-analysis', '人脸分析', 'Face Analysis', '观察 AI 如何理解人脸特征', 'Observe how AI understands facial features', '培养学生对 AI 识别能力的理解', 'Develop understanding of AI recognition', 'Smile', 'see', 0, '2026-01-15 10:53:28', '2026-02-04 17:23:49', 'recognition');
INSERT INTO `aiedu_aitool` VALUES (2, 'play-draw-&-guess', '你画我猜', 'Draw & Guess', '体验 AI 的识别与判断能力', 'Experience AI recognition', '通过游戏化方式体验 AI 识别', 'Experience AI through gamification', 'Palette', 'play', 0, '2026-01-15 10:53:28', '2026-02-04 17:24:04', 'recognition');
INSERT INTO `aiedu_aitool` VALUES (3, 'train-image', '图像分类', 'Image Classification', '学习 AI 如何通过数据学习', 'Learn how AI learns from data', '理解机器学习的核心原理', 'Understand core ML principles', 'Image', 'train', 1, '2026-01-15 10:53:28', '2026-02-04 17:24:05', 'recognition');
INSERT INTO `aiedu_aitool` VALUES (4, 'train-pose', '姿态分类', 'Gesture Classification', '训练 AI 识别不同人体姿态', 'Train AI to recognize pose', '学习如何训练自己的 AI 模型', 'Learn to train your own AI model', 'PersonStanding', 'train', 0, '2026-01-15 10:53:28', '2026-02-26 16:49:16', 'recognition');
INSERT INTO `aiedu_aitool` VALUES (5, 'train-sound', '音频分类', 'Audio Classification', '让 AI 学会听声辨音', 'Teach AI to recognize sounds', '探索音频识别的应用场景', 'Explore audio recognition applications', 'Volume2', 'train', 0, '2026-01-15 10:53:28', '2026-02-04 17:24:08', 'recognition');
INSERT INTO `aiedu_aitool` VALUES (6, 'generate-image', '绘图助手', 'Drawing Assistant', '使用 AI 生成图像', 'Generate images using AI', '激发创造力，理解 AIGC 原理', 'Inspire creativity, understand AIGC', 'Image', 'create', 0, '2026-01-15 10:53:28', '2026-02-04 17:24:14', 'generation');
INSERT INTO `aiedu_aitool` VALUES (7, 'generate-video', '视频助手', 'Video Assistant', '使用 AI 生成视频', 'Generate videos using AI', '探索视频创作的新可能', 'Explore new possibilities in video creation', 'Video', 'create', 0, '2026-01-15 10:53:28', '2026-02-04 17:24:15', 'generation');
INSERT INTO `aiedu_aitool` VALUES (9, 'generate-text', '灵感对话', 'Inspiration Chat', '使用 AI 生成文本内容', 'Generate text content using AI', '培养批判性思维与创作能力', 'Develop critical thinking and creativity', 'FileText', 'create', 0, '2026-01-15 10:53:28', '2026-02-04 17:24:17', 'generation');
INSERT INTO `aiedu_aitool` VALUES (10, 'pose-detection', '姿态识别', 'Pose Detection', '体验 AI 的识别与判断能力', 'Experience AI recognition', '体验 AI 姿态识别', 'Experience AI through pose detection', 'PersonStanding', 'play', 0, '2026-01-15 10:53:28', '2026-02-26 16:49:13', 'recognition');

-- ----------------------------
-- Table structure for aiedu_class
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_class`;
CREATE TABLE `aiedu_class`  (
  `class_id` int NOT NULL AUTO_INCREMENT COMMENT '班级ID',
  `teacher_id` int NULL DEFAULT NULL COMMENT '创建班级的老师id',
  `grade` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '年级',
  `class_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '班级名称',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '描述',
  `student_count` int NULL DEFAULT 0 COMMENT '学生人数',
  `created_at` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`class_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '班级信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_class
-- ----------------------------


-- ----------------------------
-- Table structure for aiedu_classroom_session
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_classroom_session`;
CREATE TABLE `aiedu_classroom_session`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `class_id` int NOT NULL COMMENT '关联字段-班级表id',
  `classroom_id` int NOT NULL COMMENT '课堂ID',
  `classroom_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '课堂名称',
  `teacher_id` int NOT NULL COMMENT '教师ID',
  `teacher_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '教师姓名',
  `class_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '课堂码',
  `current_stage` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT 'waiting' COMMENT '当前阶段\'waiting\', \'tool-experience\', \'quiz\', \'completed\'',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT 'active' COMMENT '会话状态\'active\', \'ended\'',
  `grade` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '年级',
  `ai_tool_json` json NULL COMMENT 'AI工具',
  `courseware_json` json NULL COMMENT '教学课件',
  `quiz_config_json` json NULL COMMENT '测验配置json',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_class_code`(`class_code` ASC) USING BTREE,
  INDEX `idx_classroom_id`(`classroom_id` ASC) USING BTREE,
  INDEX `idx_teacher_id`(`teacher_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '课堂会话信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_classroom_session
-- ----------------------------


-- ----------------------------
-- Table structure for aiedu_classroom_session_student
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_classroom_session_student`;
CREATE TABLE `aiedu_classroom_session_student`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `classroom_session_id` int NULL DEFAULT NULL COMMENT '关联字段aiedu_classroom_session.id',
  `student_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学号',
  `student_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学生名称',
  `joined_at` datetime NULL DEFAULT NULL COMMENT '加入课堂时间',
  `work_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT 'AIGC作业状态：waiting, in-progress，completed',
  `api_count` int NULL DEFAULT 0 COMMENT 'API/模型调用数',
  `quiz_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '测验状态：ready,answering,submitted',
  `quiz_answers_jsonarray` json NULL COMMENT '学生提交的测验答题内容',
  `quiz_result_jsonobject` json NULL COMMENT '学生测验结果json',
  `submitted_at` datetime NULL DEFAULT NULL COMMENT '测验提交时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `classroom_session_id`(`classroom_session_id` ASC) USING BTREE,
  INDEX `student_id`(`student_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 128 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '课堂会话学生上课信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_classroom_session_student
-- ----------------------------


-- ----------------------------
-- Table structure for aiedu_classroom_session_student_work
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_classroom_session_student_work`;
CREATE TABLE `aiedu_classroom_session_student_work`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `classroom_session_id` int NULL DEFAULT NULL COMMENT '关联字段aiedu_classroom_session.id',
  `student_id` varchar(20) CHARACTER SET utf32 COLLATE utf32_general_ci NULL DEFAULT NULL COMMENT '学号',
  `student_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学生名称',
  `ai_tool_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '作品类型：generation AIGC 类工具，recognition 识别类工具',
  `submission_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '提交类型：manual，snapshot',
  `content_json` json NULL COMMENT '提交内容（单次提交的内容）',
  `submitted_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '作品提交时间',
  `final_submit` tinyint NULL DEFAULT NULL COMMENT '是否最终提交作品：0 否 1 是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_classroom_session_id`(`classroom_session_id` ASC) USING BTREE,
  INDEX `idx_student_id`(`student_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11944 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '课堂会话学生作品信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_classroom_session_student_work
-- ----------------------------


-- ----------------------------
-- Table structure for aiedu_classrooms
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_classrooms`;
CREATE TABLE `aiedu_classrooms`  (
  `classroom_id` int NOT NULL AUTO_INCREMENT COMMENT '课堂记录ID',
  `teacher_id` int NOT NULL COMMENT '教师ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '课程名称',
  `grade` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '年级',
  `class_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '班级',
  `ai_tool_json` json NULL COMMENT 'AI工具',
  `courseware_json` json NULL COMMENT '教学课件',
  `quiz_config_json` json NULL COMMENT '测验配置JSON',
  `featured` tinyint NULL DEFAULT 0 COMMENT '是否精选',
  `created_at` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `last_used_at` datetime NULL DEFAULT NULL COMMENT '最近使用时间',
  `is_template` tinyint NULL DEFAULT NULL COMMENT '是否模板',
  PRIMARY KEY (`classroom_id`) USING BTREE,
  INDEX `idx_teacher_id`(`teacher_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '课堂配置表' ROW_FORMAT = Dynamic;

