INSERT INTO `aiedu_classrooms` VALUES (12, 3, '用AI生成环保海报', 'G3', '', '{\"id\": 6, \"icon\": \"Image\", \"name\": \"绘图助手\", \"nameEn\": \"Drawing Assistant\", \"toolId\": \"generate-image\", \"category\": \"create\", \"createdAt\": \"2026-01-15 10:53:28\", \"updatedAt\": \"2026-02-04 17:24:14\", \"aiToolType\": \"generation\", \"description\": \"使用 AI 生成图像\", \"recommended\": false, \"teachingGoal\": \"激发创造力，理解 AIGC 原理\", \"descriptionEn\": \"Generate images using AI\", \"teachingGoalEn\": \"Inspire creativity, understand AIGC\"}', '{\"id\": \"rec0RQ33Aw\", \"unit\": \"U1\", \"grade\": \"G1\", \"title\": \"二叉树是如何工作的？\", \"topic\": \"看见结构：我们如何组织数据\", \"summary\": \"本课中，学生将探索如何使用二叉树这种简单而强大的工具，通过一系列是/否问题来组织信息。课堂首先以熟悉的物品和校园相关类别为例，全班共同构建一棵二叉树。然后，学生独立完成一份简短的练习单以巩固概念。最后，全班一起帮助老师整理一个“虚拟的凌乱房间”，通过将物品分类到 2–3 层的二叉树中完成整理。课后，学生将理解二元分类如何帮助我们做出决策、快速查找并保持有序。\", \"titleEn\": \"How Do Binary Trees Work?\", \"topicEn\": \"Seeing Structure: How We Organize Data\", \"literacy\": \"数据素养\", \"summaryEn\": \"In this lesson, students will explore how to use binary trees, a simple yet powerful tool, to organize information through a series of yes/no questions. The class begins with familiar items and campus-related categories as examples, and the whole class builds a binary tree together. Then, students independently complete a short exercise sheet to consolidate the concepts. Finally, the whole class helped the teacher organize a \\\"virtual messy room\\\" together, completing the organization by classifying the items into a binary tree of 2 to 3 levels. After class, students will understand how binary classification helps us make decisions, find things quickly and stay organized.\", \"coverImage\": \"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U1_L1.png\", \"createTime\": \"2025-12-25\", \"lessonCode\": \"G1_T1_U1_L1\", \"lessonType\": \"通识课\", \"literacyEn\": \"Data Literacy\", \"updateTime\": \"2026-02-04\", \"keyConcepts\": \"二元决策；树状分类；信息组织结构\", \"lessonTypeEn\": \"General\", \"pptCanvaCode\": \"<div style=\\\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\\n border-radius: 8px; will-change: transform;\\\">\\n  <iframe loading=\\\"lazy\\\" style=\\\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\\\"\\n    src=\\\"https://education.braightidea.com/canva-design/DAGvfYmv-oQ/B3_pjtGrGFxuH7SpcNhxqw/view?embed\\\" allowfullscreen=\\\"allowfullscreen\\\" allow=\\\"fullscreen\\\">\\n  </iframe>\\n</div>\\n<a href=\\\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfYmv-oQ&#x2F;B3_pjtGrGFxuH7SpcNhxqw&#x2F;view?utm_content=DAGvfYmv-oQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\">G1上_U1_L1_Slides</a>，作者 Iris\", \"keyConceptsEn\": \"Binary Decision;Tree Classification;Information Structure\", \"keyConceptList\": [\"二元决策\", \"树状分类\", \"信息组织结构\"], \"keyConceptEnList\": [\"Binary Decision\", \"Tree Classification\", \"Information Structure\"]}', '{\"enabled\": true, \"questions\": [{\"id\": 1, \"type\": \"single\", \"answer\": [0], \"points\": 10, \"source\": \"ai-tool\", \"options\": [\"让机器像人一样思考\", \"一种编程语言\", \"一种硬件设备\", \"一个操作系统\"], \"question\": \"什么是人工智能？\", \"createdAt\": \"2026-02-02 21:51:51\", \"optionsEn\": [\"Making machines think like humans\", \"A programming language\", \"A hardware device\", \"An operating system\"], \"updatedAt\": \"2026-02-02 21:51:51\", \"answerJson\": \"[0]\", \"customized\": false, \"isSelected\": true, \"questionEn\": \"What is Artificial Intelligence?\", \"optionsJsonarray\": \"[\\\"让机器像人一样思考\\\", \\\"一种编程语言\\\", \\\"一种硬件设备\\\", \\\"一个操作系统\\\"]\", \"optionsEnJsonarray\": \"[\\\"Making machines think like humans\\\", \\\"A programming language\\\", \\\"A hardware device\\\", \\\"An operating system\\\"]\"}, {\"