INSERT INTO `aiedu_classrooms` VALUES (13, 3, '认识人工智能', 'G3', '', '{\"id\": 1, \"icon\": \"Smile\", \"name\": \"人脸分析\", \"nameEn\": \"Face Analysis\", \"toolId\": \"see-face-analysis\", \"category\": \"see\", \"aiToolType\": \"recognition\", \"description\": \"观察 AI 如何理解人脸特征\", \"teachingGoal\": \"培养学生对 AI 识别能力的理解\", \"descriptionEn\": \"Observe how AI understands facial features\", \"teachingGoalEn\": \"Develop understanding of AI recognition\"}', '{\"id\": \"recv53KVmAHQDj\", \"grade\": \"G2\", \"title\": \"什么是人工智能？\", \"topic\": \"数字社会与未来：我们身边的智慧伙伴\", \"summary\": \"这是人工智能（AI）入门系列的第一课。学生将从日常经验出发，学会区分由人类制造的“人工”物品与自然界中生长的“天然”事物。在此基础上，学生将认识一种特殊的人工产物——人工智能。虽然 AI 是机器，但它可以“看”“听”并“做事”。通过比较人类与机器的行为，学生将开始理解 AI 是人类设计出来的、能够以“聪明”方式行动的工具。课堂包含图像分类游戏、人类感官与机器传感器的比较，以及绘画活动，帮助学生建立对 AI 的清晰第一印象。\", \"coverImage\": \"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U1_L1.jpg\", \"createTime\": \"2025-12-25\", \"lessonCode\": \"G2_T2_U1_L1\", \"lessonType\": \"通识课\", \"updateTime\": \"2026-02-04\", \"pptCanvaCode\": \"<div style=\\\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\\n border-radius: 8px; will-change: transform;\\\">\\n  <iframe loading=\\\"lazy\\\" style=\\\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\\\"\\n    src=\\\"https://education.braightidea.com/canva-design/DAGsMfX4GZU/G--lGpPP92I7PfbK2tZlKA/view?embed\\\" allowfullscreen=\\\"allowfullscreen\\\" allow=\\\"fullscreen\\\">\\n  </iframe>\\n</div>\\n<a href=\\\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGsMfX4GZU&#x2F;G--lGpPP92I7PfbK2tZlKA&#x2F;view?utm_content=DAGsMfX4GZU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\">G2下_U1_L1_Slides</a>，作者 宜斐\", \"keyConceptList\": [], \"keyConceptEnList\": []}', '{