ing\",\"Competition Items\",\"Research Practice\",\"Works Displayed\"]}]},\"sectionLearningSpaceHeader\":{\"title\":\"应用平台\",\"titleEn\":\"App Platform\",\"subtitle\":\"探索我们的 AI 学习体验\",\"subtitleEn\":\"Explore Our AI Learning Experience\"},\"sectionLearningSpace\":{\"modules\":[{\"id\":\"see\",\"title\":\"识别\",\"titleEn\":\"Recognize\",\"subtitle\":\"AI的视觉与感知\",\"subtitleEn\":\"AI Vision & Perception\",\"color\":\"#EA5347\",\"maskType\":\"svg\",\"svgPath\":\"pf1616f0\",\"image\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/a6438d242721690e0c092bd9bb58b8f26be6fc74.png\",\"items\":[{\"name\":\"识别中心\",\"nameEn\":\"Recognition Center\",\"icon\":\"Network\",\"action\":\"ai-recognition-tools\"},{\"name\":\"图像识别\",\"nameEn\":\"Image Recognition\",\"icon\":\"Image\",\"action\":\"image-recognition\"},{\"name\":\"人脸分析\",\"nameEn\":\"Face Analysis\",\"icon\":\"Smile\",\"action\":\"face-analysis\"},{\"name\":\"语音识别\",\"nameEn\":\"Speech Recognition\",\"icon\":\"Mic\",\"action\":\"speech-recognition\"},{\"name\":\"文字识别\",\"nameEn\":\"Text Recognition\",\"icon\":\"FileText\",\"action\":\"ocr\"}]},{\"id\":\"experience\",\"title\":\"体验\",\"titleEn\":\"Experience\",\"subtitle\":\"动手实践AI应用\",\"subtitleEn\":\"Hands-on AI Practice\",\"color\":\"#4097CE\",\"maskType\":\"rounded\",\"image\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/07062be095b361f3a665d8dded7c5b14cd7126f4.png\",\"items\":[{\"name\":\"看见声音\",\"nameEn\":\"See Sound\",\"icon\":\"Volume2\",\"action\":\"see-sound\"},{\"name\":\"你画我猜\",\"nameEn\":\"Draw & Guess\",\"icon\":\"Palette\",\"action\":\"drawing-game\"},{\"name\":\"指挥乐队\",\"nameEn\":\"Conduct Orchestra\",\"icon\":\"Music\",\"action\":\"conduct-orchestra\"}]},{\"id\":\"train\",\"\":\"\",\"title\":\"训练AI\",\"titleEn\":\"Train\",\"subtitle\":\"训练专属AI模型\",\"subtitleEn\":\"Train Your Own AI Model\",\"color\":\"#91C424\",\"maskType\":\"rounded\",\"image\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.co