\":\"隐私声明\",\"privacyEn\":\"Privacy Policy\",\"terms\":\"使用条款\",\"termsEn\":\"Terms of Use\",\"copyright\":\"©️和光未来（北京）文化科技发展有限公司    京ICP备16012345号\",\"copyrightEn\":\"©️ HeGuang Future (Beijing) Culture & Technology Development Co., Ltd.\",\"imageD\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/550886a562bd72ba7a4673706cdd09a917c7cf29.png\",\"imageR\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/eb596a327c2b14085a44c0820b4513c46fd0924a.png\",\"imageE\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/4109f440354cf014fc25470eee105a379247f768.png\",\"imageA\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/1e16d1fbce101de2374f32ccd8b9fd1ea3d389c2.png\",\"imageM\":\"https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/4d269a585521f3ea0184571b309b41f1cf24391d.png\"}}');

-- ----------------------------
-- Table structure for aiedu_inquiry
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_inquiry`;
CREATE TABLE `aiedu_inquiry`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '角色',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '咨询人名称',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '电话',
  `message` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '需求或问题',
  `school_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学校-学校名称',
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学校-咨询人职位',
  `school_size` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学校-学生人数',
  `interests_json` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学校-感兴趣的服务',
  `subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '老师-课题主题',
  `grade` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '老师-年级',
  `teacher_interests_json` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '老师-感兴趣的内容',
  `child_grade` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '家长-孩子当前年级',
  `learning_goal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '家长-希望孩子获得什么',
  `parent_interests_json` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '家长-感兴趣的内容',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_inquiry
-- ----------------------------


-- ----------------------------
-- Table structure for aiedu_literacy_class
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_literacy_class`;
CREATE TABLE `aiedu_literacy_class`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '飞书行id',
  `lesson_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程编号',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程名称',
  `title_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程名称-en',
  `grade` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '年级',
  `lesson_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程类型',
  `lesson_type_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程类型-en',
  `literacy` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '相关素养维度',
  `literacy_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '相关素养维度-en',
  `unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '单元',
  `summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程概述',
  `summary_en` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '课程概述-en',
  `key_concepts` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '关键词',
  `key_concepts_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '关键词-en',
  `topic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '单元名称',
  `topic_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '单元名称-en',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '封面图',
  `ppt_canva_code` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT 'PPT嵌入代码',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新日期',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = 'AI素养课程库' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_literacy_class
-- ----------------------------
INSERT INTO `aiedu_literacy_class` VALUES ('rec0RQ33Aw', 'G1_T1_U1_L1', '二叉树是如何工作的？', 'How Do Binary Trees Work?', 'G1', '通识课', 'General', '数据素养', 'Data Literacy', 'U1', '本课中，学生将探索如何使用二叉树这种简单而强大的工具，通过一系列是/否问题来组织信息。课堂首先以熟悉的物品和校园相关类别为例，全班共同构建一棵二叉树。然后，学生独立完成一份简短的练习单以巩固概念。最后，全班一起帮助老师整理一个“虚拟的凌乱房间”，通过将物品分类到 2–3 层的二叉树中完成整理。课后，学生将理解二元分类如何帮助我们做出决策、快速查找并保持有序。', 'In this lesson, students will explore how to use binary trees, a simple yet powerful tool, to organize information through a series of yes/no questions. The class begins with familiar items and campus-related categories as examples, and the whole class builds a binary tree together. Then, students independently complete a short exercise sheet to consolidate the concepts. Finally, the whole class helped the teacher organize a \"virtual messy room\" together, completing the organization by classifying the items into a binary tree of 2 to 3 levels. After class, students will understand how binary classification helps us make decisions, find things quickly and stay organized.', '二元决策；树状分类；信息组织结构', 'Binary Decision;Tree Classification;Information Structure', '看见结构：我们如何组织数据', 'Seeing Structure: How We Organize Data', 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U1_L1.png', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfYmv-oQ/B3_pjtGrGFxuH7SpcNhxqw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfYmv-oQ&#x2F;B3_pjtGrGFxuH7SpcNhxqw&#x2F;view?utm_content=DAGvfYmv-oQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('rec2AH4QNn', 'G1_T1_U1_L3', '网格是如何工作的？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '学生将探索我们如何使用网格（也称为表格或矩阵）来组织日常生活中的信息。通过贴近生活的例子，他们将开始理解行和列如何帮助我们整齐地查找和存储数据。课堂将创建并阅读简单的网格，练习这种新的信息观察方式。核心思想是理解网格是一种清晰且有用的数据组织工具。', NULL, '行列结构；网格组织；空间定位', NULL, '看见结构：我们如何组织数据', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U1_L3.png', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfYv4e_s/v6vjPs7DiQEjLlm_1Lp9UQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfYv4e_s&#x2F;v6vjPs7DiQEjLlm_1Lp9UQ&#x2F;view?utm_content=DAGvfYv4e_s&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U1_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recrmmxo8X', 'G1_T1_U1_L2', '我们如何进行排序？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '在这节实践课中，学生将探索如何用清晰的规则对物品进行排序，就像计算机那样。他们将先观察自己生活中如何整理物品（如玩具、衣服、零食），然后将这些方法应用到模拟简单的排序算法中。通过引导式的游戏与动作活动，学生将表演冒泡排序和插入排序的运作方式。核心概念是理解排序是由比较引导的、按步骤进行的过程。', NULL, '比较规则；顺序变化；排序过程', NULL, '看见结构：我们如何组织数据', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfbrC8rI/GuVGknEEiE61MMyGVB_DlQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfbrC8rI&#x2F;GuVGknEEiE61MMyGVB_DlQ&#x2F;view?utm_content=DAGvfbrC8rI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recuHS1ruy', 'G1_T1_U2_L1', '什么是地图？', NULL, 'G1', '通识课', NULL, '数字素养', NULL, NULL, '学生将探索“地图”作为表示真实空间的简单绘图的概念。以熟悉的校园为例，学生将思考如何用符号和形状展示大范围的空间。他们将绘制自己的简易校园地图，帮助理解核心概念：地图是现实空间的抽象版本。通过观察、讨论和绘画，学生将初步理解人们如何借助地图在不亲临其境的情况下了解地方。', NULL, '地图；俯视图；抽象表示', NULL, '地图：探索空间与路径', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U2_L1.png', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfSfJ_R0/ZTqCpfiOY_nbp5qIy0IvAw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfSfJ_R0&#x2F;ZTqCpfiOY_nbp5qIy0IvAw&#x2F;view?utm_content=DAGvfSfJ_R0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA0hqV', 'G4_T1_U4_L1', '网络上会有哪些骗局？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课引导学生调查常见的网络诈骗和欺骗手段，从钓鱼邮件、假网站到社会工程学骗局。学生将分析骗子如何操纵信任和情绪来窃取信息或金钱，并学习识别、避免和举报可疑网络行为的实用步骤。', NULL, NULL, NULL, '远离网络骗局', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuM5WGp8/EUhHuIKReNlGzj3mzGCqMg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuM5WGp8&#x2F;EUhHuIKReNlGzj3mzGCqMg&#x2F;view?utm_content=DAGvuM5WGp8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA0tfb', 'G2_T2_U2_L3', 'AI 如何识别人脸？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将探索 AI 系统如何通过关注面部特征点（如眼睛、鼻子、嘴的位置）来识别和辨认人脸。通过互动游戏、创意“拼脸”任务以及 AI 生成头像的实验，学生将体验机器是如何“看”人脸的，并将其与现实应用（如手机解锁、照片滤镜、游戏头像）联系起来。', NULL, NULL, NULL, 'AI 如何感知世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfdpvwzE/-kK9qZVTKg99JoW-PqBDRg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfdpvwzE&#x2F;-kK9qZVTKg99JoW-PqBDRg&#x2F;view?utm_content=DAGvfdpvwzE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1dXm', 'G6_T2_U6_L3', '制作你的地图之旅！——用ArcGIS StoryMaps把调研转化为精美在线故事', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '将收集的文化遗址资料转化为交互式地图旅行，完成地点组织、媒体上传、描述撰写与位置标记。', NULL, NULL, NULL, '规划、创建并展示你自己的虚拟旅行体验 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U6_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviQZxj6o/12XvNEKJuvL6mfIWiSSRjw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviQZxj6o&#x2F;12XvNEKJuvL6mfIWiSSRjw&#x2F;view?utm_content=DAGviQZxj6o&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U6_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1dYV', 'G1_T1_U3_L2', '谁属于同一组？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '学生将探索日常物品可以按相似性分组的概念。通过使用玩具或卡片的动手活动，学生将练习标记、排序和计数。目标是让学生理解物品可以用简单的规则和模式进行组织——就像计算机利用数据理解世界一样。本课为按特征分组、标记和记录数据打下基础。', NULL, '共同特征；分类规则；分组逻辑', NULL, '用数据看世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfaBMIoI/xNQoGhnNg7bVCl8iQmbHaw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfaBMIoI&#x2F;xNQoGhnNg7bVCl8iQmbHaw&#x2F;view?utm_content=DAGvfaBMIoI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1gOk', 'G1_T2_U2_L4', '设计你的算法——从给指令到解决问题', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课引导学生通过观察现实任务并将其转化为分步行动计划，探索“算法”概念。通过示例和引导练习，他们将用编号步骤和末尾检查设计并编写简单算法。这帮助学生理解顺序和验证是解决问题的关键，并将这种思维应用到日常情境，如整理书包或安全过马路。', NULL, '算法；输入–过程–输出；检查与验证', NULL, '像程序员一样思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfbAcjo8/yHb-O_xmZxb_z9U0FsrfUg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfbAcjo8&#x2F;yHb-O_xmZxb_z9U0FsrfUg&#x2F;view?utm_content=DAGvfbAcjo8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1K0u', 'G6_T2_U4_L1', '从展馆到舞台——沉浸式体验文化：虚拟、增强与混合现实如何让博物馆和表演“活”起来', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '介绍XR（AR、VR、MR）在展览与表演中的应用，通过案例与AR涂色活动理解沉浸式设计及其在旅游、教育、艺术等领域的潜力。', NULL, NULL, NULL, '在现实中穿行——探索XR中的文化与交互 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviVHMtMI/ks6wAozdIq1-2f-U_G41cA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviVHMtMI&#x2F;ks6wAozdIq1-2f-U_G41cA&#x2F;view?utm_content=DAGviVHMtMI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1Lc4', 'G6_T2_U3_L2', '让你的角色动起来、开口说话！——学习AI如何赋予角色语言与动作', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '学习文本转语音、动作捕捉、面部表情追踪三大技术，通过小组设计脚本与动作，利用AI工具预览角色表现。', NULL, NULL, NULL, 'AI如何让3D角色“活”起来？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviS1_goA/LGNRGDLzbCL0Y1hmAugQ8Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviS1_goA&#x2F;LGNRGDLzbCL0Y1hmAugQ8Q&#x2F;view?utm_content=DAGviS1_goA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1nlf', 'G6_T1_U3_L2', '自动驾驶车辆如何做出驾驶决策？——从感知环境到采取行动', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生探讨自动驾驶从感知到决策的流程，体验“识别-评估-行动”三个步骤，并通过案例理解决策在不同交通情境中的应用。', NULL, NULL, NULL, '自动驾驶 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviAUwoSg/HcVM9dCf_svtsRGDQjJn4w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviAUwoSg&#x2F;HcVM9dCf_svtsRGDQjJn4w&#x2F;view?utm_content=DAGviAUwoSg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1OlB', 'G7_T2_U1_L3', 'AI的先驱与突破性时刻——关键里程碑如何塑造人工智能', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '探索塑造AI历史的关键人物与里程碑事件，从图灵测试到AlphaGo与ChatGPT；通过讨论与课堂图灵测试活动，理解技术进步与个人贡献的关系。', NULL, NULL, NULL, '人工智能历史之旅 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvitfS3Zc/Y7Cq8QRkCYRJUCA3pcSC7w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvitfS3Zc&#x2F;Y7Cq8QRkCYRJUCA3pcSC7w&#x2F;view?utm_content=DAGvitfS3Zc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U1_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA1vfx', 'G1_T2_U2_L1', '按步骤来——从日常习惯到顺序结构', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课引导学生探索“顺序”的概念——按照正确的顺序做事。通过观察生活实例和分步演示日常流程，学生将理解计算机和机器如何像人类一样一条一条地执行指令。他们会通过“洗衣机”活动和简单代码编写任务来模拟这种逻辑。', NULL, '顺序；指令逻辑', NULL, '像程序员一样思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfY7qy1Y/ODz0EmFxIXDcp293ZAHczw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfY7qy1Y&#x2F;ODz0EmFxIXDcp293ZAHczw&#x2F;view?utm_content=DAGvfY7qy1Y&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA2KBV', 'G6_T1_U1_L3', '人工智能在智慧城市中的应用——更美好的生活，更智慧的未来', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生探索人工智能在交通、能源管理、废物管理、公共安全、医疗、城市规划、市民参与七大领域的应用，了解AI如何通过数据分析改善城市生活，并思考隐私与数据安全等社会议题。', NULL, NULL, NULL, '智慧社会与人工智能 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviItzpaU/E7XB-o6LZOjdAmqcZzkPGw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviItzpaU&#x2F;E7XB-o6LZOjdAmqcZzkPGw&#x2F;view?utm_content=DAGviItzpaU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U1_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA2Lxg', 'G7_T2_U3_L4', '探索我在AI时代的未来职业——未来我会在哪里？', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '结合个人优势、兴趣与新兴技术设计未来职业，用绘画或Canva可视化职业设想并展示，深化职业与技术关系的理解。', NULL, NULL, NULL, 'AI时代的未来工作 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZWjMqxQ/zsXqAWwTpbze28seTZMs6A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZWjMqxQ&#x2F;zsXqAWwTpbze28seTZMs6A&#x2F;view?utm_content=DAGvZWjMqxQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA2MHB', 'G3_T2_U3_L2', '如何在不同模型中做选择？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索为什么要用不同模型解决不同问题。他们将比较两种模型：决策树模型（使用是/否规则）和模式预测模型（预测序列中的下一步）。通过现实演示、个人练习单和趣味挑战，学生会认识到最佳模型取决于问题和可用数据。核心理念：没有一种模型适用于所有情况——选择合适的模型很重要。', NULL, NULL, NULL, '模式识别与分类逻辑', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfhmOhxE/w-PymvIT6TAIWTjybAmOEg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfhmOhxE&#x2F;w-PymvIT6TAIWTjybAmOEg&#x2F;view?utm_content=DAGvfhmOhxE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA3I59', 'G5_T1_U1_L2', 'AI 的大脑——芯片、计算与处理', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探究 AI 的“大脑”——处理器。在第一课“感知–表征–推理”链条的基础上，他们将学习三种主要处理器类型（CPU、GPU、MCU）、它们的功能以及如何让 AI“思考”。学生将比较这些处理器在速度、能耗和应用上的差异，并探讨 AI 如何通过规则或学习模式做出决策。课程以“AI 是否真的会思考”的讨论收尾，并为下一主题——AI 的“神经系统”——做好准备。', NULL, NULL, NULL, '硬核 AI——AI 硬件与基础设施', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh-F51PE/DXJFXajjycIY-2ogCHAydQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh-F51PE&#x2F;DXJFXajjycIY-2ogCHAydQ&#x2F;view?utm_content=DAGvh-F51PE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA3m5y', 'G7_T2_U2_L4', 'AI的红线与价值对齐——为AI与人类使用划定边界', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '探索AI红线与价值对齐，分析文化差异对AI决策的影响；通过视频与讨论理解不同价值取向带来的差异，并反思未来人机共存。', NULL, NULL, NULL, '现实世界中的AI系统：逻辑、协作与边界 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvinGh2Ro/oW2hLrMn2AWru5xaFAYx6g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvinGh2Ro&#x2F;oW2hLrMn2AWru5xaFAYx6g&#x2F;view?utm_content=DAGvinGh2Ro&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA3M6p', 'G4_T2_U2_L4', '信息越多越好吗？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课通过“挑选运动鞋的困难”和“短视频上瘾”的案例，引导学生认识信息过载的三大危害（精神疲劳、注意力下降、记忆力减退），并提出多样化推荐作为解决方案。学生将在“信息餐盘”设计活动中培养健康管理信息的能力。', NULL, NULL, NULL, '推荐算法与信息过滤', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf1AFHRQ/UwDM8lUJVk4tmx5vRAjQ7g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf1AFHRQ&#x2F;UwDM8lUJVk4tmx5vRAjQ7g&#x2F;view?utm_content=DAGvf1AFHRQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA4DYz', 'G2_T2_U2_L1', 'AI 如何看见？——图像基础', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课向学生介绍人工智能（AI）是如何看待图片的——并不是完整的画面，而是由称为像素的小点组成的。通过有趣的动手活动，学生将探索每一张数字图片其实都是由大量彩色方块构成的。他们将制作并解码简单的像素图像，理解计算机和 AI 如何将图片转化为数字。本课为理解数字图像和基础图像编码奠定基础。', NULL, NULL, NULL, 'AI 如何感知世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfWep4oA/GdwpO3zFK7ErrBfqWEd2hg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfWep4oA&#x2F;GdwpO3zFK7ErrBfqWEd2hg&#x2F;view?utm_content=DAGvfWep4oA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA4qm1', 'G1_T2_U3_L5', '设计交互故事——用积木让故事动起来！', NULL, 'G1', '项目课', NULL, 'CS素养', NULL, NULL, '本课以外星机器人 Toc 的冒险故事为载体，引导学生用 ScratchJr 设计交互式叙事程序。学生将独立编写故事、设计角色与舞台，并创建交互环节，把冰冷的积木变成温暖的交互故事，成长为能用“事件驱动 + 创意表达”思考与表达的小小数字创作者。', NULL, '交互触发事件；场景设计；叙事编程', NULL, '用 ScratchJr 探索编程', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U3_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvftNS8lU/gvBR9npSyUuVJ8YyDG25Og/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvftNS8lU&#x2F;gvBR9npSyUuVJ8YyDG25Og&#x2F;view?utm_content=DAGvftNS8lU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U3_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA4tYq', 'G2_T1_U3_L1', '计算机如何感知世界？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课将人类的感官（视觉、听觉、触觉、嗅觉、味觉）与计算机的传感器进行比较，帮助学生理解感知是获取数据的第一步。课程建立这样的意识：没有传感器，计算机无法“看”或“听”——所有数据都必须先从外部世界采集。', NULL, NULL, NULL, '从数据到行动——计算机如何工作', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuDj6FcrI/apQJ3HuW8GpsHws1kIrUIw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuDj6FcrI&#x2F;apQJ3HuW8GpsHws1kIrUIw&#x2F;view?utm_content=DAGuDj6FcrI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U3_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA53h7', 'G5_T1_U3_L1', '输入有偏见，输出也有偏见——在不公平的世界里，机器能公平吗？', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将通过“输入有偏见，输出有偏见”的概念探索 AI 如何再现人类偏见。通过视觉化的 AI 生成示例，他们将观察性别与种族刻板印象如何源于有偏见的训练数据。学生将学习 AI 如何从数据中学习、偏见为何产生，并探讨三种主要的偏见修复策略及其优缺点。课程以开放式反思收尾：修复 AI 偏见是改变了世界，还是仅仅让它看起来更公平？', NULL, NULL, NULL, 'AI 与伦理：成为批判性 AI 思考者', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviLGEdPM/L23-yBMHXPuBThvvaP_jbg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviLGEdPM&#x2F;L23-yBMHXPuBThvvaP_jbg&#x2F;view?utm_content=DAGviLGEdPM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA5ysd', 'G4_T2_U2_L2', '你和别人相似吗？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课通过零食口味评比的案例，引导学生寻找口味相同的同学。在统计偏好的过程中，学生将接触并理解评分矩阵和用户相似度等概念，并在实践中以喜爱的书籍为例，寻找阅读偏好相似的同学，发现志同道合的朋友。', NULL, NULL, NULL, '推荐算法与信息过滤', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf-cuGo8/vkFscHCEvhTn01hG3OX98g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf-cuGo8&#x2F;vkFscHCEvhTn01hG3OX98g&#x2F;view?utm_content=DAGvf-cuGo8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA6e3w', 'G4_T1_U5_L5', '打磨你的初稿——用 Midjourney 创作更好的图片', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将学习如何使用 Midjourney 优化绘本插图。通过教师演示与动手练习，他们将掌握如何撰写更详细的提示词、应用风格与角色参考，并生成高质量、视觉一致的图片。学生还将学习如何向 ChatGPT 寻求帮助以更清晰地组织提示词。课末，学生将保存每个故事场景的首选图片，为下一课的绘本排版做好准备。', NULL, NULL, NULL, '用 AI 讲故事：从想象到插画', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U5_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh5CjoSY/YBR0vsGwKy_J_nAZzZevCQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh5CjoSY&#x2F;YBR0vsGwKy_J_nAZzZevCQ&#x2F;view?utm_content=DAGvh5CjoSY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U5_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA7BdT', 'G6_T2_U2_L2', 'AI如何帮助我们重建过去——从图像修复到文化遗产重构', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学习AI在图像修复、艺术风格迁移、虚拟重建中的作用，观察真实案例并亲自体验AI艺术工具，探讨修复历史的准确性、创造性与责任感。', NULL, NULL, NULL, '用人工智能让历史重现', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviFtRaQQ/GQJiB1PtknV9HWukiSoCkQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviFtRaQQ&#x2F;GQJiB1PtknV9HWukiSoCkQ&#x2F;view?utm_content=DAGviFtRaQQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA7D7E', 'G7_T2_U4_L3', '我如何改进我的简历？', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '学习简历优化策略并应用到个人简历，通过同伴反馈、引导编辑与ChatGPT辅助修改，提高语言、结构与影响力。', NULL, NULL, NULL, '数字简历', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZdmP6oM/Et05TBSfOOPptVunJDPJPg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZdmP6oM&#x2F;Et05TBSfOOPptVunJDPJPg&#x2F;view?utm_content=DAGvZdmP6oM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U4_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA7pXB', 'G4_T1_U1_L2', '线上我和真实的我是同一个吗？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '我们很多人都曾在网上搜索过自己或他人。当你查找某个人时，会出现什么？可能是他们的社交媒体账号、照片、视频，甚至是别人分享的关于他们的内容。这些信息组成了他们的数字档案。', NULL, NULL, NULL, '认识我的线上自我', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuIPpQrs/5gBouV2o8c9eBddHi4-9EQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuIPpQrs&#x2F;5gBouV2o8c9eBddHi4-9EQ&#x2F;view?utm_content=DAGvuIPpQrs&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8cA4', 'G4_T1_U1_L1', '我在线上是谁？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '当我们上网时，总会创造一个“迷你版的自己”，就像游戏中的角色。这个小小的虚拟版本被称为“线上自我”或“数字自我”，它就像一个资料卡或头像，向他人展示我是谁，就像现实生活中人们认识我一样。', NULL, NULL, NULL, '认识我的线上自我', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuIbOyAU/pWHoqxi7tvKTeKHACZI71Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuIbOyAU&#x2F;pWHoqxi7tvKTeKHACZI71Q&#x2F;view?utm_content=DAGvuIbOyAU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8iBC', 'G4_T2_U3_L1', '像专家一样搜索——用关键词找到准确信息', NULL, 'G4', '通识课', NULL, NULL, NULL, NULL, '本课引导学生掌握关键词搜索技巧，比较好与差的搜索案例，练习构建更优搜索语句，并探索搜索引擎的工作原理。通过生活化情境，学生理解增加细节和选择恰当关键词的重要性。', NULL, NULL, NULL, '从搜索到结构化：掌握信息技能', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfwZMKlU/yjbreG1qHvNJ7cf_7cB_cQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfwZMKlU&#x2F;yjbreG1qHvNJ7cf_7cB_cQ&#x2F;view?utm_content=DAGvfwZMKlU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8pqh', 'G5_T1_U2_L8', '上传与激活——让 Steve 运行起来', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将向 Steve 上传控制程序，激活其 AI 驱动的垃圾分类功能。他们将按照检查清单验证语音响应、AI 摄像头启动与舵机动作，并用不同物体进行压力测试。学生还将练习系统化调试，以识别并修复硬件、软件或逻辑问题。该课为下一节的最终物理组装做准备。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L8.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviDPfVL4/5gKphX6a2N08A_WKO8fQRg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviDPfVL4&#x2F;5gKphX6a2N08A_WKO8fQRg&#x2F;view?utm_content=DAGviDPfVL4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L8_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8ryn', 'G4_T1_U5_L4', '让故事动起来——用 AI 创作场景', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '学生将把故事拆分为多个场景，并借助 ChatGPT 和 DALL·E 创作插图。他们将学习什么是“场景”、如何在不同页面保持视觉风格一致，以及如何用提示词与 AI 协作生成图片。本课强调理解叙事结构、练习描述性写作，并认识到视觉一致性的重要性。', NULL, NULL, NULL, '用 AI 讲故事：从想象到插画', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U5_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh3k18Js/sI2jg2VcdeZ585_u8ARQsw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh3k18Js&#x2F;sI2jg2VcdeZ585_u8ARQsw&#x2F;view?utm_content=DAGvh3k18Js&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U5_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8Tho', 'G4_T2_U3_L4', '从搜索到结构化——整理你的发现', NULL, 'G4', '通识课', NULL, NULL, NULL, NULL, '本课教授学生如何用清晰、有逻辑的方式整理研究结果，介绍分类、思维导图和总结表三种方法，并以“火山”为示例对比不同方法的特点，最后将所学应用于“哪吒传奇”的研究任务。', NULL, NULL, NULL, '从搜索到结构化：掌握信息技能', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf9cQZKI/5XNdmweRIWYlhyQCuTAZnQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf9cQZKI&#x2F;5XNdmweRIWYlhyQCuTAZnQ&#x2F;view?utm_content=DAGvf9cQZKI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8tOu', 'G1_T2_U2_L5', '图案挑战——帮小精灵找到家人！', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课通过有趣的小精灵故事，引入三种视觉图案类型：重复、对称和递增。学生将观察示例、识别图案类型，并基于理解设计自己的徽章图案。', NULL, '重复模式；对称；递增模式', NULL, '像程序员一样思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U2_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfb2CAB0/a9UwcDI83BBXqs7SpJBaXw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfb2CAB0&#x2F;a9UwcDI83BBXqs7SpJBaXw&#x2F;view?utm_content=DAGvfb2CAB0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U2_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA8V0O', 'G3_T1_U1_L1', '什么是数据——走近红树林之星', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课通过引导学生观察和记录现实世界信息，帮助他们认识“数据”这一概念。故事情境设定在深圳红树林湿地，学生在探访中遇见黑脸琵鹭，并将自己的观察转化为结构化数据。本课帮助学生理解什么是数据、如何收集数据以及数据的用途。学生将练习识别、整理和展示现实生活中的数据。', NULL, NULL, NULL, '用数据理解世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGsws8JRSg/FzWDKHv_j1craB9_htZTOw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGsws8JRSg&#x2F;FzWDKHv_j1craB9_htZTOw&#x2F;view?utm_content=DAGsws8JRSg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U1_L1_Slides</a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmA9f1V', 'G4_T1_U3_L3', '应用收集了我的哪些个人信息？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '在本节课中，学生将从案例分析转向实际操作。他们会探索不同应用收集的个人数据——包括国外的 YouTube，以及国内的微信、淘宝和小红书。从 YouTube 的 “Your Data in YouTube” 页面开始，学生将看到他们的观看历史、搜索历史和订阅是如何被记录和利用的。随后，他们会调查国内常见应用的数据收集情况。在教师引导下，学生将理解：应用收集了哪些个人数据、这些数据如何被使用、以及我们如何管理自己的隐私。', NULL, NULL, NULL, '数字足迹与数据隐私', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuGR3yUQ/belL_7g0Og5WW9dhnWjP1Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuGR3yUQ&#x2F;belL_7g0Og5WW9dhnWjP1Q&#x2F;view?utm_content=DAGvuGR3yUQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U3_L3_Slides </a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAa0yn', 'G1_T2_U3_L1', '视觉化编程入门', NULL, 'G1', '项目课', NULL, 'CS素养', NULL, NULL, '本课向学生介绍视觉化编程的概念及 ScratchJr 界面。他们将探索界面的五个主要区域，学习添加和更改角色与背景，并了解如何调整角色大小。通过引导活动，学生将为下一节课设计一个简单的迷你故事场景。本课帮助学生理解可视化编程工具的“所见即所得”特性，为编程奠定基础。', NULL, '图形化编程；界面结构；角色与舞台', NULL, '用 ScratchJr 探索编程', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfkwTKqk/6HBsvhHgCepVOlDiREwd2g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfkwTKqk&#x2F;6HBsvhHgCepVOlDiREwd2g&#x2F;view?utm_content=DAGvfkwTKqk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAaefM', 'G4_T1_U2_L2', '什么是个人数据？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课帮助学生理解每一次线上行为都会留下数字足迹，并可能影响自己和他人。通过现实案例讨论、视频、测验和自我反思，学生将探讨“人肉搜索”、数字永久性和线上责任感。目标是提升学生的线上身份意识，并鼓励他们养成负责任的数字行为习惯。', NULL, NULL, NULL, '了解与保护私人信息', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuEJSVtA/fHfa6IG4wNs-kd9WkBkK2A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuEJSVtA&#x2F;fHfa6IG4wNs-kd9WkBkK2A&#x2F;view?utm_content=DAGvuEJSVtA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAAkvR', 'G1_T1_U3_L1', '什么是标记与匹配？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '学生将探索我们如何用标签来组织和查找物品。通过图片卡片和生活实例，学生将练习按颜色、形状或类型分组，并理解标记对于组织信息的重要性——尤其是在处理计算机和图片时。核心概念是标签如何帮助我们更容易地描述、分组和搜索数据。', NULL, '标签；特征分类；匹配规则', NULL, '用数据看世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfVOyQKI/Vz9jwFaMeruc4bDQQEOmZQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfVOyQKI&#x2F;Vz9jwFaMeruc4bDQQEOmZQ&#x2F;view?utm_content=DAGvfVOyQKI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAANcm', 'G7_T1_U5_L1', '用AI策划信息——每天发生这么多事，如何告诉别人？', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '本课是四节项目制学习（PBL）课程中的第一节，学生将探索AI如何支持他们制作校刊。在本节中，学生将学习如何用AI和自己的文字总结新闻，评估AI生成内容，并开始建立新闻素材池，为下一节课做准备。', NULL, NULL, NULL, '我们的声音，我们的新闻：AI驱动', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U5_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZY23V6c/lFqACGTth5MebDapCvFqXw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZY23V6c&#x2F;lFqACGTth5MebDapCvFqXw&#x2F;view?utm_content=DAGvZY23V6c&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U5_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAarcc', 'G1_T2_U1_L4', '设计你的逻辑路径——学会写规则', NULL, 'G1', '通识课', NULL, '设计思维', NULL, NULL, '在本单元的最后一课中，学生将化身逻辑设计师，运用所学的布尔值、逻辑运算符和条件语句，创建自己的基于规则的冒险地图。他们先挑战“魔法逻辑”任务，再设计和绘制带有逻辑检查点的地图，让同学尝试闯关。本课通过创意性、同伴互动的项目，巩固逻辑思维、规则编写和决策能力。', NULL, '逻辑表达式；多条件组合；规则设计', NULL, '用逻辑聪明思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U1_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfWnuIpc/pkR3hkF1yRc2AVVzt4bIiA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfWnuIpc&#x2F;pkR3hkF1yRc2AVVzt4bIiA&#x2F;view?utm_content=DAGvfWnuIpc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U1_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAb25G', 'G2_T1_U3_L2', '计算机能理解什么？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课将向学生介绍计算机中常用的三种基本数据类型：字符串（文本）、数字和真/假值（布尔值）。通过分类游戏、卡片归类和现实类比，学生将学习这些数据类型是所有计算机程序的构建基石。课程还鼓励学生思考：计算机如何“理解”信息？它不能真正理解什么？它能处理什么？', NULL, NULL, NULL, '从数据到行动——计算机如何工作', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuOwCZ6Do/dDm_MaNC7GvxJxLoK6J8gg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuOwCZ6Do&#x2F;dDm_MaNC7GvxJxLoK6J8gg&#x2F;view?utm_content=DAGuOwCZ6Do&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U3_L2_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAbaWV', 'G3_T1_U2_L1', 'PPDAC 模型——用数据解决问题的聪明方法', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课向学生介绍 PPDAC 模型——一种用数据解决现实问题的简单而聪明的方法。通过“糖果谜案”和“零食小队”的故事情境，学生学习如何确定问题、规划数据收集、收集并分析数据，并根据发现做出决策。本课以有趣、适龄的方式建立数据探究流程的基础理解。', NULL, NULL, NULL, '用数据解决问题', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGt2VHWQnk/KKe14WKq3_2Erioee_xHMQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGt2VHWQnk&#x2F;KKe14WKq3_2Erioee_xHMQ&#x2F;view?utm_content=DAGt2VHWQnk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U2_L1_Slides</a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAboIe', 'G2_T1_U4_L1', '我们如何连接到互联网？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索设备是如何连接到互联网的。以“给奶奶发照片”的日常情景为切入点，他们将开始理解数据是如何从自己的设备传输到远方的。通过观察、卡片配对和数据路径拼图游戏，学生将初步认识互联网连接的基本组成部分——如手机、Wi-Fi、路由器、光纤、电缆和服务器——并形成关于信息如何在网络中传递的心智模型。核心思想是：互联网不是魔法，它通过现实世界中的路径来工作。', NULL, NULL, NULL, '互联网与通信', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvEma6IvI/tJkQUzY-0G2Ug5wX1AU--Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvEma6IvI&#x2F;tJkQUzY-0G2Ug5wX1AU--Q&#x2F;view?utm_content=DAGvEma6IvI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U4_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmABQ9n', 'G2_T2_U4_L3', 'AI 如何找路？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将探索 AI 如何通过路径搜索和地图查找来决定最佳路线。通过动手游戏，学生将引导机器人在地图中找到回家的最短、安全路线。他们将使用小地图和问题解决步骤来理解 AI 如何规划路径，就像 GPS 或送货机器人一样。本课通过简单贴近生活的挑战，向孩子介绍 AI 的路径规划概念。', NULL, NULL, NULL, 'AI 如何思考与决策', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfhkC8V0/SfMZtpNGsDKm_Vy5V54Gvg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfhkC8V0&#x2F;SfMZtpNGsDKm_Vy5V54Gvg&#x2F;view?utm_content=DAGvfhkC8V0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U4_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAbUOc', 'G5_T2_U2_L1', '用户与市场', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课探索产品管理的基础：理解用户与市场。学生将学习产品的定义（用户+问题=产品），区分真正的产品与业余爱好，并练习识别用户需求。最终每组将产出四项关键调研成果——用户画像、情景设计、问题陈述和痛点洞察，为下一阶段的产品设计做好准备。', NULL, NULL, NULL, '做老板：成为产品经理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJbi_YU/r-gxHxJirCpwvu3DGlfP-A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJbi_YU&#x2F;r-gxHxJirCpwvu3DGlfP-A&#x2F;view?utm_content=DAGviJbi_YU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAC9hd', 'G6_T1_U1_L1', '智慧城市：一种全新的生活与出行方式——更智慧的城市，更美好的生活', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '本课向学生介绍智慧城市的概念，并探讨数字技术如何改善城市运作方式。通过视频分析和真实案例，学生将了解智慧城市的主要应用领域（交通、医疗、能源、废物管理），并理解这些技术如何应对日常城市挑战。', NULL, NULL, NULL, '智慧社会与人工智能 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviD-rKh4/G2oCCsrYnKE2VvREkK5evg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviD-rKh4&#x2F;G2oCCsrYnKE2VvREkK5evg&#x2F;view?utm_content=DAGviD-rKh4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcabI', 'G1_T2_U2_L2', '给出明确指令——让你的机器人动起来！', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课中，学生将探索如何用精确的指令与机器交流。他们会了解到计算机和机器人不会“猜”我们的意思——它们只会执行明确、有结构的指令。本课介绍优质指令的三要素：动作、对象和数量，并强调顺序的重要性。学生将通过角色扮演和可视化编程练习发出和执行指令，为算法思维和基础编程逻辑打下坚实基础。', NULL, '指令；顺序执行', NULL, '像程序员一样思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfdR_QPg/xNDhcK-qmplhLAsNSWlEOg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfdR_QPg&#x2F;xNDhcK-qmplhLAsNSWlEOg&#x2F;view?utm_content=DAGvfdR_QPg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcbP0', 'G2_T2_U2_L4', 'AI 如何听到声音？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索人工智能（AI）如何听取声音并识别声音中的模式。通过听觉体验和绘画活动，学生将学习声音可以被看作称为声波和频谱的图形和形状。通过比较不同的声音，他们将开始理解 AI 是如何区分声音的。核心思想是 AI 并不是用“耳朵”听，而是通过识别声波的模式和变化来听。', NULL, NULL, NULL, 'AI 如何感知世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfVmEzHc/qLXvecxR-8Ats3aDa8g0kg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfVmEzHc&#x2F;qLXvecxR-8Ats3aDa8g0kg&#x2F;view?utm_content=DAGvfVmEzHc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcfs8', 'G2_T1_U2_L4', '计算机如何保存一切？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将学习计算机如何使用“比特积木”和“数字背包”的比喻来存储不同类型的信息。他们将理解不同文件占用的空间不同，并且存储是有限的。通过角色扮演和动手活动，学生将体验信息的选择过程，获得理解 AI 和计算机如何管理内存的基础概念。', NULL, NULL, NULL, '计算机基础', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGu53pBAwM/KEU0sGrEvTYxAymjNWvtRw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGu53pBAwM&#x2F;KEU0sGrEvTYxAymjNWvtRw&#x2F;view?utm_content=DAGu53pBAwM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U2_L4_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcFu2', 'G5_T2_U2_L3', '团队与项目——谁做什么，何时做？', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '学生将学习创建产品是一个协作过程。他们将了解五种关键产品开发角色，理解互补技能的重要性，并制定简单的项目时间表来组织工作。通过 smartWork 案例，学生将看到清晰的团队分工、任务拆解和结构化沟通如何确保按时交付。最终每组将分配好团队角色并完成迷你项目进度表，以指导下一阶段的原型构建与测试。', NULL, NULL, NULL, '做老板：成为产品经理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJ_YclA/2CfU0JPKiQghQVS3R-s2LA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJ_YclA&#x2F;2CfU0JPKiQghQVS3R-s2LA&#x2F;view?utm_content=DAGviJ_YclA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcKR2', 'G7_T1_U3_L1', '文字背后的秘密——自然语言处理与社会洞察', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课带领学生探索计算机如何理解人类语言，以及这如何影响我们与信息的互动。在理解假新闻与算法影响的基础上，本课介绍自然语言处理（NLP）的基础知识——它是搜索引擎、语音助手和AI内容分析背后的核心技术。学生将通过互动活动与真实案例学习人类与计算机如何理解文本、识别关键信息并解读含义，同时批判性思考NLP在语气、讽刺或文化差异上的局限性。', NULL, NULL, NULL, '自然语言处理与社会洞察', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviQeGhQE/5WaahekAuYOYcciyG3EOdQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviQeGhQE&#x2F;5WaahekAuYOYcciyG3EOdQ&#x2F;view?utm_content=DAGviQeGhQE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcLoE', 'G1_T2_U3_L4', '让它运行——查找并修复程序中的 Bug！', NULL, 'G1', '项目课', NULL, 'CS素养', NULL, NULL, '学生将化身“小小编程巫师”，通过解决魔法森林中的异常事件（失控的小猪、失败的魔法咒语）学习程序调试的核心概念。课程以游戏化任务驱动，引导学生通过“发现 Bug → 分析原因 → 修改代码 → 验证结果”的闭环过程培养计算思维与问题解决能力。', NULL, '调试；错误定位；指令修正', NULL, '用 ScratchJr 探索编程', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfi3dc2k/EnHBaWLSY3NxnwUME6hnsQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfi3dc2k&#x2F;EnHBaWLSY3NxnwUME6hnsQ&#x2F;view?utm_content=DAGvfi3dc2k&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmACSER', 'G7_T2_U4_L4', '展示自我', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '模拟面试式自我展示，运用优化后的简历介绍个人优势与目标，通过展示技巧与同伴反馈提升沟通与自我呈现能力。', NULL, NULL, NULL, '数字简历', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZbW7d54/jKrzwZlWORF6CKj1nvGIqA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZbW7d54&#x2F;jKrzwZlWORF6CKj1nvGIqA&#x2F;view?utm_content=DAGvZbW7d54&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U4_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcw2g', 'G5_T1_U3_L2', '工具还是裁判？——AI 应（不应）做什么，谁来决定，人类还是机器？', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '本课探讨 AI 作为有用工具与 AI 作为决策裁判的界限。学生将通过问卷调查判断自己何时信任 AI，比较 AI 协助与 AI 决策的场景，并分析“责任网络”来绘制责任归属图。社交媒体推荐的案例研究帮助学生将 AI 对信息的影响与现实世界的伦理问题联系起来。', NULL, NULL, NULL, 'AI 与伦理：成为批判性 AI 思考者', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviNFDO9Y/qF7K9wV2ZXb3AKczc3SaQw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviNFDO9Y&#x2F;qF7K9wV2ZXb3AKczc3SaQw&#x2F;view?utm_content=DAGviNFDO9Y&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmACxA2', 'G6_T1_U2_L3', '红绿灯也能变聪明！——探索自适应控制与多智能体协作', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生了解传统信号与智慧信号的区别，探索如 SURTRAC 系统的实时数据与路口协作模式，并通过小组模拟对比独立决策与协同决策的效果。', NULL, NULL, NULL, '智慧交通', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJ0atR4/HfXd6CcovRPQgb6aFKLYAw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJ0atR4&#x2F;HfXd6CcovRPQgb6aFKLYAw&#x2F;view?utm_content=DAGviJ0atR4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAcy77', 'G3_T1_U3_L1', '开一家巧克力店——是什么让人想买巧克力？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课以巧克力品牌世界作为有趣的切入口，引导学生进入数字素养学习。在探索“是什么让巧克力品牌吸引人”时，学生将开始识别优秀产品设计、顾客偏好和用户体验的要素。这些观察将为后续的数据收集、分析和决策课程奠定基础。课末，学生将制作一份视觉品牌板，表达自己关于产品、受众和展示的初步想法——这是建立数据驱动思维的关键组成部分。', NULL, NULL, NULL, '智能巧克力工坊：用数据设计', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGsYqCVocg/_WQvszLLJqYbsBSAEvySaA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGsYqCVocg&#x2F;_WQvszLLJqYbsBSAEvySaA&#x2F;view?utm_content=DAGsYqCVocg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U3_L1_Slides</a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAdJBs', 'G5_T1_U2_L5', '训练 Steve——用真实数据教 Steve 识别垃圾', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将使用真实世界的图像数据和 KNN 算法训练他们的智能垃圾分类机器人 Steve。他们将复习 KNN 的工作原理，准备标注数据集（如电池和易拉罐），将 HuskyLens AI 摄像头连接到 Mind+ 平台，并将训练好的模型部署到设备上。最后，他们将测试模型的实时预测并反思其准确性，为下一节 Steve 硬件组装做好准备。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviPvrBkQ/ClkPh08RN2_fnMAhc9yOYQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviPvrBkQ&#x2F;ClkPh08RN2_fnMAhc9yOYQ&#x2F;view?utm_content=DAGviPvrBkQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAdRNI', 'G4_T1_U5_L1', '你的创意伙伴——AI 在创作中能做什么？', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课探讨 AI 是否具备创造力。学生将发现 AI 如何创作诗歌、绘画、音乐和视频，以及 AI 如何理解人类语言。课堂将包含互动挑战，例如猜测 AI 创作的诗歌和用成语难倒 AI。', NULL, NULL, NULL, '用 AI 讲故事：从想象到插画', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U5_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvhwq8_ls/16hmp8zSMuJl41LTZOkMkA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvhwq8_ls&#x2F;16hmp8zSMuJl41LTZOkMkA&#x2F;view?utm_content=DAGvhwq8_ls&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U5_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAdRV0', 'G3_T2_U3_L1', '什么是决策树？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课向学生介绍“决策树”概念——一种用是/否问题来组织想法或物体的方式。通过真实案例（自动售货机、电梯、机器人）和小组活动，学生将学习决策树如何帮助计算机（和人类）逐步做出聪明的决定。他们会看到每一次“是/否”回答都会分叉路径，直到找到正确答案。', NULL, NULL, NULL, '模式识别与分类逻辑', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfu5avBw/s-_OMX5GmoYRHXEoptJm3g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfu5avBw&#x2F;s-_OMX5GmoYRHXEoptJm3g&#x2F;view?utm_content=DAGvfu5avBw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAE1Hw', 'G2_T2_U2_L2', 'AI 如何看世界？——认识 AI 能做什么', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课聚焦 AI 感知，特别是图像识别与特征理解。学生将探索手机如何识别照片，并通过动手活动理解“感知”是 AI 的基本能力之一。', NULL, NULL, NULL, 'AI 如何感知世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGmu68VbVk/S2MqDTnQ7IvDlpBPeC85Vg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGmu68VbVk&#x2F;S2MqDTnQ7IvDlpBPeC85Vg&#x2F;view?utm_content=DAGmu68VbVk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U2_L2_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAe1VP', 'G5_T2_U3_L2', '解构游戏', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '学生将探索电子游戏的工作原理——从游戏循环的概念到代码如何变成交互体验。他们将学习游戏循环、核心循环，以及不同编程语言在游戏开发中的应用，并通过 HTML/CSS/JavaScript 的现场编码演示认识 IDE 和 AI 编码助手。', NULL, NULL, NULL, 'AI × 游戏：从LLM到可玩原型', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviPY2wUY/Rzb16M8ucMvL-gaXil5THw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviPY2wUY&#x2F;Rzb16M8ucMvL-gaXil5THw&#x2F;view?utm_content=DAGviPY2wUY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAE4h0', 'G4_T2_U2_L3', 'AI 如何推荐好内容？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课通过智能导购的推荐机制案例，引入两种不同的推荐机制——基于物品的协同过滤与基于用户的协同过滤，并结合各类电商平台的推送案例直观展示两种机制的异同，帮助学生形成更全面的理解。', NULL, NULL, NULL, '推荐算法与信息过滤', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfznOsbA/Wu9hhj0TEZgu4mhtfFbD0g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfznOsbA&#x2F;Wu9hhj0TEZgu4mhtfFbD0g&#x2F;view?utm_content=DAGvfznOsbA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAe6xS', 'G4_T1_U5_L2', '你的故事伙伴——和 AI 一起创作故事！', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课引导学生探索 AI 如何支持故事的写作与插画过程。学生将回顾好故事的关键要素，并学习用“三段式”结构来组织想法。随后，他们将使用 AI 工具生成图片，并将自己的文字创意扩展成简短的插画故事。课末，学生将理解 AI 如何成为创意故事讲述的好帮手。', NULL, NULL, NULL, '用 AI 讲故事：从想象到插画', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U5_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh6c-uog/V5GWVfNJzhnx3Mt3vORKCQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh6c-uog&#x2F;V5GWVfNJzhnx3Mt3vORKCQ&#x2F;view?utm_content=DAGvh6c-uog&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U5_L2_slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAeLCk', 'G4_T2_U2_L1', '给你看更多你喜欢的东西？——基于内容的推荐', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课介绍一种系统推荐方法：基于内容的推荐。学生将学习如何用多个维度准确描述物品（物品“身份证”），并与候选物品对比，选择相似度最高的物品进行推荐，从而模拟系统推荐过程。', NULL, NULL, NULL, '推荐算法与信息过滤', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf5Lpma0/6DdEAfsRFD3KVW9p9Rjwlg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf5Lpma0&#x2F;6DdEAfsRFD3KVW9p9Rjwlg&#x2F;view?utm_content=DAGvf5Lpma0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAep5m', 'G7_T2_U3_L1', '人类/机器人在工作中到底做什么？——探索AI时代的职业', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '引导学生通过讨论、访谈和在线职业数据库研究不同职业的任务、工具与技能，完成“职业角色卡”，培养数字调研与职业结构理解能力。', NULL, NULL, NULL, 'AI时代的未来工作 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZKcVqoY/O3xyv77kl7WsNyHSjU-iIA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZKcVqoY&#x2F;O3xyv77kl7WsNyHSjU-iIA&#x2F;view?utm_content=DAGvZKcVqoY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAEVqx', 'G5_T2_U1_L2', '人机协作——通过提示与AI创作', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '学生学习在人类与AI内容创作中如何通过提示工程进行协作。他们将定义提示（prompt），分析弱提示与强提示的差异，练习重写提示，并反思AI生成作品的作者身份与创作归属问题。', NULL, NULL, NULL, '解码AIGC：用人工智能创作', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviEogKb0/eDG2_MzYBA_IpPUUQhCQKw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviEogKb0&#x2F;eDG2_MzYBA_IpPUUQhCQKw&#x2F;view?utm_content=DAGviEogKb0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAeyn8', 'G6_T2_U5_L1', '用时间讲故事——数据如何展示时间的变化', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '通过时间线案例学习如何用时间顺序展现历史变化与模式，分析毕加索自画像变化，并用排序活动体验时间数据的叙事作用。', NULL, NULL, NULL, '历史的时间与空间——数据如何讲述故事 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U5_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviUUnnvc/KLOJNhiaU_kUMWkPfGhHAA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviUUnnvc&#x2F;KLOJNhiaU_kUMWkPfGhHAA&#x2F;view?utm_content=DAGviUUnnvc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U5_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAFG5V', 'G3_T2_U3_L4', '分类系统如何处理不确定性？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课引导学生探索分类系统在信息不完整、不清晰或含噪声时如何处理不确定性。他们会发现即使是智能系统也可能“不确定”，并学习它们如何利用置信度做出最佳猜测。通过趣味活动（如识别模糊图片、处理缺失线索），学生将认识到：不确定性是正常的，系统会用策略来应对它。', NULL, NULL, NULL, '模式识别与分类逻辑', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfoi4Oz4/7e8ErYj_PQX_FNcbPWoasA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfoi4Oz4&#x2F;7e8ErYj_PQX_FNcbPWoasA&#x2F;view?utm_content=DAGvfoi4Oz4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAFgsv', 'G3_T2_U2_L2', '模型如何学会做判断？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课引导学生认识到计算机可以像人一样通过练习（观察示例）来提高判断能力。学生将通过为天气场景贴标签（下雨/不下雨）并使用 Google Teachable Machine 演示训练一个简单 AI 模型来区分“陆地交通工具”和“非陆地交通工具”，理解模型如何在优质示例训练后提高预测准确率，从而强化“AI 通过数据模式学习”的概念。', NULL, NULL, NULL, '机器学习入门：建模、预测与评估', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfjUh5k4/uIcqp9wCsHVphz_OqYEf4Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfjUh5k4&#x2F;uIcqp9wCsHVphz_OqYEf4Q&#x2F;view?utm_content=DAGvfjUh5k4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAFm3b', 'G7_T2_U1_L1', '探索人工智能的起源——AI是如何诞生并塑造未来的', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '回顾人工智能的发展历程，从早期构想到学科诞生、快速发展、挑战与重大突破；通过讨论、时间线排序和趋势反思，理解AI如何演变并持续塑造世界。', NULL, NULL, NULL, '人工智能历史之旅 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviRV2BPQ/uW-bQGzXXHj9G6JvznnSmg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviRV2BPQ&#x2F;uW-bQGzXXHj9G6JvznnSmg&#x2F;view?utm_content=DAGviRV2BPQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAfpOn', 'G6_T2_U1_L2', 'AI在文化遗产呈现中的应用——AI如何帮助讲述文化遗产故事？', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '探讨AI如何在再创作、故事讲述、多模态呈现和个性化传递四个方面丰富文化遗产表达，以“下一个伦勃朗”案例引入，通过案例与活动反思AI的文化创作潜力。', NULL, NULL, NULL, '用人工智能保护与呈现文化遗产 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviFZio4c/qmgZYYgijRvzBfT8OWhSTg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviFZio4c&#x2F;qmgZYYgijRvzBfT8OWhSTg&#x2F;view?utm_content=DAGviFZio4c&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAfRQT', 'G4_T2_U3_L2', '过滤与聚焦——找到最佳答案', NULL, 'G4', '通识课', NULL, NULL, NULL, NULL, '本课引导学生学习如何过滤与聚焦搜索结果以找到最相关、最可靠的信息，理解搜索结果的构成，掌握何时及为何使用过滤器，并通过示例练习选择最适合任务需求的来源，养成批判性思考的习惯。', NULL, NULL, NULL, '从搜索到结构化：掌握信息技能', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf5coOo0/IZye5yYZwvECJ6_VXffIyw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf5coOo0&#x2F;IZye5yYZwvECJ6_VXffIyw&#x2F;view?utm_content=DAGvf5coOo0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAFwKj', 'G1_T2_U3_L3', '用积木完成任务——帮机器人 Toc 保安全！', NULL, 'G1', '项目课', NULL, 'CS素养', NULL, NULL, '本课中，学生将帮助外星机器人 Toc 避开地球上的车辆。通过三步任务——事件触发（碰撞检测）→ 消息传递（红色消息）→ 模块响应（跳跃动作），学生将掌握事件驱动编程和模块化思维，为创建复杂交互故事打下基础。', NULL, '事件驱动；消息传递；模块化', NULL, '用 ScratchJr 探索编程', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfhh_rA8/D4ND9kqWNGTFSDb609OUFg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfhh_rA8&#x2F;D4ND9kqWNGTFSDb609OUFg&#x2F;view?utm_content=DAGvfhh_rA8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAfynd', 'G6_T2_U3_L1', '从设计到动画——探索AI如何创建3D角色', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '探索角色从创意到3D模型的过程，对比传统与AI辅助方法，理解角色如何“成长”为结构化数字模型。', NULL, NULL, NULL, 'AI如何让3D角色“活”起来？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviOHhvEg/l3RA9Iwpy3vfhnli_yZAwQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviOHhvEg&#x2F;l3RA9Iwpy3vfhnli_yZAwQ&#x2F;view?utm_content=DAGviOHhvEg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAg64h', 'G4_T2_U3_L3', '从索引到排名——搜索结果是如何组织的', NULL, 'G4', '通识课', NULL, NULL, NULL, NULL, '本课带领学生探索搜索引擎如何组织与呈现结果，学习抓取（Crawling）、索引（Indexing）和排序（Ranking）三大步骤，并通过示例和流程填空活动，巩固从输入查询到排序结果页的全过程理解。', NULL, NULL, NULL, '从搜索到结构化：掌握信息技能', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf_bqSi4/y1o1S77JsjZwtuv1vL5rFg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf_bqSi4&#x2F;y1o1S77JsjZwtuv1vL5rFg&#x2F;view?utm_content=DAGvf_bqSi4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAGdhE', 'G3_T1_U1_L3', '筛选与分类——从篮子到市场（2）', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课向学生介绍两种重要的数据处理方式：筛选和分类。学生将跟随茉茉一起思考如何为荔枝上市做准备。过程中，他们会学习筛选（去掉不合格数据）和分类（按规则分组合格数据）的意义，并探索果园中真实的分拣规则，逐步练习应用这些规则。课后学生将能够解释“筛选”和“分类”的含义，并理解它们如何帮助做出更好的决策。', NULL, NULL, NULL, '用数据理解世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoV_Lz44/mB90Oex9LultEssgUUp5UQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoV_Lz44&#x2F;mB90Oex9LultEssgUUp5UQ&#x2F;view?utm_content=DAGuoV_Lz44&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U1_L3_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAghaj', 'G6_T1_U1_L4', '塑造未来城市——改变城市生活的八大智慧城市趋势', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '通过新加坡数字孪生案例和八大趋势介绍，学生理解未来智慧城市的发展方向，并在“My Future Smart City” 活动中设计未来城市，描述日常生活场景并讨论最希望实现的功能。', NULL, NULL, NULL, '智慧社会与人工智能 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U1_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviDQpul8/YD3mf-vnXfp0Hqdpmef-8g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviDQpul8&#x2F;YD3mf-vnXfp0Hqdpmef-8g&#x2F;view?utm_content=DAGviDQpul8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U1_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAGi1q', 'G5_T2_U3_L1', '神奇的LLM！', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课向学生介绍大型语言模型（LLM）——它是什么、如何学习以及如何预测。学生将通过简单类比理解分词、嵌入和自注意力等核心概念，参与“下一个词”小游戏，并讨论AI是否像人类一样“思考”。', NULL, NULL, NULL, 'AI × 游戏：从LLM到可玩原型', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviFwM1-I/fHaWPv_TiigP2-pHzUv49w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviFwM1-I&#x2F;fHaWPv_TiigP2-pHzUv49w&#x2F;view?utm_content=DAGviFwM1-I&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAgK02', 'G2_T1_U4_L4', '什么是万维网（WWW）？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课将向学生介绍万维网（WWW）的基本概念。他们将学习 WWW 如何在互联网上连接不同的页面和网站，了解其历史，并探索它在日常生活中的应用。通过生动的比喻和互动活动，学生将直观理解万维网的结构，并能将其与互联网区分开来。', NULL, NULL, NULL, '互联网与通信', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvhSVmbL8/zNuGevnMXwZkm-Q2LuYPxg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvhSVmbL8&#x2F;zNuGevnMXwZkm-Q2LuYPxg&#x2F;view?utm_content=DAGvhSVmbL8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U4_L4_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAglya', 'G2_T1_U3_L4', '谁告诉计算机该做什么？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课向学生介绍计算机是如何按照特定的步骤流程执行指令的。通过亲身体验物理和可视化编程活动，学生将探索顺序、分支（判断）和循环的逻辑——这是计算机程序的基本构件。他们将学习：没有指令，计算机不会行动；而不同的结构可以让计算机行动得更高效。', NULL, NULL, NULL, '从数据到行动——计算机如何工作', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuVw18aT4/I8Q88ikiB_yr_0MXQUAN4Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuVw18aT4&#x2F;I8Q88ikiB_yr_0MXQUAN4Q&#x2F;view?utm_content=DAGuVw18aT4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U3_L4_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAGNG2', 'G1_T1_U4_L3', '你能看到声音吗？', NULL, 'G1', '通识课', NULL, '数字素养', NULL, NULL, '学生将探索一个有趣的想法——声音可以用数字工具“看见”。通过录制自己的声音和播放简单的声音，他们将观察声波和频谱图如何出现在屏幕上。将熟悉的声音（如拍手声、动物叫声）与其视觉模式相连接，学生将理解声音虽然看不见，但借助科技可以呈现形状与图案。核心概念是声音虽不可见，但有可通过技术可视化的形状与模式。', NULL, '声波；频谱图；声音可视化', NULL, '数字媒体：用像素和声音表达', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfUtSGu0/EEEx_aUPgWjnYuZW7DrC1w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfUtSGu0&#x2F;EEEx_aUPgWjnYuZW7DrC1w&#x2F;view?utm_content=DAGvfUtSGu0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U4_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAgUsI', 'G6_T2_U6_L6', '庆祝我们的虚拟地图之旅！——回顾项目制学习过程与现实联系', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '观看整合后的虚拟旅行地图，进行项目成果评价与学习历程反思，讨论现实应用并进行自我评估。', NULL, NULL, NULL, '规划、创建并展示你自己的虚拟旅行体验 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U6_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviUHOBV8/Wq0duFiBjpjfR5ylXhCgwQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviUHOBV8&#x2F;Wq0duFiBjpjfR5ylXhCgwQ&#x2F;view?utm_content=DAGviUHOBV8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U6_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHbtK', 'G3_T2_U4_L2', '每日能量数据日志——我今天吃动平衡了吗？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课引导学生用数据探索一个核心健康问题：“我今天吃动平衡了吗？” 他们将使用两个有趣的数字模拟器计算自己一天中摄入和消耗的能量。通过记录食物摄入、估算体力活动并计算总能量收支，学生将开始理解食物如何提供能量、运动如何消耗能量。', NULL, NULL, NULL, '数字健康——数字工具如何帮助我们更聪明地饮食？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGskXPrXYY/Xj5TggWe6yjcJRZ39Cb_MQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGskXPrXYY&#x2F;Xj5TggWe6yjcJRZ39Cb_MQ&#x2F;view?utm_content=DAGskXPrXYY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U4_L2_slides</a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHbwO', 'G6_T1_U2_L2', '高速公路交通管理——信号、车速与交通流量的实验', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生在仿真平台测试三种交通控制策略，比较拥堵消除效果，并反思交通流量、信号时序、车速等因素的重要性，为下一课的自适应信号铺垫。', NULL, NULL, NULL, '智慧交通', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJUAWbs/uTASv0cQv_FJqZ9Skkm-lA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJUAWbs&#x2F;uTASv0cQv_FJqZ9Skkm-lA&#x2F;view?utm_content=DAGviJUAWbs&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAhc2I', 'G5_T1_U2_L10', 'Steve 的感官——传感器入门', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将探索传感器的概念——让机器感知环境的设备，类似于人类的感官。通过比较人类感官与机器传感器，学生将学习传感器检测的信号类型、信号如何转化为数据，以及感知与理解的区别。随后学生将应用这些知识为“Steve”选择合适的传感器。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L10.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvhzgS3Z0/eR3s-or8ps8T50YMUxmRQw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvhzgS3Z0&#x2F;eR3s-or8ps8T50YMUxmRQw&#x2F;view?utm_content=DAGvhzgS3Z0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L10_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHEmG', 'G1_T2_U1_L1', '逻辑大冒险——遵守规则', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课通过互动游戏《逻辑森林探险》向学生介绍逻辑运算符——与（AND）、或（OR）和非（NOT）的基本概念。学生将帮助小兔子通过应用简单的逻辑规则来解决谜题。在这些活动中，他们会探索逻辑运算符如何帮助计算机做出“是/否”决策。本课鼓励逻辑思维，并为理解数字设备如何“思考”打下基础。', NULL, '逻辑算符；规则判断；布尔决策', NULL, '用逻辑聪明思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfGZ64zU/QTKQjYqvoid9jPN1-MDQlQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfGZ64zU&#x2F;QTKQjYqvoid9jPN1-MDQlQ&#x2F;view?utm_content=DAGvfGZ64zU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAhLXK', 'G1_T2_U2_L6', '指挥乐队——用指令、顺序和循环创造节奏', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课通过音乐与节奏介绍编程基础。学生将通过解码模式与符号，学习如何使用指令、顺序和循环与动物乐队一起创作音乐节奏。本活动将音乐与编程相结合，为学生提供理解计算思维的趣味途径。', NULL, '节奏结构；可视化指令；序列与循环', NULL, '像程序员一样思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U2_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfrjeaVc/Y5tale_Rbu0Tpvjmn-WXMg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfrjeaVc&#x2F;Y5tale_Rbu0Tpvjmn-WXMg&#x2F;view?utm_content=DAGvfrjeaVc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U2_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHMp1', 'G3_T2_U2_L1', '如何通过建立训练集教 AI “识别”事物？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '在本节动手探究课中，学生将学习 AI 如何通过建立训练集来识别物体。通过日常示例和引导活动，他们会发现收集和标注示例如何帮助机器“学会”识别模式。这引入了机器学习的核心思想——机器需要结构化的示例才能做出准确预测。', NULL, NULL, NULL, '机器学习入门：建模、预测与评估', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfgbinrg/hIYz_ZvOCnMfXKPxQ6Jx0g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfgbinrg&#x2F;hIYz_ZvOCnMfXKPxQ6Jx0g&#x2F;view?utm_content=DAGvfgbinrg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAhnJt', 'G5_T2_U1_L1', 'AI创造力——创造还是生成？', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '学生探讨一个核心问题：AI是真正的创造，还是只是生成？通过比较AI生成与人类创作的作品，他们识别模式，讨论大型语言模型（LLM）、生成对抗网络（GAN）和扩散模型生成内容的机制，并反思AI创造力的局限性。课程最后引入“人机协作”的概念。', NULL, NULL, NULL, '解码AIGC：用人工智能创作', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviBTXXOM/XkbFBccXGkAg5ZR3IzOLKQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviBTXXOM&#x2F;XkbFBccXGkAg5ZR3IzOLKQ&#x2F;view?utm_content=DAGviBTXXOM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHoeM', 'G1_T1_U4_L4', '你能当个小小音乐家吗？', NULL, 'G1', '通识课', NULL, '媒体素养', NULL, NULL, '学生将探索音乐是如何由节奏、旋律和重复模式构成的。他们将聆听音乐、拍击节奏，然后使用简单的在线工具创作自己的短音乐模式。目标是帮助学生理解音乐不仅是声音——它还是一种具有结构、秩序和创造性的数字媒体。通过有趣且简单的探索，学生将成为能用清晰重复片段来设计、重复和分享音乐的“小小音乐家”。', NULL, '节奏；旋律；重复模式', NULL, '数字媒体：用像素和声音表达', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvff7mPLg/7eKCrAuob7sOBj09ZmdQAQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvff7mPLg&#x2F;7eKCrAuob7sOBj09ZmdQAQ&#x2F;view?utm_content=DAGvff7mPLg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U4_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHoJE', 'G6_T1_U3_L3', '自动驾驶挑战：操控 AI 汽车', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生在 Siemens 平台体验自动驾驶如何识别危险并做出安全决策，通过动手挑战加深对AI在驾驶中的作用理解，并思考驾驶权的归属问题。', NULL, NULL, NULL, '自动驾驶 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviOOC5y4/PEiYwKHqYNE5PYMR_htDMw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviOOC5y4&#x2F;PEiYwKHqYNE5PYMR_htDMw&#x2F;view?utm_content=DAGviOOC5y4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHQDj', 'G2_T2_U1_L1', '什么是人工智能？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '这是人工智能（AI）入门系列的第一课。学生将从日常经验出发，学会区分由人类制造的“人工”物品与自然界中生长的“天然”事物。在此基础上，学生将认识一种特殊的人工产物——人工智能。虽然 AI 是机器，但它可以“看”“听”并“做事”。通过比较人类与机器的行为，学生将开始理解 AI 是人类设计出来的、能够以“聪明”方式行动的工具。课堂包含图像分类游戏、人类感官与机器传感器的比较，以及绘画活动，帮助学生建立对 AI 的清晰第一印象。', NULL, NULL, NULL, '数字社会与未来：我们身边的智慧伙伴', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGsMfX4GZU/G--lGpPP92I7PfbK2tZlKA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGsMfX4GZU&#x2F;G--lGpPP92I7PfbK2tZlKA&#x2F;view?utm_content=DAGsMfX4GZU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U1_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAhR4h', 'G4_T2_U2_L6', '你愿意被预测吗？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课通过餐厅点餐方式的对比，引导学生辩证分析个性化推荐的优缺点（效率与便利 vs. 认知局限），探讨人机协作的平衡点（70% 定制 + 30% 随机），培养在数字环境中的独立决策能力。', NULL, NULL, NULL, '推荐算法与信息过滤', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U2_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf0rh4S0/isA26jIikbPhJFAcxRXy8Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf0rh4S0&#x2F;isA26jIikbPhJFAcxRXy8Q&#x2F;view?utm_content=DAGvf0rh4S0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U2_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAhS74', 'G7_T2_U4_L1', '什么是数字简历？', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '比较传统与数字简历，分析结构与目的，探讨数字工具与创意如何提升简历的表现力与未来感，并用思维导图构思个人简历。', NULL, NULL, NULL, '数字简历', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZfPT8EQ/rC_7n66WFRrDlqu5n0RszQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZfPT8EQ&#x2F;rC_7n66WFRrDlqu5n0RszQ&#x2F;view?utm_content=DAGvZfPT8EQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAHWn9', 'G4_T2_U4_L2', '构建推荐模型——从人工匹配到规则思维', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课将第一课的人工推荐系统升级为基于规则的推荐模型，学生将学习模型构建的两大步骤：特征提取与规则设定。通过小型图书数据集（从500本书中抽样），学生为读者匹配图书并编写 IF… THEN… 规则，为后续用飞书表格搭建在线推荐系统做准备。', NULL, NULL, NULL, '从读者到策展人：AI 驱动的图书推荐', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfwHlWPU/c2_QA8Zogm7Fc8tdNFxatQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfwHlWPU&#x2F;c2_QA8Zogm7Fc8tdNFxatQ&#x2F;view?utm_content=DAGvfwHlWPU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAhYU6', 'G7_T1_U4_L1', 'AI幻觉——AI创作伦理', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本单元引导学生批判性地审视AI生成内容所带来的伦理挑战与责任。他们将探讨AI幻觉的概念、成因，以及它既能作为创造性工具又可能成为错误信息来源的双重性质。学生还将就学术作弊、深度伪造娱乐、内容标识等争议话题开展结构化辩论，最终合作制定“班级AI使用协议”。本单元强调数字公民意识、批判性思维以及在AI创作时代的责任决策。', NULL, NULL, NULL, 'AI创作伦理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvifFmh-4/StwU-IW441qB5zAD6Ek2Fg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvifFmh-4&#x2F;StwU-IW441qB5zAD6Ek2Fg&#x2F;view?utm_content=DAGvifFmh-4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAI6iP', 'G4_T2_U2_L5', '推荐背后的影响', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课通过“恐龙视频上瘾”的案例，揭示推荐系统导致的“信息茧房”现象及其三大危害（认知固化/偏见/封闭性），引导学生设计“破茧计划”，培养健康的信息消费观念。', NULL, NULL, NULL, '推荐算法与信息过滤', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U2_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf02BOwc/7y371lVu0qZQxRK183U1iw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf02BOwc&#x2F;7y371lVu0qZQxRK183U1iw&#x2F;view?utm_content=DAGvf02BOwc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U2_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAI99J', 'G5_T2_U3_L4', '更强、更聪明、更出色', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '学生将进入AI生成网页游戏的优化阶段，学习调试HTML/CSS/JavaScript代码，发现改进空间，并通过更好的视觉效果、声音、计分或新机制提升游戏体验。重点在于创造性迭代，并使用 DeepSeek 支持调试与优化。', NULL, NULL, NULL, 'AI × 游戏：从LLM到可玩原型', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviG-hj8g/Jl9JY64H8gWShoKPed87FQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviG-hj8g&#x2F;Jl9JY64H8gWShoKPed87FQ&#x2F;view?utm_content=DAGviG-hj8g&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAigQ6', 'G3_T1_U2_L5', '做数据侦探——解读你的睡眠与情绪！', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课中，学生将化身“数据侦探”，探索自己睡眠与情绪的关系。利用上一课收集的一周数据，他们将分析模式、得出结论，并用图表呈现结果。本课聚焦 PPDAC 模型的最后两个阶段——分析与结论，强调用数据支持的批判性思考与个人洞察。', NULL, NULL, NULL, '用数据解决问题', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U2_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoejDsrI/2tmFAclA52c2DOylr-evZg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoejDsrI&#x2F;2tmFAclA52c2DOylr-evZg&#x2F;view?utm_content=DAGuoejDsrI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U2_L5_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAIJP9', 'G6_T2_U2_L1', '从真实到数字——文物是如何被数字化的', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '通过案例与交互平台学习文物数字化的采集与3D建模两大步骤，了解点云、网格、纹理映射等概念，并观察3D模型如何实现可旋转、缩放与多角度研究。', NULL, NULL, NULL, '用人工智能让历史重现', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviH2-dEU/LU0GqQALHQFGKR0G9-8l4w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviH2-dEU&#x2F;LU0GqQALHQFGKR0G9-8l4w&#x2F;view?utm_content=DAGviH2-dEU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAIkMA', 'G7_T2_U1_L4', 'AI的风险与反思——人工智能会给我们的未来带来哪些挑战？', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '探讨AI相关的就业、决策公平性、虚假信息等风险；通过投票与讨论识别重要风险并反思不同人关注点的差异，批判性思考AI的社会、伦理与环境影响。', NULL, NULL, NULL, '人工智能历史之旅 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U1_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvilZ2xB8/LPRzKvdHR1VSXu2mrlZvhg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvilZ2xB8&#x2F;LPRzKvdHR1VSXu2mrlZvhg&#x2F;view?utm_content=DAGvilZ2xB8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U1_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAILII', 'G4_T1_U2_L1', '什么是私人信息？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '私人信息是关于人及其家庭的重要细节——例如电话号码、家庭住址或密码——这些信息只应被本人和可信赖的成年人（如父母）知晓。如果陌生人获取了这些信息，他们可能会骚扰你、欺骗你，甚至冒充你。', NULL, NULL, NULL, '了解与保护私人信息', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuO70VWQ/mB6tam44SEZ1toY05LFAwg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuO70VWQ&#x2F;mB6tam44SEZ1toY05LFAwg&#x2F;view?utm_content=DAGvuO70VWQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U2_L1_Slides </a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAioRB', 'G7_T1_U2_L3', '做信息侦探——媒体素养与深度伪造', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课将指导学生成为数字信息的批判性消费者。在前面学习假新闻与深度伪造的基础上，本课聚焦于验证网络信息真伪的实用策略。学生将学习并实践 CRAAP 和 SIFT 方法，提升评估数字内容真实性的能力，并学会如何避免被操控或误导。', NULL, NULL, NULL, '媒体素养与深度伪造', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvidjTAbU/Ys_Af5atwnmBxVTG-obxUQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvidjTAbU&#x2F;Ys_Af5atwnmBxVTG-obxUQ&#x2F;view?utm_content=DAGvidjTAbU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAIqmA', 'G3_T1_U1_L2', '用表格整理数据——从篮子到市场（1）', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课引导学生探索如何整理和使用数据解决现实问题。以“茉茉的荔枝农场”故事为背景，学生将练习用结构化数据表记录、分组、比较和估算。学生将进行计数与计算，帮助茉茉估算收获带来的潜在收入。本课培养学生按类别整理数据的基础技能，并用基本算术支持决策。', NULL, NULL, NULL, '用数据理解世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoe_M3aE/lEZl1AFy_rx25fuW5F8gBg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoe_M3aE&#x2F;lEZl1AFy_rx25fuW5F8gBg&#x2F;view?utm_content=DAGuoe_M3aE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U1_L2_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAit9W', 'G4_T2_U1_L2', 'AI 如何“理解”你？——数字行为与个性化画像', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课引导学生理解 AI 如何基于数字足迹（Cookie/历史记录）进行兴趣建模，并通过对比家庭成员在购物推荐上的差异，最终构建用户画像。通过拼图游戏和画像制作，加深对个性化服务原理和隐私保护的理解。', NULL, NULL, NULL, '数字行为与个性化画像', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfxC2iBw/xSLDp9l8SHJd99n42kfEBA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfxC2iBw&#x2F;xSLDp9l8SHJd99n42kfEBA&#x2F;view?utm_content=DAGvfxC2iBw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAj1jF', 'G2_T1_U2_L1', '计算机如何做决定？——比特与逻辑门', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课向学生介绍驱动所有计算机的逻辑。课程从晶体管——计算机内部微小的开关（可以处于开（1）或关（0）状态）——开始，解释计算机如何用数百万个晶体管表示信息并作出决策。学生将探索基本逻辑门（非、与、或）和复合逻辑门（与非、或非、异或、同或），并通过真值表和简单电路模拟理解如何通过组合逻辑门让计算机执行复杂任务。', NULL, NULL, NULL, '计算机基础', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuhwJSne4/czxX5J7--L2GPfhbEOo3_g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuhwJSne4&#x2F;czxX5J7--L2GPfhbEOo3_g&#x2F;view?utm_content=DAGuhwJSne4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U2_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAjJiV', 'G3_T1_U3_L3', '用数据解读顾客偏好——我们的顾客喜欢哪种巧克力？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课引导学生用真实的调查数据探索顾客偏好。通过解读结构化问卷和筛选有效数据，学生理解数据如何反映不同群体的偏好。通过动手数据整理与分析，他们将基于口味、质地和使用习惯为目标顾客（教师或学生）建立画像。本课帮助学生掌握偏好（preference）、有效数据（valid data）和顾客画像（customer profile）的概念，并将其应用于真实的产品设计情境。', NULL, NULL, NULL, '智能巧克力工坊：用数据设计', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoR3D_fw/qtmmMZ6_A5MuhNrSV00qkA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoR3D_fw&#x2F;qtmmMZ6_A5MuhNrSV00qkA&#x2F;view?utm_content=DAGuoR3D_fw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U3_L3_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAJJN1', 'G2_T1_U2_L3', '从数字到比特：计算机如何理解颜色', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '现代计算机并不是将图像作为整体看待，而是将其视为许多称为“像素”的小点。每个像素都有自己的颜色代码，这些代码会被转换成比特并存储在计算机中。通过视觉化的“像素填色”活动，本课帮助学生理解图像是如何被“分解成小点并用数字表示”的。', NULL, NULL, NULL, '计算机基础', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuzUN8hFg/bpwxyug7JGErvChEEDvk1A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuzUN8hFg&#x2F;bpwxyug7JGErvChEEDvk1A&#x2F;view?utm_content=DAGuzUN8hFg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U2_L3_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAjJoB', 'G7_T1_U5_L3', '更多关于我们话题的新闻——如何找到更多相关报道？', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将担任小记者与研究员。他们将在第2课选择的话题基础上，搜索更多相关文章，使用AI进行摘要并添加合适图片。在复习信息可靠性验证方法后，他们将与另一组交换新闻卡片进行同伴可靠性检查。', NULL, NULL, NULL, '我们的声音，我们的新闻：AI驱动', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U5_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZSOaywo/qdBheEgoEXa5P0XzU9uvBA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZSOaywo&#x2F;qdBheEgoEXa5P0XzU9uvBA&#x2F;view?utm_content=DAGvZSOaywo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U5_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAJm5x', 'G3_T1_U2_L4', '收集并研究我们的数据——情绪与睡眠日记', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课中，学生将开始一个小项目，利用自己的数据研究睡眠与情绪的关系。他们将学习如何提出研究问题、确定收集哪些数据，并用结构化表格记录数据。本课聚焦 PPDAC 模型中的“数据”阶段：如何收集与整理数据。分析与结论将在下一课中进行。', NULL, NULL, NULL, '用数据解决问题', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuofsWVkI/FXD3W_LB_-47icEPTQp0jg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuofsWVkI&#x2F;FXD3W_LB_-47icEPTQp0jg&#x2F;view?utm_content=DAGuofsWVkI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U2_L4_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAJnOu', 'G3_T1_U1_L5', '图表（2）——帮助动物园园长', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课让学生探索折线图以及它如何展示随时间变化的趋势。在已有条形图和饼图知识的基础上，学生将分析动物园动物数量变化数据，将信息整理成表格并绘制折线图。他们将学习解读趋势、比较变化并进行预测。本课强调将图表类型与问题匹配的重要性，强化数据可视化的价值。', NULL, NULL, NULL, '用数据理解世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U1_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoaMXZ84/LYk966HCGISBG330S31-9Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoaMXZ84&#x2F;LYk966HCGISBG330S31-9Q&#x2F;view?utm_content=DAGuoaMXZ84&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U1_L5_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAjtUV', 'G5_T2_U2_L5', '最终展示', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '在本单元的最后一课中，学生将向全班展示改进后的原型，介绍产品创意、目标用户、主要功能，以及反馈如何塑造最终版本。他们将练习清晰表达、积极倾听与建设性反馈，并以同伴投票的方式评选出最具创意和有效的产品，最后反思从发现问题到交付测试方案的整个设计过程。', NULL, NULL, NULL, '做老板：成为产品经理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U2_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvmDVU2Ww/BbEfYP1TbCTjiBAsxNsP7Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvmDVU2Ww&#x2F;BbEfYP1TbCTjiBAsxNsP7Q&#x2F;view?utm_content=DAGvmDVU2Ww&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U2_L5_Slides</a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAjuRW', 'G4_T2_U4_L1', '匹配用户需求与图书特征——为谁推荐什么书？', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课介绍推荐系统的基本逻辑——匹配用户需求与物品特征。学生将在图书馆情境中识别并描述读者偏好与图书特征（三大类别：类型、主题、难度），进行人工匹配，并体验真实图书推荐网站对比人工与系统推荐结果。', NULL, NULL, NULL, '从读者到策展人：AI 驱动的图书推荐', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf2BQkX8/sI15y0i6_aCnoLDB1SM3yQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf2BQkX8&#x2F;sI15y0i6_aCnoLDB1SM3yQ&#x2F;view?utm_content=DAGvf2BQkX8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAjUXU', 'G4_T1_U5_L3', '你的插画伙伴——用 AI 创作图片', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课引导学生探索 AI 如何用文字生成图片，使用 Midjourney 和 DALL·E 3 等工具。他们将学习两种重要的 AI 模型——生成对抗网络（GAN）和扩散模型（Diffusion Models），并尝试用提示词生成自己的故事角色。通过引导示例与讨论，学生还将反思人类创造力在 AI 艺术创作中的作用。', NULL, NULL, NULL, '用 AI 讲故事：从想象到插画', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U5_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh2R8zAY/mhWLPlQkvQSNsbQJyPAHRQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh2R8zAY&#x2F;mhWLPlQkvQSNsbQJyPAHRQ&#x2F;view?utm_content=DAGvh2R8zAY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U5_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAjyff', 'G5_T1_U2_L4', 'Steve 学习——机器能像你一样学习吗？', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将探讨“机器能像人类一样学习吗？”的问题，并建立对机器学习的概念性认识。他们将比较人类学习与机器学习，理解从实例学习而非明确规则的思想，并用烹饪类比来理解过程。学生将学习 K 最近邻（KNN）算法作为易于理解的 AI 学习案例，并思考如何将其应用到 Steve 的垃圾分类任务中。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviCg5VU4/w427N1TjK_7IlKhO0yekYw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviCg5VU4&#x2F;w427N1TjK_7IlKhO0yekYw&#x2F;view?utm_content=DAGviCg5VU4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAKTRT', 'G4_T2_U1_L1', '谁在记录我的上网行为？——数字行为与个性化画像', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课通过日常生活案例和比喻（便利贴/日记）引导学生了解浏览器记录用户行为的两种方式：Cookie（网站偏好记录）和浏览历史（用户访问轨迹），建立数字足迹意识，并渗透隐私保护的概念。', NULL, NULL, NULL, '数字行为与个性化画像', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf4b7odo/SZ9R7aGd0Gq08oggEHFylw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf4b7odo&#x2F;SZ9R7aGd0Gq08oggEHFylw&#x2F;view?utm_content=DAGvf4b7odo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAkVBW', 'G2_T2_U1_L2', 'AI 如何改变我们的生活', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课引导学生探索人工智能在日常生活中的应用。通过观察图片和现实例子、分类活动和小组讨论，学生将了解 AI “听、看、行动”的能力。他们将初步理解 AI 的“感知–分析–行动”工作流程，并建立好奇心与现实生活的联系。学生将完成图片卡片分类、功能表格填写以及分享自己 AI 使用经历的简短陈述等任务。', NULL, NULL, NULL, '数字社会与未来：我们身边的智慧伙伴', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGsRiKmXjQ/R7ACwTny7ssZX2ZzvdQD8g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGsRiKmXjQ&#x2F;R7ACwTny7ssZX2ZzvdQD8g&#x2F;view?utm_content=DAGsRiKmXjQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U1_L2_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAlDjM', 'G7_T2_U1_L2', '人工智能发展的起伏——探索历史上的AI寒冬与繁荣期', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '聚焦两次“AI寒冬”和三次“繁荣”，分析技术局限、资金与公众预期对AI进程的影响；通过互动时间线重构事件并识别代表技术，思考AI发展的周期性与未来风险。', NULL, NULL, NULL, '人工智能历史之旅 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviqG-Drw/FHkfMV0UQld8Rjhr65GFdg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviqG-Drw&#x2F;FHkfMV0UQld8Rjhr65GFdg&#x2F;view?utm_content=DAGviqG-Drw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALdJO', 'G2_T2_U2_L6', 'AI 如何感知世界？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索人工智能（AI）机器如何使用不同类型的传感器来感知世界。通过游戏、配对活动和现实类比，他们将发现传感器与人类感官的关系。本课重点介绍 AI 使用的三种关键传感器：温度传感器、光传感器和距离传感器。学生将学会识别每种传感器的用途，并将它们与生活中熟悉的情境联系起来。', NULL, NULL, NULL, 'AI 如何感知世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U2_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfvE8Esw/kbyAWL7UQWSMysEuSQSxJw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfvE8Esw&#x2F;kbyAWL7UQWSMysEuSQSxJw&#x2F;view?utm_content=DAGvfvE8Esw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U2_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALf1S', 'G6_T2_U6_L4', '让你的导游活起来！——写一个有趣脚本，让AI帮你开口说话和动作表演', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '撰写英文讲解脚本并用HeyGen生成虚拟导游视频，体验文本转视频技术与AI内容生动化。', NULL, NULL, NULL, '规划、创建并展示你自己的虚拟旅行体验 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U6_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvidPD6Ns/Sbn2m4GL1AC0A_s7wMOW5w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvidPD6Ns&#x2F;Sbn2m4GL1AC0A_s7wMOW5w&#x2F;view?utm_content=DAGvidPD6Ns&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U6_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALh0w', 'G2_T1_U1_L3', '计算机硬件与软件', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '帮助学生区分计算机的可见部分（硬件）与控制它的不可见指令（软件）。通过对比、分类游戏和角色扮演类比，学生将学习按功能（输入/输出/双向）对硬件分类，并理解软件——尤其是操作系统——如何作为指挥官协调各种应用。本课旨在将学生的思维从“计算机长什么样”转向“计算机内部如何工作”。', NULL, NULL, NULL, '认识计算机', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGucBb0cD8/W4bokDnyZG-js7w4tUMDtg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGucBb0cD8&#x2F;W4bokDnyZG-js7w4tUMDtg&#x2F;view?utm_content=DAGucBb0cD8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U1_L3_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALjyG', 'G3_T1_U1_L4', '图表（1）——帮助动物园园长', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课向学生介绍两种数据可视化方式：饼图和条形图。以动物园报告为情境，学生将把杂乱的笔记转化为结构化的表格和图表。他们将学习如何解读图表、识别关键组成部分，并通过分析可视化数据的模式回答问题。在引导练习中，学生理解数据如何通过图表呈现并支持推理和决策。', NULL, NULL, NULL, '用数据理解世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U1_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoTKoF_Y/fskolec3fDp6oauABOAcDw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoTKoF_Y&#x2F;fskolec3fDp6oauABOAcDw&#x2F;view?utm_content=DAGuoTKoF_Y&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U1_L4_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALqD5', 'G6_T1_U4_L3', '运行自适应交通灯——测试程序、观察结果并总结项目', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '学生运行交通灯程序，分析不同参数对信号时序的影响，完成修改挑战，并反思与现实自适应系统的联系。', NULL, NULL, NULL, '在 Tinkercad 中构建自适应交通灯', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviNppC5s/aVviHOOEK_USXoz6Ocj31g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviNppC5s&#x2F;aVviHOOEK_USXoz6Ocj31g&#x2F;view?utm_content=DAGviNppC5s&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U4_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALSl3', 'G5_T1_U2_L9', 'Steve 完成！——最终组装与反思', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本单元最后一课中，学生将完成 Steve 的全部物理组装，将所有硬件集成到设计好的垃圾桶结构中。他们将安装 AI 摄像头，将舵机连接到桶盖，并为稳定性和可维护性安置 MCU 和电池。组装完成后，他们将运行一次完整的系统测试——从语音激活到垃圾识别与桶盖控制——并进行必要的调整。反思阶段，学生将评估原型，讨论改进方案，并探索基于云端的识别，与本地 AI 进行比较。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L9.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJgKXlg/LV8WxI8q6jHiPEGS7p1T8w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJgKXlg&#x2F;LV8WxI8q6jHiPEGS7p1T8w&#x2F;view?utm_content=DAGviJgKXlg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L9_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALslH', 'G1_T1_U3_L3', '你如何描述某样东西？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '本课向学生介绍可以通过物体的属性（如颜色、大小、形状）来描述世界中的事物。学生将探索熟悉的日常物品，并练习用多种方式进行分组和描述。通过提问、动手活动和猜谜游戏，学生将初步理解数据是如何用来描述和组织我们周围世界的。核心概念是一个物体可以有多个属性，而每个属性都能让我们对它有更多了解。', NULL, '属性（颜色/大小/形状）；多重归类；特征描述', NULL, '用数据看世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfWSgS80/3JAXeXdZ3Do_ck5dhagQVA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfWSgS80&#x2F;3JAXeXdZ3Do_ck5dhagQVA&#x2F;view?utm_content=DAGvfWSgS80&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAltnK', 'G1_T1_U3_L4', '谁的更多，谁的更少？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '本课引导学生用可见、可数的数据来比较群体。学生将使用常见物品（如彩色积木或形状卡片）识别不同群体的数量差异。在探索“更多”“更少”“最多”和“最少”等概念时，他们将学习如何用与数据相关的关键词来描述观察到的现象。核心概念是学会按属性分组物品并比较其数量大小。', NULL, '数量比较；分组计数；数据表达', NULL, '用数据看世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfSOL52s/dnQK9BAvwWzgGC1sb1RS7w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfSOL52s&#x2F;dnQK9BAvwWzgGC1sb1RS7w&#x2F;view?utm_content=DAGvfSOL52s&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmALu5l', 'G6_T2_U1_L1', 'AI在文化遗产保护中的应用——技术如何帮助我们守护过去', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '介绍AI在文化遗产保护中的应用，从巴黎圣母院的数字重建案例切入，学习激光扫描、3D建模、AI图像分析等技术及其在数字化、修复、环境监测和无障碍化四大方面的实际案例。', NULL, NULL, NULL, '用人工智能保护与呈现文化遗产 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviHZ7B_Q/hBoPHqgfvky1HyCWMVLYTw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviHZ7B_Q&#x2F;hBoPHqgfvky1HyCWMVLYTw&#x2F;view?utm_content=DAGviHZ7B_Q&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAmCjH', 'G2_T1_U1_L4', '计算机的历史', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将通过追溯计算机从古代计数工具到现代智能设备的发展历程，探索计算机的历史。通过故事讲述、图片和互动设计活动，他们将了解到计算机在尺寸、功能和智能上的演变。学生将认识到计算机是人类制造并不断随时间变化的发明，并被鼓励想象和创造自己对未来计算机的构想。', NULL, NULL, NULL, '认识计算机', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U1_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGtIQnIsdU/2SrXr_8eBUp7RGLq8WlGrA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGtIQnIsdU&#x2F;2SrXr_8eBUp7RGLq8WlGrA&#x2F;view?utm_content=DAGtIQnIsdU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U1_L4_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAMEZt', 'G1_T2_U3_L2', '运行我的第一个指令', NULL, 'G1', '项目课', NULL, 'CS素养', NULL, NULL, '本课中，学生将学习如何在讲故事程序中“运行”简单指令。他们将练习选择背景、添加角色、赋予声音并让角色移动。通过动手活动，学生理解指令是计算机执行的命令，并且指令的顺序很重要。', NULL, '指令执行；事件触发；动作参数', NULL, '用 ScratchJr 探索编程', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfowSY64/9pPaYFeub0vB53e0OdBawA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfowSY64&#x2F;9pPaYFeub0vB53e0OdBawA&#x2F;view?utm_content=DAGvfowSY64&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAMIdl', 'G5_T2_U2_L2', '产品设计——产品应该做什么？', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '学生将从理解用户问题（第一天）转向明确产品应如何解决问题。他们将学习如何将调研洞察转化为三项具体的设计成果：功能清单、用户流程图和界面草图。课程结束时，学生将拥有清晰的功能规划，准备进入下一课的团队组织与项目计划阶段。', NULL, NULL, NULL, '做老板：成为产品经理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviKv0c24/L2XDghjGqzIhf7bvdb0X4g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviKv0c24&#x2F;L2XDghjGqzIhf7bvdb0X4g&#x2F;view?utm_content=DAGviKv0c24&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAmN6U', 'G2_T1_U4_L3', '什么是网站与 URL？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课将向学生介绍网站和 URL 的基本概念。学生将学习网站是由多个网页组成的，以及 URL 如何帮助我们找到网站和特定页面。通过拆解 URL 的结构，学生将理解它的不同组成部分，并学习如何通过输入 URL 访问不同的网站和网页。', NULL, NULL, NULL, '互联网与通信', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvWckOcqA/Aa2o49Wlwk3F7JUGb7RtRA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvWckOcqA&#x2F;Aa2o49Wlwk3F7JUGb7RtRA&#x2F;view?utm_content=DAGvWckOcqA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U4_L3_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAN4JE', 'G5_T2_U4_L2', '智慧物流内部探秘', NULL, 'G5', '情境课', NULL, NULL, NULL, NULL, '在上一课的包裹旅程基础上，学生将剖析智慧物流系统的内部结构与运作，重点探讨三大组成部分——感知、决策和执行，以及三大核心流——信息流、控制流和物流。通过图解、案例，学生将学习传感器、算法和自动化等技术如何协同，让物流变得“智慧”。课程结束时，学生将能分析一个真实的物流挑战，并用感知–决策–执行模型提出解决方案。', NULL, NULL, NULL, '认识智慧物流', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvhyLUUqM/SkdtiosPfWx9xBjKOddLXA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvhyLUUqM&#x2F;SkdtiosPfWx9xBjKOddLXA&#x2F;view?utm_content=DAGvhyLUUqM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAn5Ic', 'G2_T1_U2_L2', '编码与解码', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课让学生理解计算机如何将文字转换成0和1（编码），再将其还原成文字（解码）。他们将学习文字信息在计算机中的表示方式，并通过“秘密信息纸条”游戏体验编码与解码的基本过程。目标是帮助学生建立“文字可以转化为数字”的初步理解，为下一节图像和声音编码课程做铺垫。', NULL, NULL, NULL, '计算机基础', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuylZzHLI/L0diCbyD8ztun6Af6mAcOQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuylZzHLI&#x2F;L0diCbyD8ztun6Af6mAcOQ&#x2F;view?utm_content=DAGuylZzHLI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U2_L2_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmANkIc', 'G5_T1_U1_L4', 'AI 的基础设施——能源、数据中心与维护', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将了解到 AI 系统与生物体一样，需要能量与基础设施才能运作。他们将探究 AI 的“燃料”（电力）来源，如何进行冷却与维护，以及支撑 AI 运行的数据中心等大型设施。学生将比较碳基生命系统与硅基 AI 系统，学习 AI 的能耗与可持续解决方案，并理解边缘计算与云计算的区别。课程以回顾整个单元收尾，强调 AI 的四个关键硬件部分。', NULL, NULL, NULL, '硬核 AI——AI 硬件与基础设施', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U1_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh2wN9bI/bZhCaGpq7tzn-6MbXjOp5A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh2wN9bI&#x2F;bZhCaGpq7tzn-6MbXjOp5A&#x2F;view?utm_content=DAGvh2wN9bI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U1_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmANnGj', 'G3_T2_U3_L3', '如何评估一个分类系统？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课引导学生学习如何检验分类系统的表现。通过有趣的示例（如分类健康零食、检测“入侵者”），学生将探索三种简单评估指标：准确率（预测正确的比例）、精确率（预测的严谨程度）和召回率（捕捉到的相关数量）。通过游戏和练习单，学生将理解为什么单靠准确率不够，以及何时需要改进“分类器”。核心理念：我们可以衡量系统表现并找到改进方法。', NULL, NULL, NULL, '模式识别与分类逻辑', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfpdLUU8/8aVjwUJWvJ1_Q6UfRy2tgw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfpdLUU8&#x2F;8aVjwUJWvJ1_Q6UfRy2tgw&#x2F;view?utm_content=DAGvfpdLUU8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAO2u2', 'G3_T2_U1_L2', '走进计算机的“大脑”——理解规则与学习', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课延续单元一主题，帮助学生理解计算机在不同构建方式下的思考差异：通过明确规则（传统编程）或通过数据学习（机器学习）。课程聚焦两个核心概念：透明性（计算机过程的可见程度）与“变聪明”（系统的改进方式）。', NULL, NULL, NULL, '传统编程 vs 机器学习', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvis9p3xY/F2U3Og-U6qQz194k-L6Hsg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvis9p3xY&#x2F;F2U3Og-U6qQz194k-L6Hsg&#x2F;view?utm_content=DAGvis9p3xY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U1_L2_slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAO72J', 'G6_T2_U6_L5', '融合所有成果——构建并完成最终的旅行项目', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '整合内容与视频，完成并发布包含开篇介绍与一个文化地点的完整数字旅行，并进行班级展示。', NULL, NULL, NULL, '规划、创建并展示你自己的虚拟旅行体验 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U6_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviQnm0FQ/dPAzk6u9_4w-7SV_VDlWTw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviQnm0FQ&#x2F;dPAzk6u9_4w-7SV_VDlWTw&#x2F;view?utm_content=DAGviQnm0FQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U6_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAobMI', 'G7_T1_U3_L2', 'NLP如何理解情绪？——自然语言处理与社会洞察', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课带领学生探索NLP如何尝试理解文本中的人类情绪。在理解假新闻与推荐算法的基础上，学生将学习计算机如何解读“开心”“生气”等词语，并分析NLP在处理语气、讽刺或复杂表达时的挑战。通过情感打分、电影评论和热点评论分析等实例，学生将反思计算机处理语言的方式及其对舆论与网络平台的潜在影响。', NULL, NULL, NULL, '自然语言处理与社会洞察', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvid7aU34/I-TZBZZPWsAdBbaf5fmnqg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvid7aU34&#x2F;I-TZBZZPWsAdBbaf5fmnqg&#x2F;view?utm_content=DAGvid7aU34&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAOCdQ', 'G3_T2_U2_L4', '数据越多越好吗？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索“更多数据是否总是带来更好预测”的问题。通过互动活动，他们将发现虽然更多信息有时有帮助，但真正重要的是数据的“质量”。学生将通过彩色积木、快速预测游戏和数字演示理解：数据太少会导致错误猜测，而太多无关数据会让系统困惑。关键结论：质量重于数量。', NULL, NULL, NULL, '机器学习入门：建模、预测与评估', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfvlRgtU/DW9IiI4le6TOogGMof3xTA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfvlRgtU&#x2F;DW9IiI4le6TOogGMof3xTA&#x2F;view?utm_content=DAGvfvlRgtU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAoeiP', 'G5_T2_U3_L3', '开始编码！打造你的第一个游戏', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '学生将运用对LLM和Web技术的理解，用AI辅助编码构建迷你游戏。他们将学习如何为LLM设计有效提示，并在 VS Code 中结合 Cline + DeepSeek 工具使用这些提示生成 HTML/CSS/JavaScript 游戏代码，进行测试并根据创意迭代。', NULL, NULL, NULL, 'AI × 游戏：从LLM到可玩原型', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJr71XM/grSy8rSPHtaEdyjTPSr-ug/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJr71XM&#x2F;grSy8rSPHtaEdyjTPSr-ug&#x2F;view?utm_content=DAGviJr71XM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAOLa6', 'G7_T1_U2_L2', '深度伪造的威胁——媒体素养与深度伪造', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课深入探讨深度伪造技术带来的威胁与风险。从假新闻和趣味性图片编辑，转向AI生成媒体在诈骗、操纵甚至犯罪中的应用。本课将帮助学生成为更有责任感的数字公民，并具备更强的识别与质疑虚假内容的能力。', NULL, NULL, NULL, '媒体素养与深度伪造', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvicjfKCo/q4_F9o3A70y0guMDngrpIw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvicjfKCo&#x2F;q4_F9o3A70y0guMDngrpIw&#x2F;view?utm_content=DAGvicjfKCo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAOngw', 'G7_T1_U4_L2', '谁该为内容负责？——AI创作伦理', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将围绕AI生成内容的争议话题（如学术作弊、深度伪造娱乐、内容标识等）展开结构化课堂辩论。目标是培养批判性思维、伦理意识，并在应对AI在日常生活中作用日益扩大的背景下共同制定规则。辩论后，学生将分组设计共享的“班级AI使用协议”，反映他们对负责任数字行为的集体理解。', NULL, NULL, NULL, 'AI创作伦理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviUZ-fyA/lH2FPUu3iwsNZParJypU_A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviUZ-fyA&#x2F;lH2FPUu3iwsNZParJypU_A&#x2F;view?utm_content=DAGviUZ-fyA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAOnRP', 'G6_T1_U3_L5', '自动驾驶汽车的安全与伦理——从减少事故到做出艰难选择', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '以Uber事故案例引导学生讨论安全与伦理，体验 Moral Machine 情境，认识技术潜力与伦理挑战并需社会共同制定规则。', NULL, NULL, NULL, '自动驾驶 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U3_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviER99wo/ViiHiG1e9CoYZaF72IV_Mg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviER99wo&#x2F;ViiHiG1e9CoYZaF72IV_Mg&#x2F;view?utm_content=DAGviER99wo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U3_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAopZy', 'G6_T1_U4_L2', '组装与编程自适应交通灯——从硬件连接到代码逻辑', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '学生完成电路组装，学习编程如何通过传感器输入、数据记录与分析实现自适应信号，理解软硬件结合解决问题的过程。', NULL, NULL, NULL, '在 Tinkercad 中构建自适应交通灯', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviDKuJ3s/VyZJzY54c0PpcFe7wN5tTQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviDKuJ3s&#x2F;VyZJzY54c0PpcFe7wN5tTQ&#x2F;view?utm_content=DAGviDKuJ3s&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAozrv', 'G5_T1_U2_L6', 'Steve 觉醒——连接大脑、眼睛和手臂', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将从软件转向硬件，学习 Steve 的“大脑”（微控制器）、“眼睛”（HuskyLens）和“手臂”（舵机）如何通过电路连接。他们将学习面包板基础，搭建迷你 LED 电路理解电路流动，并规划 Steve 的完整接线图。到课终，学生将准备好在下一课中组装完整的垃圾分类系统。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviJQO8i4/hMtt-SBGWrStIQRooFMliA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviJQO8i4&#x2F;hMtt-SBGWrStIQRooFMliA&#x2F;view?utm_content=DAGviJQO8i4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAP6wZ', 'G7_T2_U2_L3', '人机协作——理解三种协作模式', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '介绍人主导/机器辅助、平衡协作、机器主导/人类辅助三种模式，从Moravec悖论切入，通过案例配对识别模式特征与应用场景。', NULL, NULL, NULL, '现实世界中的AI系统：逻辑、协作与边界 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvihSadew/pxIlnKfGm67bxy6ZPOQJQg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvihSadew&#x2F;pxIlnKfGm67bxy6ZPOQJQg&#x2F;view?utm_content=DAGvihSadew&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmApbKc', 'G4_T1_U4_L2', '如何安全上网？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '在当今的数字世界中，孩子需要知道如何保护私人信息，避免落入陷阱。警示信号包括：陌生人试图与自己见面、索要私人照片、或施压要求保密。一旦出现这些行为，最好的做法是立即中断与此人的所有联系，并告知可信赖的成年人。理解数字隐私有助于孩子在安全地使用互联网的同时保护自己和个人信息。', NULL, NULL, NULL, '远离网络骗局', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuOhCa1I/D5_q3UAtru9MGr4-uaGuBQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuOhCa1I&#x2F;D5_q3UAtru9MGr4-uaGuBQ&#x2F;view?utm_content=DAGvuOhCa1I&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U4_L2_Slides </a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmApe2X', 'G7_T2_U2_L1', 'AI系统是如何运作的？——理解现实世界AI决策背后的逻辑', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '介绍AI系统的核心组成与运行逻辑，利用OECD AI框架分析自动驾驶、智慧交通等案例的输入-处理-输出过程，打下理解AI系统的基础。', NULL, NULL, NULL, '现实世界中的AI系统：逻辑、协作与边界 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvig6h_Sk/lc0V9AJHVAlZczH8JOWTEQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvig6h_Sk&#x2F;lc0V9AJHVAlZczH8JOWTEQ&#x2F;view?utm_content=DAGvig6h_Sk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAponY', 'G6_T1_U2_L1', '探索智慧交通——技术如何让出行更智慧、更安全', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生了解智慧交通的概念、核心技术（传感器、物联网、机器学习、大数据、自动驾驶）及七大应用领域，探讨技术如何提升出行安全性、效率与可持续性。', NULL, NULL, NULL, '智慧交通', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviM9pbUs/6Nvt4GpRjOqx9Cu6NPJiSg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviM9pbUs&#x2F;6Nvt4GpRjOqx9Cu6NPJiSg&#x2F;view?utm_content=DAGviM9pbUs&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmApqbT', 'G2_T2_U5_L2', '什么是模型？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将探索计算机和 AI 是如何利用“模型”来进行预测的。通过有趣的“猜动物”动手游戏，学生将初步理解 AI 模型是如何利用线索进行推测的——就像我们一样！本课将这种抽象概念与熟悉的课堂游戏联系起来，让“大概念”变得简单有趣。', NULL, NULL, NULL, 'AI 如何学习', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U5_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfnwfGVo/RKIQA4-YqvINkQvs9JB9yA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfnwfGVo&#x2F;RKIQA4-YqvINkQvs9JB9yA&#x2F;view?utm_content=DAGvfnwfGVo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U5_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAPuLR', 'G3_T2_U4_L1', '食物也是数据？——100 克食物到底有多少能量？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课引导学生探索食物不仅有味道和外观，还包含可测量、可比较、可可视化的数据。学生将使用数字营养数据库查找不同食物（每 100 克）的热量含量，记录结果，并合作制作可视化的“食物能量墙”。通过称重食物样本、填写数据卡片并按能量从高到低排列等活动，学生将学习数据的收集、整理和决策应用。同时，本课引入千卡（kcal）作为能量单位，帮助学生将营养科学与数据收集、排序、可视化等数字素养技能相联系。', NULL, NULL, NULL, '数字健康——数字工具如何帮助我们更聪明地饮食？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGinlcdAyo/9KREg1R2tAod3NxtDRi_6A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGinlcdAyo&#x2F;9KREg1R2tAod3NxtDRi_6A&#x2F;view?utm_content=DAGinlcdAyo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U4_L1_slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAQfrW', 'G3_T2_U4_L4', '用 AI 管理健康', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将回顾“能量差”概念，并用“输入→处理→输出”模型回答“健康管理应用如何工作”这一问题。他们将探索智能设备和应用（由 AI 驱动）如何自动化许多手动步骤，重点学习由美国高中生开发的最新、最成功的基于照片', NULL, NULL, NULL, '数字健康——数字工具如何帮助我们更聪明地饮食？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGnHeu8cxc/6YvANnnOhJhHp-dK3o2YPA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGnHeu8cxc&#x2F;6YvANnnOhJhHp-dK3o2YPA&#x2F;view?utm_content=DAGnHeu8cxc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U4_L4_slides </a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAQhhI', 'G2_T2_U5_L1', 'AI 为什么需要数据？——AI 的推理能力', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将学习 AI 并非“天生聪明”，而是像人类一样通过大量示例的练习来学习。通过训练 AI 识别水果，并比较不同训练数据量下的结果，学生将看到更多数据 = 更好学习，以及数据不足时 AI 可能犯错。', NULL, NULL, NULL, 'AI 如何学习', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U5_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvr9dOtd0/2YBmqy6DJa1BbP7ChgAHvQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvr9dOtd0&#x2F;2YBmqy6DJa1BbP7ChgAHvQ&#x2F;view?utm_content=DAGvr9dOtd0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U5_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAqJJg', 'G3_T2_U1_L1', '我们如何让计算机做事？——用规则解决问题 vs 从数据中学习', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课引导学生探索计算机解决问题的两种方式：传统编程（由人写规则）和机器学习（从数据中学习）。通过四个有趣的动手活动，学生体验计算机如何执行指令、识别人脸和声音、推荐视频。本课为学生建立对智能系统如何学习和运作的基础理解。', NULL, NULL, NULL, '传统编程 vs 机器学习', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviv8cFFI/1LQBAsPp7bnOZ5VAjLFMKQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviv8cFFI&#x2F;1LQBAsPp7bnOZ5VAjLFMKQ&#x2F;view?utm_content=DAGviv8cFFI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U1_L1_slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAqrs4', 'G6_T2_U6_L1', '发现项目——了解我们将要创作的作品，并认识虚拟导游！', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '体验示例虚拟旅行，分析文化遗址呈现与虚拟导游作用，开始规划自己的虚拟导游角色与表现方式。', NULL, NULL, NULL, '规划、创建并展示你自己的虚拟旅行体验 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U6_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviToHyec/jhIA-aAq6D2IUisA2gG2MA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviToHyec&#x2F;jhIA-aAq6D2IUisA2gG2MA&#x2F;view?utm_content=DAGviToHyec&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U6_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAQWHa', 'G3_T2_U2_L3', 'AI 也需要考试吗？', NULL, 'G3', '通识课', NULL, NULL, NULL, NULL, '本课引导学生认识到，AI 和人类一样，需要通过测试来检验学习效果。学生将探索 AI 如何进行预测，以及为什么检查预测结果（评估）很重要。通过动手任务（如检查 AI 在练习单上的答案、测试在线 AI 绘画工具），学生将理解测试如何帮助 AI 改进，就像模拟考试帮助学生提高一样。', NULL, NULL, NULL, '机器学习入门：建模、预测与评估', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfvc3BiA/k3nRQMW84005HehsNyegHA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfvc3BiA&#x2F;k3nRQMW84005HehsNyegHA&#x2F;view?utm_content=DAGvfvc3BiA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAR2BI', 'G6_T1_U3_L1', '自动驾驶汽车的“感官”——汽车如何感知周围世界？', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生学习GPS、激光雷达、摄像头、雷达、红外、超声波、地图、DSRC、惯性导航等传感技术及组合方案，并了解特斯拉的纯视觉路线。', NULL, NULL, NULL, '自动驾驶 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviEHCTSU/4FohQHaZ_sQolC0uFvS23A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviEHCTSU&#x2F;4FohQHaZ_sQolC0uFvS23A&#x2F;view?utm_content=DAGviEHCTSU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAr2xT', 'G1_T2_U1_L3', '布尔值——用布尔逻辑制定安全规则', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课通过日常物品和安全设备向学生介绍布尔值的概念。学生将学会识别只有两种可能状态的情境，并用“真/假”（TRUE/FALSE）来表示。他们将练习编写 IF…THEN 语句来描述不同设备在紧急情况中的行为，并反思逻辑规则如何帮助机器做出决策。', NULL, '布尔值；二元状态；逻辑规则', NULL, '用逻辑聪明思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfZRKQGo/0NEYi6y_Eu1C99ctlEY3FQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfZRKQGo&#x2F;0NEYi6y_Eu1C99ctlEY3FQ&#x2F;view?utm_content=DAGvfZRKQGo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U1_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmARAb7', 'G3_T2_U4_L3', '每日饮食图表——我的饮食健康均衡吗？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课引导学生围绕“图表能帮助我们做出更健康的饮食选择吗？”这一问题展开。学生将制作一份数字餐盘，为自己的一日饮食生成饼图和条形图，并利用这些可视化结果发现饮食问题并制定具体改进计划。', NULL, NULL, NULL, '数字健康——数字工具如何帮助我们更聪明地饮食？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGlQOP3G5Y/c4HL51V8TOGvo8hhzgu_3w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGlQOP3G5Y&#x2F;c4HL51V8TOGvo8hhzgu_3w&#x2F;view?utm_content=DAGlQOP3G5Y&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U4_L3_slides </a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmARcMn', 'G3_T1_U2_L6', '单元总结——用数据解决问题', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课帮助学生复习完整的 PPDAC 模型，巩固用数据解决实际问题的理解。学生将通过可视化回顾和讨论重温每个阶段的关键概念，并参加单元测试展示所学。教师可选择课堂讲评或收集批改后在下一课讨论。', NULL, NULL, NULL, '用数据解决问题', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U2_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoZGT-B0/x4h_CGbZUSgtq_tl9fgKyA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoZGT-B0&#x2F;x4h_CGbZUSgtq_tl9fgKyA&#x2F;view?utm_content=DAGuoZGT-B0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U2_L6_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmArETM', 'G7_T2_U3_L2', '工作的变化——在AI时代消失与出现的职业', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '研究职业消失的原因与AI对工作的重塑，通过趋势分析和象限图评估职业被AI取代的风险，培养批判性思维与分类推理能力。', NULL, NULL, NULL, 'AI时代的未来工作 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZE1uZMk/lTQ_3HTnMnWNKzr9zrEJxw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZE1uZMk&#x2F;lTQ_3HTnMnWNKzr9zrEJxw&#x2F;view?utm_content=DAGvZE1uZMk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmARhrm', 'G7_T1_U2_L1', '深度伪造的真相——媒体素养与深度伪造', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课带领学生深入了解各种“伪造”——不仅是假新闻，还有由现代技术生成的照片、视频和音频操控案例。通过真实案例（如著名的“怪兽猫”照片）以及先进的AI深度伪造示例，学生将探讨媒体如何被篡改以及为什么难以分辨真伪。他们将学习深度伪造技术的工作原理、人们制造这些内容的动机，以及相关风险与责任。课末学生将具备更强的媒体素养，学会质疑线上所见，并反思编辑与AI如何改变我们对真相的认知。', NULL, NULL, NULL, '媒体素养与深度伪造', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviXq17ds/RBAR6sZYQv1YhkYRPZ-wiA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviXq17ds&#x2F;RBAR6sZYQv1YhkYRPZ-wiA&#x2F;view?utm_content=DAGviXq17ds&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmARiWL', 'G2_T2_U4_L1', 'AI 如何下棋？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索 AI 如何玩象棋等游戏。他们将比较人类思考与 AI“计算”走法的方式，发现 AI 的“聪明”来源于人类设定的规则与程序，而不是理解或情感。通过井字棋小游戏、AlphaZero 学棋的简短故事，以及动手的“决策树”活动，学生将学会区分“看起来很聪明”和“真正会思考”。', NULL, NULL, NULL, 'AI 如何思考与决策', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvkJPtdyo/cVbHGD9FekGSlvIX6-k1bg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvkJPtdyo&#x2F;cVbHGD9FekGSlvIX6-k1bg&#x2F;view?utm_content=DAGvkJPtdyo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U4_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmArKMD', 'G6_T2_U6_L2', '设计旅行路线——探索、调研并构建你的旅行站点', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '学习使用ArcGIS StoryMaps设计城市主题旅行，进行分组资料收集与撰写简介。', NULL, NULL, NULL, '规划、创建并展示你自己的虚拟旅行体验 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U6_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvibFSZBM/QXqVrZnc3g690OFc8RyyWg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvibFSZBM&#x2F;QXqVrZnc3g690OFc8RyyWg&#x2F;view?utm_content=DAGvibFSZBM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U6_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmArl34', 'G4_T1_U3_L4', '如果个人数据泄露会怎样？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '本课探讨个人数据泄露的潜在风险和后果。学生将通过真实案例了解被盗信息如何被滥用于身份盗窃、诈骗、欺诈或骚扰。他们还将讨论减少损害的策略，例如设置强密码、使用双重身份验证以及及时报告可疑活动。', NULL, NULL, NULL, '数字足迹与数据隐私', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuLLTcAQ/sMFzojrTqR9ZKzZ1VCZMUA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuLLTcAQ&#x2F;sMFzojrTqR9ZKzZ1VCZMUA&#x2F;view?utm_content=DAGvuLLTcAQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmArLXv', 'G3_T1_U3_L4', '为顾客设计巧克力——AI 能帮我们设计完美巧克力吗？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课引导学生根据用户偏好设计巧克力产品。学生将探索风味配料，学习企业如何收集顾客信息，并利用 AI 激发口味创意，从而理解创意与数据如何在产品设计中协同作用。课末，学生将利用收集到的数据为目标顾客打造一款契合需求的巧克力。', NULL, NULL, NULL, '智能巧克力工坊：用数据设计', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoad22ug/SPwBRYkVw4glxNWHfJxteA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoad22ug&#x2F;SPwBRYkVw4glxNWHfJxteA&#x2F;view?utm_content=DAGuoad22ug&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U3_L4_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmArqp9', 'G5_T1_U2_L7', '意大利面电路——反正先让它跑起来', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将根据接线图连接 Steve 的所有硬件组件——微控制器、传感器、执行器和 AI 模块。他们将构建完整电路，逐步测试各个功能，并两人一组调试问题。这一动手组装环节将硬件规划与功能集成连接起来，为下一节的编程做好准备。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L7.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviN3YiZk/tAp9yeRuFxAWHnTrt_qsFg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviN3YiZk&#x2F;tAp9yeRuFxAWHnTrt_qsFg&#x2F;view?utm_content=DAGviN3YiZk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L7_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmARUkP', 'G4_T2_U4_L4', '展示·改进·反思', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '在本单元最后一课中，学生将展示用 Lark Base 搭建的图书推荐系统，讲解匹配规则背后的逻辑，并接受同伴反馈。随后，学生将基于反馈进行改进，并反思在推荐系统与以用户为中心的设计中所学到的知识。', NULL, NULL, NULL, '从读者到策展人：AI 驱动的图书推荐', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf3dcBKw/fTWzvBe4wC8Qdp9ibapg6w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf3dcBKw&#x2F;fTWzvBe4wC8Qdp9ibapg6w&#x2F;view?utm_content=DAGvf3dcBKw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U4_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAs6vY', 'G3_T2_U4_L6', '训练我的AI：如何教AI判断健康餐盘？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '数字健康——数字工具如何帮助我们更聪明地饮食？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U4_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGotmGAZZ8/4IkP9FZrlY1OQjUYloLcfQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGotmGAZZ8&#x2F;4IkP9FZrlY1OQjUYloLcfQ&#x2F;view?utm_content=DAGotmGAZZ8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U4_L6_slides </a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmASGDk', 'G1_T1_U2_L3', '数据能形成图案吗？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '学生将探索如何用代码识别和描述重复图案。通过观察简单的像素图案并模拟编织过程，学生会发现如何将重复元素转化为数据。核心思想是数据不仅是数字，还可以用来描述由重复单元构成的视觉设计。课堂将利用“编织”网格进行活动，学习如何用符号描述所见内容。', NULL, '重复模式；符号编码；像素图案', NULL, '地图：探索空间与路径', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfXwwdl8/YNFIs8VJ2AbUCkgxI6n5jQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfXwwdl8&#x2F;YNFIs8VJ2AbUCkgxI6n5jQ&#x2F;view?utm_content=DAGvfXwwdl8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAsGF7', 'G3_T1_U1_L6', '单元总结——用数据理解世界', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '作为单元的最后一课，学生将复习关于数据的所学内容，并通过现实数据故事应用所学。他们将回顾数据素养的关键概念，包括数据收集、处理与分析。课堂的参与环节包含三个微型案例研究，让学生化身“数据侦探”。', NULL, NULL, NULL, '用数据理解世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U1_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoRUfldo/nul-6Ddy-ykbZbj6jU71TA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoRUfldo&#x2F;nul-6Ddy-ykbZbj6jU71TA&#x2F;view?utm_content=DAGuoRUfldo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U1_L6_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAsN3r', 'G4_T1_U3_L2', '免费应用真的免费吗？——个人数据与隐私', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '在本节课中，学生将探究免费应用如何收集和使用个人数据。通过分析小红书、淘宝和微信等常用应用，他们将了解应用收集的信息类型——如位置信息、浏览记录和社交互动——以及这些数据如何被用来进行个性化推荐、广告和服务。学生还将批判性地反思便利与隐私风险之间的平衡，增强如何负责任地管理个人数据和保护数字身份的意识。', NULL, NULL, NULL, '数字足迹与数据隐私', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuISA1yw/-CT2CCLFRk-z7Z6w09DBYA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuISA1yw&#x2F;-CT2CCLFRk-z7Z6w09DBYA&#x2F;view?utm_content=DAGvuISA1yw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAsNoJ', 'G1_T1_U2_L2', '你如何在地图上找到宝藏？', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '学生将通过熟悉的校园场景，学习如何用符号和形状来表示大空间，并绘制自己的简易校园地图，从而理解地图是现实空间的抽象化表达。通过观察、讨论和绘画，学生将体会到地图如何帮助人们在不亲临其境的情况下理解地点。', NULL, '坐标；路径；最短路线', NULL, '地图：探索空间与路径', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U2_L2.png', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfQ_8tJw/bLhiCwWTWY05McbElw5szw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfQ_8tJw&#x2F;bLhiCwWTWY05McbElw5szw&#x2F;view?utm_content=DAGvfQ_8tJw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAsoLo', 'G1_T2_U1_L2', '如果……那么……——用条件做聪明选择', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '本课通过“如果……那么……”和“如果……那么……否则……”结构向学生介绍基础条件语句。通过互动故事和动手逻辑游戏，学生将帮助小兔子根据条件做出选择。他们将学习条件如何指导生活和计算机编程中的决策。课末，学生能够在简单情境中识别、理解并应用条件逻辑。', NULL, '条件语句；分支结构', NULL, '用逻辑聪明思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfI4RFy8/p4PihyAhoXnTm1xZKT1yhg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfI4RFy8&#x2F;p4PihyAhoXnTm1xZKT1yhg&#x2F;view?utm_content=DAGvfI4RFy8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmASpQE', 'G3_T1_U2_L2', '什么是一个好问题？——确定要调查的问题', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课聚焦 PPDAC 模型的“问题”阶段。通过三个真实情境，学生将学习什么样的问题适合用数据来调查。他们将理解一个好问题应具体、可测量、有目的，并明确涉及的群体和主题。学生还将学习两个关键概念：总体（population）与变量（variable），并练习基于这些概念提出问题。', NULL, NULL, NULL, '用数据解决问题', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoec7SnQ/uTCB3IMUVvz1T3TmFAmrUA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoec7SnQ&#x2F;uTCB3IMUVvz1T3TmFAmrUA&#x2F;view?utm_content=DAGuoec7SnQ&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U2_L2_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmASUVK', 'G6_T1_U2_L4', '为救护车让路——智慧信号如何打造“绿波带”', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '通过西雅图案例，学生学习智慧信号如何为急救车辆创造畅通路线，理解传统优先方式的不足，并反思智慧交通系统的价值。', NULL, NULL, NULL, '智慧交通', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviDsox9I/wUiSbWFlJYWeoZ-CFmUDUQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviDsox9I&#x2F;wUiSbWFlJYWeoZ-CFmUDUQ&#x2F;view?utm_content=DAGviDsox9I&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmASUxM', 'G2_T1_U1_L1', '日常生活中的计算机', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '帮助学生打破“计算机=台式机/笔记本”的刻板印象，开始形成功能性视角来判断什么是计算机。理解计算机不仅是笔记本电脑，还包括日常生活和科学工作中使用的各种智能设备。', NULL, NULL, NULL, '认识计算机', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGr3uWP2zs/I6kkMCegPuUoWBnFZeLjkg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGr3uWP2zs&#x2F;I6kkMCegPuUoWBnFZeLjkg&#x2F;view?utm_content=DAGr3uWP2zs&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U1_L1_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAsz89', 'G5_T2_U4_L4', '用算法找路！', NULL, 'G5', '情境课', NULL, NULL, NULL, NULL, '学生将基于路径的抽象表示，学习计算机如何用算法搜索路径。他们将了解图论基础——节点、边、状态和状态空间，并探索广度优先搜索（BFS）与深度优先搜索（DFS）的工作原理。学生还将接触加权路径以及“成本”如何影响最佳路径选择。课程结束时，学生将能比较BFS与DFS，解释加权路径的概念，并将这些思路与现实中的物流和导航系统相联系。', NULL, NULL, NULL, '认识智慧物流', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh7LWDPI/zCjh_2J7gz0SA4L41CNqvw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh7LWDPI&#x2F;zCjh_2J7gz0SA4L41CNqvw&#x2F;view?utm_content=DAGvh7LWDPI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U4_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAT4HY', 'G7_T1_U2_L4', '识别假新闻——媒体素养与深度伪造', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课探讨假新闻的制作、传播和被相信的过程。学生将通过互动调查、分析可疑标题和小组讨论，培养批判性思维以评估在线信息的可信度。他们将分析真实案例，学习常见的错误信息模式，并反思人们为何容易被假或误导性内容欺骗。课末学生将能够识别假新闻手法，理解情绪化设计与呈现对可信度的影响，并反思核实网络内容的重要性。', NULL, NULL, NULL, '媒体素养与深度伪造', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvifFAkis/sDec0mP3fXGUhPgYcaeoBg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvifFAkis&#x2F;sDec0mP3fXGUhPgYcaeoBg&#x2F;view?utm_content=DAGvifFAkis&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAT52l', 'G4_T1_U5_L6', '一本绘本的诞生', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '在本单元的最后一课中，学生将把之前的作品整合成完整的数字绘本。他们将使用 MidJourney 设计书封，并用 Canva 为每一页故事配上文字说明进行排版。课程最后将举行全班作品展示会。', NULL, NULL, NULL, '用 AI 讲故事：从想象到插画', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U5_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh_hRFg8/vSJGGX_i7fsDMtXvb45NiQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh_hRFg8&#x2F;vSJGGX_i7fsDMtXvb45NiQ&#x2F;view?utm_content=DAGvh_hRFg8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U5_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAT9x0', 'G3_T2_U4_L5', 'AI识别评估：如何判断AI是否可信？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '数字健康——数字工具如何帮助我们更聪明地饮食？', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T2_U4_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGoEXIBfZ8/U5PryEV6MErwAfZGr-CGIQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGoEXIBfZ8&#x2F;U5PryEV6MErwAfZGr-CGIQ&#x2F;view?utm_content=DAGoEXIBfZ8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3下_U4_L5_slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmATgaw', 'G5_T2_U4_L1', '包裹的奥德赛之旅', NULL, 'G5', '情境课', NULL, NULL, NULL, NULL, '学生将探索包裹的旅程——从下单到送达客户手中。他们将了解智慧物流的关键步骤，包括下单、运单生成、分拣、路线规划、长途运输和末端配送。通过讨论、路线绘制和观察智能分拣系统，学生将理解信息流与物流的运行，并反思技术如何提升配送效率与准确性。课程结束时，学生将能口头描述包裹的完整旅程，并提出作为未来物流工程师的改进设想。', NULL, NULL, NULL, '认识智慧物流', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvhxoEmjY/xjGUbLJBMst25_7XgMkwVA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvhxoEmjY&#x2F;xjGUbLJBMst25_7XgMkwVA&#x2F;view?utm_content=DAGvhxoEmjY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAThTe', 'G7_T1_U1_L1', '为什么我们在网上看到的东西不一样？——算法与注意力', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课向学生介绍推荐算法的概念，并探讨为什么不同的人会在网上看到不同的内容。通过真实案例、互动讨论、视频分析和实践活动，学生将理解推荐算法的工作原理、用户行为如何塑造数字画像，以及平台如何为个人策划内容。课末学生能够解释什么是推荐算法，描述自己的在线行为如何影响看到的内容，识别“抓住”注意力的关键平台设计特征，并反思算法策划在数字生活中的潜在风险。', NULL, NULL, NULL, '算法与注意力——做数字世界的聪明人', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvifFGpTs/Q35l2j00K8uNmfJNBPlVMw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvifFGpTs&#x2F;Q35l2j00K8uNmfJNBPlVMw&#x2F;view?utm_content=DAGvifFGpTs&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAtkvK', 'G2_T1_U4_L2', '什么是 IP 地址？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课向学生介绍 IP 地址的概念。他们将了解到 IP 地址是帮助设备在互联网上找到彼此的唯一编号，就像家庭地址帮助人们找到房子一样。学生将探索 IP 地址在连接设备中的重要性，以及它在网络通信中发挥的重要作用。', NULL, NULL, NULL, '互联网与通信', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvJxcpIx8/_i9eQqHVyThiehu8BgU84Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvJxcpIx8&#x2F;_i9eQqHVyThiehu8BgU84Q&#x2F;view?utm_content=DAGvJxcpIx8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U4_L2_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmATMM8', 'G4_T1_U3_L1', '什么是数字足迹？', NULL, 'G4', '情境课', NULL, NULL, NULL, NULL, '数字足迹是指关于你的一切出现在互联网上的信息。这包括照片、音频、视频、文字，甚至是你在朋友主页上的“点赞”和评论。就像走路时脚会在地上留下脚印一样，你在网上发布的内容也会留下痕迹。', NULL, NULL, NULL, '数字足迹与数据隐私', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T1_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvuKxrJD4/isWhr9UFmbq3xeYupdnVZQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvuKxrJD4&#x2F;isWhr9UFmbq3xeYupdnVZQ&#x2F;view?utm_content=DAGvuKxrJD4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4上_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmATtDB', 'G5_T1_U1_L3', 'AI 的神经系统——网络与通信', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索 AI “大脑”如何通过接口和网络与身体的其他部分通信——就像人类神经系统一样。他们将比较人类神经与 AI 通信路径，了解连接传感器与执行器到处理器的接口，以及 AI 系统在内部和外部的通信方式。通过追踪一个真实的 AI 通信流程（如 ChatGPT），学生将看到信号如何在设备、网络和数据中心间传递。课程最后将连接迄今为止学到的各个部分，并预览下一个主题——AI 系统如何获取能量运行。', NULL, NULL, NULL, '硬核 AI——AI 硬件与基础设施', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh7f-K4w/rc8o1h6dROJ8tdTfcj67OQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh7f-K4w&#x2F;rc8o1h6dROJ8tdTfcj67OQ&#x2F;view?utm_content=DAGvh7f-K4w&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U1_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAtvgz', 'G6_T1_U3_L4', '谁来控制汽车？——理解驾驶自动化等级', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生学习SAE驾驶自动化等级，理解人类与系统在不同等级下的任务分配，并通过实例了解当前与未来的自动驾驶能力差异。', NULL, NULL, NULL, '自动驾驶 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U3_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviIXkJy8/VFKYPV1T5tw317nkSTHHWA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviIXkJy8&#x2F;VFKYPV1T5tw317nkSTHHWA&#x2F;view?utm_content=DAGviIXkJy8&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U3_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAu0eC', 'G2_T2_U3_L1', '如何与机器人对话？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将探索人类如何向机器人或 AI 助手下达指令。他们将尝试不同的指令方式，并观察清晰的指令如何带来更好的结果。本课以简单的方式介绍提示词工程（Prompt Engineering）——让学生认识到 AI 不会“猜”我们的意思，只会执行明确的指令。学生还将使用“豆包”工具将优化后的提示词转化为 AI 生成的图片。', NULL, NULL, NULL, 'AI 与人机交互', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U3_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfuEeDkk/srk2aVT8CVVzIwBIeTaglA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfuEeDkk&#x2F;srk2aVT8CVVzIwBIeTaglA&#x2F;view?utm_content=DAGvfuEeDkk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U3_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAUADn', 'G1_T2_U2_L3', '再来一次——从生活循环到编码结构', NULL, 'G1', '通识课', NULL, 'CS素养', NULL, NULL, '从闹钟到四季，从糖果机到代码——世界在循环中运行！本课通过探索日常生活和自然界中熟悉的重复模式，引入“循环”概念。学生将识别周围的循环现象，理解循环在代码中的运行方式（循环结构与循环体），并通过创作、分析和编写简单的循环表达来应用这些概念。活动使用节奏模式和视觉重复，帮助学生培养计算思维和模式识别能力。', NULL, '循环；循环体；重复模式', NULL, '像程序员一样思考', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfYh4CBc/DB8Kv4uhN1d04BzkJCK0LQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfYh4CBc&#x2F;DB8Kv4uhN1d04BzkJCK0LQ&#x2F;view?utm_content=DAGvfYh4CBc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAuM2i', 'G6_T2_U5_L2', '地图上的文化——地图如何帮助我们看见、连接与理解文化', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学习地理信息与地理空间可视化的概念，通过案例理解文化故事的空间表达，并制作班级文化兴趣“热力图”进行反思。', NULL, NULL, NULL, '历史的时间与空间——数据如何讲述故事 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U5_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviX5f9sM/Ai1W7wwauVhgJQ7_kQ3-6Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviX5f9sM&#x2F;Ai1W7wwauVhgJQ7_kQ3-6Q&#x2F;view?utm_content=DAGviX5f9sM&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U5_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAunn4', 'G5_T2_U2_L4', '原型制作与测试——它能用吗？还能怎样改进？', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '学生将学习如何将自己的想法和计划转化为早期可用版本——原型，并与潜在用户测试。他们将探讨原型制作的重要性，理解如何收集有用反馈，并练习快速改进。通过 smartWork 案例，学生将看到团队如何分阶段测试、记录反馈并迭代优化产品。最终每组将完成简单原型并与同学测试。', NULL, NULL, NULL, '做老板：成为产品经理', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviNbxRL4/ufeIrgaMSHea34ioLeYBgQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviNbxRL4&#x2F;ufeIrgaMSHea34ioLeYBgQ&#x2F;view?utm_content=DAGviNbxRL4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAuumq', 'G5_T2_U4_L3', '抽象表示', NULL, 'G5', '情境课', NULL, NULL, NULL, NULL, '学生将探索抽象化的概念——简化复杂现实以聚焦关键信息，并理解它在智慧物流中的应用。他们将比较艺术与计算中的抽象，通过视觉分类任务练习创建自己的抽象，并理解地图如何作为现实空间与路径的抽象表示。课程结束时，学生将理解路径是位置间移动的简化表示，并为下一课的路径搜索学习做好准备。', NULL, NULL, NULL, '认识智慧物流', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh4dvuUk/qXkUiqmQBn2SNIWhKqbosw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh4dvuUk&#x2F;qXkUiqmQBn2SNIWhKqbosw&#x2F;view?utm_content=DAGvh4dvuUk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U4_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAv9jY', 'G2_T1_U3_L3', '计算机如何整理大量信息？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课介绍计算机如何使用列表、数组和表格等结构来管理多条信息。通过比较混乱与有序的数据，学生将学习数据结构如何帮助计算机更有效地存储和检索数据。活动强化了这样一个观点：就像我们在生活中使用清单或图表一样，计算机也需要“结构”来理解大量数据。', NULL, NULL, NULL, '从数据到行动——计算机如何工作', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuUBwLdFI/3Zr75Ymg3TUD0DBXGja_mQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuUBwLdFI&#x2F;3Zr75Ymg3TUD0DBXGja_mQ&#x2F;view?utm_content=DAGuUBwLdFI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U3_L3_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAvB6p', 'G7_T1_U3_L3', '从NLP到大型语言模型——自然语言处理与社会洞察', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课从基础的NLP过渡到探索新一代大型语言模型（LLM）。学生将回顾机器如何处理文本与情绪，并深入了解LLM不仅能理解还可以生成文本、图片等内容。通过实践活动，他们将学习设计有效提示词，尝试AI生成故事与图片，并反思AI生成内容的强大能力与局限性。', NULL, NULL, NULL, '自然语言处理与社会洞察', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvibbRfWg/EaLvHKkJ6QO3U-LfqQgCHA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvibbRfWg&#x2F;EaLvHKkJ6QO3U-LfqQgCHA&#x2F;view?utm_content=DAGvibbRfWg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAvEdd', 'G3_T1_U2_L3', '如何收集数据——帮博物馆设计问卷', NULL, 'G3', '情境课', NULL, NULL, NULL, NULL, '本课聚焦 PPDAC 模型的“计划”阶段。学生将探索不同的数据收集方式，并理解如何提出正确问题来解决问题。通过现实案例和问卷设计任务，学生将学习问卷调查如何帮助收集有用数据以做出决策。课堂最后，学生将为博物馆反馈项目设计一份简单的问卷。', NULL, NULL, NULL, '用数据解决问题', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoYkt9vA/SM3XWl8fNS6D8OmmmH13lg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoYkt9vA&#x2F;SM3XWl8fNS6D8OmmmH13lg&#x2F;view?utm_content=DAGuoYkt9vA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U2_L3_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAvL5t', 'G2_T2_U3_L2', 'AI 会说话吗？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索会说话的机器世界，了解 AI 如何生成语音。通过互动的听说活动，学生将听不同的 AI 声音、调整 AI 说话方式，并思考语调如何改变意思。核心概念是语音合成——AI 如何将文字转化为声音，以及语调（语音抑扬）和语言生成如何影响交流。', NULL, NULL, NULL, 'AI 与人机交互', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfn4FWu0/w0O5dAtX7SfU3xszMmdTTg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfn4FWu0&#x2F;w0O5dAtX7SfU3xszMmdTTg&#x2F;view?utm_content=DAGvfn4FWu0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U3_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAVpIT', 'G2_T1_U1_L2', '我们来拆一台笔记本！', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课引导学生探索笔记本电脑的内部结构。通过教师演示拆解、动手辨认部件和纸质拼贴活动，学生将了解到计算机由许多小部件组成，每个部件负责特定任务。本课通过比喻和故事讲述帮助学生理解各部件的作用，打破计算机是“魔法盒子”的印象，建立“计算机是一组小帮手协作工作”的基本概念。同时鼓励学生将所学知识与生活中其他电子产品联系起来。', NULL, NULL, NULL, '认识计算机', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGsdiY4zU0/udvutzyPimDCADdvWWaDQA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGsdiY4zU0&#x2F;udvutzyPimDCADdvWWaDQA&#x2F;view?utm_content=DAGsdiY4zU0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2上_U1_L2_Slides</a>，作者 宜斐', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAvPZJ', 'G7_T1_U1_L3', '逃出信息茧房——成为有意识的数字公民', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课介绍“信息茧房”概念，即算法如何个性化在线内容并可能限制我们接触多元观点。学生将观看视频、探讨信息茧房的形成机制，并讨论其影响。通过使用工作表，他们将识别自己的信息茧房并制定“破茧”策略。本课鼓励学生保持好奇心，主动获取舒适圈外的信息。', NULL, NULL, NULL, '算法与注意力——做数字世界的聪明人', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U1_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviU4C-YE/mt6J2Le_I9-dMtiQ4mlF2Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviU4C-YE&#x2F;mt6J2Le_I9-dMtiQ4mlF2Q&#x2F;view?utm_content=DAGviU4C-YE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U1_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAVw4P', 'G5_T1_U2_L1', '清洁地球，智慧起步——AI 如何帮助解决垃圾问题', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本单元第一课介绍了项目的核心挑战：设计并构建一台名为 Steve 的 AI 智能垃圾分类箱。学生将先探索全球垃圾问题，理解回收前分类的重要性，并以故事书角色和想象中的 AI 原型的方式认识“Steve”。通过讨论、多媒体资源和创意绘画活动，学生将提出智能垃圾箱的初步设计想法，这些想法将为后续的工程设计与 AI 学习奠定基础。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh7okE3c/VhUUvB5HvuPGKbGHGyJrCg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh7okE3c&#x2F;VhUUvB5HvuPGKbGHGyJrCg&#x2F;view?utm_content=DAGvh7okE3c&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAWA05', 'G6_T1_U4_L1', '构建自适应交通灯——从概念到元件准备', NULL, 'G6', '项目课', NULL, NULL, NULL, NULL, '学生回顾自适应交通控制原理，学习在Tinkercad中选取LED、电阻、光敏电阻等元件并搭建基础电路，为后续编程做准备。', NULL, NULL, NULL, '在 Tinkercad 中构建自适应交通灯', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviFlKNws/8ewnEc7O1zAbdG5zgKvYNQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviFlKNws&#x2F;8ewnEc7O1zAbdG5zgKvYNQ&#x2F;view?utm_content=DAGviFlKNws&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAWjlV', 'G2_T2_U2_L5', 'AI 如何理解人类的语言？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索人工智能（AI）系统（如智能音箱或语音助手）是如何理解人类语言的。通过有趣的动手活动，学生将发现 AI 如何“听”声音并找到重要的词，从而理解我们在说什么。课堂将模拟语音输入如何变成文字，把抽象的 AI 技术以具体、有趣的方式带入日常生活。', NULL, NULL, NULL, 'AI 如何感知世界', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U2_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfvEMisU/iOIZFqN8-Lngg69ffwkF1w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfvEMisU&#x2F;iOIZFqN8-Lngg69ffwkF1w&#x2F;view?utm_content=DAGvfvEMisU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U2_L5_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAWOBx', 'G2_T2_U4_L4', '机器人如何移动？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将探索机器人（或 AI 系统）如何像人类一样通过“感知—决策—行动”的过程来移动和做事。通过观察、绘画和动手路线设计活动，学生将理解 AI 是按照“感知 → 决策 → 执行”的顺序来工作的。他们将以清洁机器人为例，思考它如何知道去哪里、清理什么。课后，学生将能够描述并绘制这种决策路径。', NULL, NULL, NULL, 'AI 如何思考与决策', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U4_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfgaKMMA/Y-HZqgSsbmc52blWSNUsjg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfgaKMMA&#x2F;Y-HZqgSsbmc52blWSNUsjg&#x2F;view?utm_content=DAGvfgaKMMA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U4_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAwqOg', 'G7_T1_U1_L2', '热门内容能被信任吗？——理解真相幻觉与网络热度', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '本课探讨网络内容的热度（转发、点赞、评论）如何影响我们对其可信度和重要性的认知。学生将研究为什么被广泛分享或点赞的信息看起来更可信，以及重复曝光如何制造“真相的幻觉”。通过真实案例和互动讨论，学生将分析推荐算法、平台设计、机器人账号以及“沉默的大多数”在塑造网络舆论中的作用。', NULL, NULL, NULL, '算法与注意力——做数字世界的聪明人', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviRA0TAI/axyd-_KBjd7DH-AbiRBFNQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviRA0TAI&#x2F;axyd-_KBjd7DH-AbiRBFNQ&#x2F;view?utm_content=DAGviRA0TAI&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAwv7I', 'G3_T1_U3_L2', '通过调研了解顾客——我们怎么知道人们喜欢什么？', NULL, 'G3', '项目课', NULL, NULL, NULL, NULL, '本课引导学生以动手且贴近生活的方式探索用户调研的概念。学生将想象自己在学校开一家巧克力店，识别潜在顾客、选择目标群体，并学习提出有效问题以收集有用数据。通过这一过程，学生理解调研如何帮助做出更好的设计与商业决策。本课目标包括：了解“目标顾客”概念；认识三种常见的了解顾客的方法；练习用引导性问题框架设计迷你问卷。', NULL, NULL, NULL, '智能巧克力工坊：用数据设计', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G3_T1_U3_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGuoXmVSXk/neOUKYAwrJYXHDIAuSSOEg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGuoXmVSXk&#x2F;neOUKYAwrJYXHDIAuSSOEg&#x2F;view?utm_content=DAGuoXmVSXk&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G3上_U3_L2_Slides</a>，作者 Yijian Gu', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAWzLs', 'G2_T2_U4_L2', 'AI 如何学习符号？', NULL, 'G2', '通识课', NULL, NULL, NULL, NULL, '学生将探索人工智能（AI）是如何通过大量示例学习识别符号的。使用简单的符号（如形状或字母），学生将观察 AI 如何通过练习提高识别准确率。通过动手示例和讨论，学生将初步认识到“训练数据”的概念——看到“很多”有助于 AI 学习。本课通过贴近生活、可视化的任务，让机器学习等抽象概念变得具体有趣。', NULL, NULL, NULL, 'AI 如何思考与决策', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G2_T2_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfoF9-zg/Ujq61glJkcAYlWWqVZOZJg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfoF9-zg&#x2F;Ujq61glJkcAYlWWqVZOZJg&#x2F;view?utm_content=DAGvfoF9-zg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G2下_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAxAbb', 'G1_T1_U4_L1', '像素的秘密是什么？', NULL, 'G1', '通识课', NULL, '数字素养', NULL, NULL, '学生将探索数字图像是由称为“像素”的小彩色方块构成的。通过动手活动，他们将放大熟悉的图片，识别图像的基本构件，并重新创作简单的像素艺术设计。本课帮助学生认识到，屏幕上的图像不仅仅是画面，而是由颜色编码的方块集合构成，引入像素和 RGB 颜色编码的基础。', NULL, '像素；颜色编码（RGB）；图像构成', NULL, '数字媒体：用像素和声音表达', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U4_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfQuqYmw/ZYw5_KGDMCNy2HT8v6oA7A/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfQuqYmw&#x2F;ZYw5_KGDMCNy2HT8v6oA7A&#x2F;view?utm_content=DAGvfQuqYmw&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U4_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAXbwJ', 'G5_T1_U2_L2', 'Steve 的大脑——谁来理解这些数据？', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将从理解 Steve 如何“感知”世界转向他如何像大脑一样“理解”和处理数据。他们将探究感知与认知的区别，了解数据、算法与计算在 AI 中的作用，观察 AI 感知的真实案例（语音转文字与翻译），并学习微控制器——Steve 的真正“大脑”。课程以从感知到思考的步骤反思收尾，并预告下一阶段：行动。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh4F5Z78/7ZAaxvYfqJat2DNY2QOZ7w/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh4F5Z78&#x2F;7ZAaxvYfqJat2DNY2QOZ7w&#x2F;view?utm_content=DAGvh4F5Z78&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAxDzV', 'G6_T2_U4_L2', '你就是遥控器！——探索AI如何追踪你的身体控制数字世界', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学习AI如何识别并响应人体动作，结合数字艺术与博物馆互动案例，理解人体作为AI自然交互方式的原理与应用。', NULL, NULL, NULL, '在现实中穿行——探索XR中的文化与交互 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T2_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvidbSqvA/fAKZ7_x_yvkaAQaJUzSrfA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvidbSqvA&#x2F;fAKZ7_x_yvkaAQaJUzSrfA&#x2F;view?utm_content=DAGvidbSqvA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6下_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAxg1s', 'G7_T2_U3_L3', '探索未来职业的多样性与灵活性——人们的工作方式会改变吗？', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '理解技术时代下工作多样性与灵活性的重要性，通过技能卡、兴趣卡与技术卡创意组合设计未来职业，培养设计思维与团队协作能力。', NULL, NULL, NULL, 'AI时代的未来工作 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U3_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZVkUfnY/GD2mjfovgqV0lDQYd5h7sg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZVkUfnY&#x2F;GD2mjfovgqV0lDQYd5h7sg&#x2F;view?utm_content=DAGvZVkUfnY&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U3_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAxH7T', 'G1_T1_U2_L4', '世界有多随机？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '学生将通过比较随机事件与遵循规律或规则的事件来探索“随机性”概念。借助故事讲述、具体情境和手工制卡活动，学生将学习如何区分偶然发生的事物和有组织、有规律的事物。目标是让学生认识到日常生活中并非一切都有原因——有些事只是随机发生的。', NULL, '随机性；有序性；可预测性', NULL, '地图：探索空间与路径', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U2_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfUOsIfE/u3BuBtKtJi_-tbtumZJfWA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfUOsIfE&#x2F;u3BuBtKtJi_-tbtumZJfWA&#x2F;view?utm_content=DAGvfUOsIfE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U2_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAXHr2', 'G7_T1_U5_L2', '什么值得成为头条？——谁决定哪些内容值得读，人还是算法？', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将体验新闻选题的过程——既有算法筛选，也有人类编辑。他们将分组决定哪些故事足够重要可以进入校刊。通过比较AI推荐和人工投票，学生将理解技术与人类判断共同塑造新闻内容的方式。', NULL, NULL, NULL, '我们的声音，我们的新闻：AI驱动', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U5_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZXpSAg0/BY_9763ZEJvzhWlO6128sw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZXpSAg0&#x2F;BY_9763ZEJvzhWlO6128sw&#x2F;view?utm_content=DAGvZXpSAg0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U5_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAXVVh', 'G4_T2_U4_L3', '搭建并测试你的在线推荐系统——从数据到推荐', NULL, 'G4', '项目课', NULL, NULL, NULL, NULL, '本课将第二课中制定的规则转化为可运行的数字化推荐系统，学生将学习在飞书多维表中存储图书数据、应用规则过滤并生成个性化图书清单，比较人工与数字推荐效果并优化规则。', NULL, NULL, NULL, '从读者到策展人：AI 驱动的图书推荐', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G4_T2_U4_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvf_umMsE/kHqdnCNecbq9aJ5LumS_Pg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvf_umMsE&#x2F;kHqdnCNecbq9aJ5LumS_Pg&#x2F;view?utm_content=DAGvf_umMsE&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G4下_U4_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAyqRl', 'G7_T1_U5_L4', '设计你的新闻简报——怎样设计才能吸引所有人的目光？', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '作为单元的最后一课，学生将成为真正的编辑团队。他们将通过分析报纸和杂志的案例学习新闻设计的基础，然后小组协作设计自己的新闻简报，结合人工撰写和AI生成的内容，并明确标注来源以保持透明性。最后，学生将在画廊式展览中展示简报，同伴将使用评分量表进行投票与评价。', NULL, NULL, NULL, '我们的声音，我们的新闻：AI驱动', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T1_U5_L4.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZcQLYy0/gZPzSBtj9I-cNUUQ3NfRrw/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZcQLYy0&#x2F;gZPzSBtj9I-cNUUQ3NfRrw&#x2F;view?utm_content=DAGvZcQLYy0&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7上_U5_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAyrr5', 'G5_T1_U2_L3', 'Steve 行动——从思考到执行', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '本课中，学生将学习 Steve 如何通过执行器（特别是舵机）将“思考”转化为“行动”。他们将了解舵机的工作原理、微控制器如何用 PWM 信号控制舵机，以及如何用 Mind+ 进行接线与编程。本节是 AI 决策与物理执行的桥梁，为下一阶段的 AI 自动分类做准备。', NULL, NULL, NULL, 'Steve：垃圾潜水员——设计与构建 AI 智能垃圾分类箱', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U2_L3.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh1RIWkA/v2guhFC0_-38G7CkloEkow/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh1RIWkA&#x2F;v2guhFC0_-38G7CkloEkow&#x2F;view?utm_content=DAGvh1RIWkA&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U2_L3_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAyTeP', 'G1_T2_U3_L6', '成果展示与评价——庆祝我们的故事与程序', NULL, 'G1', '项目课', NULL, '设计思维', NULL, NULL, '本课是本单元 PBL 项目的成果展示环节。学生将以“故事策展人”的身份，在“花园展览”形式中，通过“三层递进式评价活动”（小组互评→迭代优化→班级展示）进行分享与交流。评价采用“花园策展 × 微笑诊断 × 勋章”体系，在“展示—评价—改进”的闭环中培养温暖的数字创作者。', NULL, '用户体验；作品评价；迭代改进', NULL, '用 ScratchJr 探索编程', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T2_U3_L6.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfrE6E4I/FSppifztRHt2Y-UdboJlNQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfrE6E4I&#x2F;FSppifztRHt2Y-UdboJlNQ&#x2F;view?utm_content=DAGvfrE6E4I&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1下_U3_L6_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAyZqA', 'G1_T1_U4_L2', '你如何用像素作画？', NULL, 'G1', '通识课', NULL, '媒体素养', NULL, NULL, '学生将发现数字图片是由称为“像素”的小方块构成的。通过将数字艺术与贴纸马赛克、纸上绘画进行比较，学生将学习艺术家如何利用像素和图层构建图像。使用在线像素艺术平台，他们将创作简单的数字肖像并探索数字设计的基础知识。本课介绍数字绘图工具以及图层在组织与提升图像中的作用。', NULL, '像素绘图；图层；数字创作工具', NULL, '数字媒体：用像素和声音表达', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfYjHg6Q/YXCjzd-Ra4whGiqt7jAYUA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfYjHg6Q&#x2F;YXCjzd-Ra4whGiqt7jAYUA&#x2F;view?utm_content=DAGvfYjHg6Q&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAYZUi', 'G5_T1_U1_L1', 'AI 的感官系统——AI 如何看、听和感受世界？', NULL, 'G5', '通识课', NULL, NULL, NULL, NULL, '本课中，学生将探索 AI 的感官系统，并与人类感官进行类比。他们将了解到 AI 依赖特定硬件——传感器、处理器、网络和执行器——来感知并与物理世界互动。课程介绍 AI 理解的三个阶段——感知（Perception）、表征（Representation）和推理（Reasoning），并引导学生思考人类与 AI 感知的优势与局限。到课终，学生将能识别人类感官及对应的 AI 传感器，解释为什么仅有感知不足以理解，并能构想自己的多传感器 AI 系统。', NULL, NULL, NULL, '硬核 AI——AI 硬件与基础设施', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T1_U1_L1.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvh9b4mKo/_Vlg7S54sH4qtn6VW0PVFQ/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvh9b4mKo&#x2F;_Vlg7S54sH4qtn6VW0PVFQ&#x2F;view?utm_content=DAGvh9b4mKo&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5上_U1_L1_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAZBsM', 'G7_T2_U4_L2', '结构与技能：开始制作我的数字简历', NULL, 'G7', '项目课', NULL, NULL, NULL, NULL, '学习简历结构与各部分作用，通过技能排序与“未来自我技能图”识别优势与待提升领域，使用Canva制作简历初稿。', NULL, NULL, NULL, '数字简历', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U4_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvZWWxLy4/x7CutGCX2XZDJDn2OsnMfg/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvZWWxLy4&#x2F;x7CutGCX2XZDJDn2OsnMfg&#x2F;view?utm_content=DAGvZWWxLy4&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U4_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAzFv2', 'G7_T2_U2_L2', 'AI如何改变我们的学习、医疗与创作方式？', NULL, 'G7', '通识课', NULL, NULL, NULL, NULL, '探讨AI在教育、医疗、创意产业的应用与影响，通过案例与动手活动体验AI辅助创作，反思优势、挑战及人机角色变化。', NULL, NULL, NULL, '现实世界中的AI系统：逻辑、协作与边界 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G7_T2_U2_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvirTyAps/JBXlnfz0L6CggjRLZSC7wA/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvirTyAps&#x2F;JBXlnfz0L6CggjRLZSC7wA&#x2F;view?utm_content=DAGvirTyAps&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G7下_U2_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAZnog', 'G6_T1_U1_L2', '智慧城市解决了哪些问题？——探索全球真实挑战与智慧解决方案', NULL, 'G6', '情境课', NULL, NULL, NULL, NULL, '学生通过全球真实案例，了解不同城市如何利用技术应对交通、公共卫生、能源和城市管理等领域的挑战，认识智慧城市是技术与需求结合的产物，并设计自己的“迷你智慧街道”解决社区问题。', NULL, NULL, NULL, '智慧社会与人工智能 ', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G6_T1_U1_L2.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGviMldnWU/kGX9KohVd0HNNrKXejMH_g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGviMldnWU&#x2F;kGX9KohVd0HNNrKXejMH_g&#x2F;view?utm_content=DAGviMldnWU&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G6上_U1_L2_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recv53KVmAZVRa', 'G5_T2_U3_L5', '试玩、测试与迭代', NULL, 'G5', '项目课', NULL, NULL, NULL, NULL, '在本单元的压轴课中，学生将展示自己的游戏，互相试玩并给予建设性反馈。他们将学习根据明确标准（趣味性、挑战性、视觉效果、操作、声音、Bug）进行评价，并利用反馈进行针对性改进。课程重点是同伴评审、迭代，以及从概念到优化成品的过程庆祝。', NULL, NULL, NULL, 'AI × 游戏：从LLM到可玩原型', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G5_T2_U3_L5.jpg', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvmka9TEc/jxW2_OZOmkrWyQc_evAq2g/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvmka9TEc&#x2F;jxW2_OZOmkrWyQc_evAq2g&#x2F;view?utm_content=DAGvmka9TEc&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G5下_U3_L5_Slides</a>，作者 Manchi', '2025-12-25 00:00:00', '2026-03-06 00:00:00');
INSERT INTO `aiedu_literacy_class` VALUES ('recw5pCCUU', 'G1_T1_U1_L4', '你能破解网格的密码吗？', NULL, 'G1', '通识课', NULL, '数据素养', NULL, NULL, '学生将探索网格如何帮助我们组织和查找信息，就像地图或座位表一样。在上一课学习行和列的基础上，他们将学习如何读取坐标并利用它破解一个简单的密码。通过现实类比和动手解谜，学生将在趣味中加深对数据结构的理解。关键概念是利用行-列位置来定位或表示信息。', NULL, '坐标编码；位置映射；信息解码', NULL, '看见结构：我们如何组织数据', NULL, 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ai_course/G1_T1_U1_L4.png', '<div style=\"position: relative; width: 100%; height: 0; padding-top: 56.2500%;\n padding-bottom: 0; box-shadow: 0 2px 8px 0 rgba(63,69,81,0.16); margin-top: 1.6em; margin-bottom: 0.9em; overflow: hidden;\n border-radius: 8px; will-change: transform;\">\n  <iframe loading=\"lazy\" style=\"position: absolute; width: 100%; height: 100%; top: 0; left: 0; border: none; padding: 0;margin: 0;\"\n    src=\"https://education.braightidea.com/canva-design/DAGvfV69rmg/D2cWX2TngBRr6ugAt7Sk0Q/view?embed\" allowfullscreen=\"allowfullscreen\" allow=\"fullscreen\">\n  </iframe>\n</div>\n<a href=\"https:&#x2F;&#x2F;www.canva.cn&#x2F;design&#x2F;DAGvfV69rmg&#x2F;D2cWX2TngBRr6ugAt7Sk0Q&#x2F;view?utm_content=DAGvfV69rmg&amp;utm_campaign=designshare&amp;utm_medium=embeds&amp;utm_source=link\" target=\"_blank\" rel=\"noopener\">G1上_U1_L4_Slides</a>，作者 Iris', '2025-12-25 00:00:00', '2026-03-06 00:00:00');

-- ----------------------------
-- Table structure for aiedu_quiz_question
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_quiz_question`;
CREATE TABLE `aiedu_quiz_question`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '题目ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '题目类型（single | multiple | boolean）',
  `question` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '题目内容',
  `question_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT '题目英文内容',
  `options_jsonarray` json NULL COMMENT '选项列表（JSON格式）',
  `options_en_jsonarray` json NULL COMMENT '选项列表英文（JSON格式）',
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT '解析说明',
  `points` int NULL DEFAULT 10 COMMENT '题目分值',
  `customized` tinyint NULL DEFAULT 0 COMMENT '是否自定义题目',
  `answer_json` json NULL COMMENT '题目答案',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `courseware_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '关联课件id',
  `tool_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT 'aiedu_aitool.tool_id',
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '来源：ai-tool 来源ai工具, courseware 来源课件, bank 系统题目, custom 自定义题目',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '测验题目信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_quiz_question
-- ----------------------------
INSERT INTO `aiedu_quiz_question` VALUES (1, 'single', '什么是人工智能？', 'What is Artificial Intelligence?', '[\"让机器像人一样思考\", \"一种编程语言\", \"一种硬件设备\", \"一个操作系统\"]', '[\"Making machines think like humans\", \"A programming language\", \"A hardware device\", \"An operating system\"]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:05', NULL, NULL, 'ai-tool');
INSERT INTO `aiedu_quiz_question` VALUES (2, 'multiple', 'AI 可以应用在哪些领域？', 'Which fields can AI be applied to?', '[\"医疗诊断\", \"自动驾驶\", \"语音识别\", \"游戏娱乐\"]', '[\"Medical diagnosis\", \"Autonomous driving\", \"Voice recognition\", \"Gaming\"]', NULL, 10, 0, '[0, 1, 2, 3]', '2026-02-02 21:51:51', '2026-02-04 21:21:05', NULL, NULL, 'ai-tool');
INSERT INTO `aiedu_quiz_question` VALUES (3, 'boolean', 'AI 需要大量数据才能学习吗？', 'Does AI need large amounts of data to learn?', '[]', '[]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:06', NULL, NULL, 'ai-tool');
INSERT INTO `aiedu_quiz_question` VALUES (4, 'boolean', '机器学习是 AI 的一个分支吗？', 'Is machine learning a branch of AI?', '[]', '[]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:06', NULL, NULL, 'ai-tool');
INSERT INTO `aiedu_quiz_question` VALUES (5, 'single', '以下哪个是监督学习的例子？', 'Which is an example of supervised learning?', '[\"图像分类\", \"随机游走\", \"无目标探索\", \"自绘画\"]', '[\"Image classification\", \"Random walk\", \"Aimless exploration\", \"Free drawing\"]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:08', NULL, NULL, 'ai-tool');
INSERT INTO `aiedu_quiz_question` VALUES (6, 'single', '神经网络是模仿什么设计的？', 'What is a neural network designed to mimic?', '[\"人脑神经元\", \"计算机芯片\", \"电路板\", \"数据库\"]', '[\"Brain neurons\", \"Computer chips\", \"Circuit boards\", \"Databases\"]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:16', NULL, NULL, 'courseware');
INSERT INTO `aiedu_quiz_question` VALUES (7, 'multiple', '训练 AI 模型需要哪些步骤？', 'What steps are needed to train an AI model?', '[\"收集数据\", \"标注数据\", \"训练模型\", \"测试模型\"]', '[\"Collect data\", \"Label data\", \"Train model\", \"Test model\"]', NULL, 10, 0, '[0, 1, 2, 3]', '2026-02-02 21:51:51', '2026-02-04 21:21:17', NULL, NULL, 'courseware');
INSERT INTO `aiedu_quiz_question` VALUES (8, 'boolean', 'AI 可以完全替代人类的工作吗？', 'Can AI completely replace human work?', '[]', '[]', NULL, 10, 0, '[1]', '2026-02-02 21:51:51', '2026-02-04 21:21:17', NULL, NULL, 'courseware');
INSERT INTO `aiedu_quiz_question` VALUES (9, 'single', '深度学习使用的是什么类型的网络？', 'What type of network does deep learning use?', '[\"多层神经网络\", \"简单逻辑门\", \"单层感知器\", \"线性回归\"]', '[\"Multi-layer neural networks\", \"Simple logic gates\", \"Single-layer perceptron\", \"Linear regression\"]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:18', NULL, NULL, 'courseware');
INSERT INTO `aiedu_quiz_question` VALUES (10, 'boolean', 'AI 训练时需要调整参数吗？', 'Does AI training require parameter adjustment?', '[]', '[]', NULL, 10, 0, '[0]', '2026-02-02 21:51:51', '2026-02-04 21:21:20', NULL, NULL, 'courseware');
INSERT INTO `aiedu_quiz_question` VALUES (11, 'single', 'AI模型训练需要哪种类型的数据？', 'What type of data does AI model training require?', '[\"标注过的数据\", \"随机数据\", \"只有文字\", \"不需要数据\"]', '[\"Labeled data\", \"Random data\", \"Only text\", \"No data needed\"]', NULL, 10, 0, '[0]', '2026-02-04 21:21:54', '2026-02-04 21:21:54', NULL, NULL, 'bank');
INSERT INTO `aiedu_quiz_question` VALUES (12, 'multiple', '影响AI识别准确率的因素有哪些？（多选）', 'What factors affect AI recognition accuracy? (Multiple)', '[\"样本数量\", \"数据多样性\", \"背景环境\", \"训练时间\"]', '[\"Sample quantity\", \"Data diversity\", \"Background environment\", \"Training time\"]', NULL, 10, 0, '[0, 1, 2]', '2026-02-05 10:29:18', '2026-02-05 10:29:18', NULL, NULL, 'bank');


-- ----------------------------
-- Table structure for aiedu_resource
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_resource`;
CREATE TABLE `aiedu_resource`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '内容类型 video | news | course | work',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '中文标题',
  `title_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '英文标题',
  `cover_image` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '中文摘要',
  `summary_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '英文摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容（HTML/Markdown）',
  `tag` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标签（中文）',
  `tag_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标签（英文）',
  `featured` tinyint(1) NULL DEFAULT 0 COMMENT '是否精选',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `link_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '链接类型 internal, external, canva',
  `link_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '外部链接/Canva链接',
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者',
  `duration` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '时长（视频）',
  `grade` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '年级范围',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_created_time`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI教育资源表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_resource
-- ----------------------------
INSERT INTO `aiedu_resource` VALUES (1, 'video', 'AI编程入门', 'Introduction to AI Programming', 'https://images.unsplash.com/photo-1516116216624-53e697fedbea?w=800', 'Python基础与机器学习入门', 'Python basics and machine learning introduction', '', '[\"编程\"]', '[\"Programing\"]', 1, '2025-12-31 15:02:13', '2025-12-31 18:50:47', 'internal', '', '王五', '45分钟', 'L2-L3');
INSERT INTO `aiedu_resource` VALUES (2, 'work', '智能垃圾分类系统', 'Smart Waste Classification', 'https://images.unsplash.com/photo-1532996122724-e3c354a0b15b?w=800', 'G7学生团队作品', 'G7学生团队作品', '', '[\"学生作品\"]', '[\"Student Works\"]', 1, '2025-12-31 15:02:13', '2025-12-31 18:53:49', 'internal', '', '王明团队', '', 'G7');
INSERT INTO `aiedu_resource` VALUES (3, 'course', '图像识别实战项目', 'Image Recognition Project', 'https://images.unsplash.com/photo-1530836369250-ef72a3f5cda8?w=800', 'G2下_U1_L1 - 学生通过训练模型识别校园植物', 'G2 U1 L1 - Students train models to recognize campus plants', '', '[\"实战\"]', '[\"Action\"]', 1, '2025-12-31 15:07:53', '2025-12-31 18:56:14', 'canva', 'https://education.braightidea.com/canva-design/DAGsMfX4GZU/G--lGpPP92I7PfbK2tZlKA/view', '王明团队', '20分钟', 'G5-G6');
INSERT INTO `aiedu_resource` VALUES (4, 'news', 'brAIght idea获AI教育创新奖', 'brAIght idea Wins AI Education Innovation Award', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800', '在2024教育科技峰会上获得认可', 'Recognized at 2024 EdTech Summit', '', '[\"AI教育\"]', '[\"AI Education\"]', 0, '2025-12-31 15:10:58', '2026-02-28 10:21:53', 'external', 'https://baidu.com', '', '10分钟', '新闻');

-- ----------------------------
-- Table structure for aiedu_solution
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_solution`;
CREATE TABLE `aiedu_solution`  (
  `tid` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '解决方案编码',
  `bg_color` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '背景色',
  `text_color` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '字体颜色',
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '标题-中文',
  `title_en` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '标题-英文',
  `title_desktop` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '标题-中文',
  `title_desktop_en` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '标题-英文',
  `title_mobile` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '标题-中文',
  `title_mobile_en` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '标题-英文',
  `features` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '特点',
  `features_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '特点-英文',
  `image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '背景图片',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '图标',
  `content_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT '详细内容',
  PRIMARY KEY (`tid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_solution
-- ----------------------------
INSERT INTO `aiedu_solution` VALUES (1, 'schools', '#daef68', '#daef68', '为学校构建可持续可落地的AI教育体系', 'Building Sustainable and Practical AI Education Systems for Schools', '为学校构建可持续可落地的AI教育体系', 'Building Sustainable and Practical AI Education Systems for Schools', '为学校构建可持续可落地的<br/>AI教育体系', 'Building Sustainable and Practical<br/>AI Education Systems for Schools', '课程体系｜学习平台｜智慧教室｜师资培训', 'Curriculum | Learning Platform | Smart Classroom | Teacher Training', 'https://images.unsplash.com/photo-1652766399415-aa89236590fa?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxzY2hvb2wlMjBjbGFzc3Jvb20lMjBzdHVkZW50c3xlbnwxfHx8fDE3NjYzNzMwODB8MA&ixlib=rb-4.1.0&q=80&w=1080', 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/ce46310c-41cd-40e0-9e0f-1098ae21ef65.png', '{\"sectionHero\":{\"title\":\"为什么这件事现在必须被认真对待？\",\"titleEn\":\"Why Does This Matter Now?\",\"description\":\"AI 不是未来的技术，而是当下学生必须理解和运用的工具。学校的责任不是追赶技术浪潮，而是帮助每一位学生建立对 AI 的正确认知、批判性思考能力，以及在真实场景中负责任地使用 AI 的素养。这需要系统性的课程设计、持续的教师支持，以及学校层面的长期承诺。\",\"descriptionEn\":\"AI is not a future technology, but a tool students must understand and use today. Schools are responsible not for chasing technology trends, but for helping every student develop proper AI cognition, critical thinking, and the literacy to use AI responsibly in real scenarios. This requires systematic curriculum design, ongoing teacher support, and long-term institutional commitment.\",\"imageUrl\":\"https://images.unsplash.com/photo-1523050854058-8df90110c9f1?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"School AI education\"},\"sectionSupport\":{\"title\":\"我们如何帮助学校真正落地？\",\"titleEn\":\"How Do We Help Schools Truly Implement?\",\"description\":\"我们不是提供单一课程或工具，而是围绕学生学习、教师成长与学校实施，构建一套可持续运行的 AI 教育支持体系。\",\"descriptionEn\":\"We don\'t provide a single curriculum or tool, but build a sustainable AI education support system around student learning, teacher development, and school implementation.\",\"supports\":[{\"title\":\"课程与学习体系\",\"titleEn\":\"Curriculum & Learning System\",\"subTitle\":\"分层、长期、可扩展的学习路径，让学习真实发生\",\"subTitleEn\":\"Tiered, long-term, scalable learning paths that enable real learning\",\"items\":[{\"title\":\"覆盖不同学段与目标的分层 AI 课程体系\",\"titleEn\":\"Tiered AI curriculum covering different grades and objectives\"},{\"title\":\"聚焦素养、判断与真实问题解决\",\"titleEn\":\"Focus on literacy, judgment, and real problem-solving\"},{\"title\":\"学生在统一学习空间中完成学习与实践\",\"titleEn\":\"Students learn and practice in unified learning spaces\"}]},{\"title\":\"教师支持与专业发展\",\"titleEn\":\"Teacher Support & Development\",\"subTitle\":\"持续支持教师，而非一次培训\",\"subTitleEn\":\"Continuous teacher support, not one-time training\",\"items\":[{\"title\":\"聚焦教师的判断力与课堂实践\",\"titleEn\":\"Focus on teacher judgment and classroom practice\"},{\"title\":\"持续支持 AI 融入真实学科教学\",\"titleEn\":\"Ongoing support for AI integration in real subject teaching\"},{\"title\":\"帮助教师逐步建立信心与经验\",\"titleEn\":\"Help teachers gradually build confidence and experience\"}]},{\"title\":\"实施与共建\",\"titleEn\":\"Implementation & Co-creation\",\"subTitle\":\"与学校一起跑通，从实施到评估再到迭代\",\"subTitleEn\":\"Run together with schools, from implementation to evaluation to iteration\",\"items\":[{\"title\":\"与学校共同制定清晰的实施路径\",\"titleEn\":\"Co-develop clear implementation paths with schools\"},{\"title\":\"持续跟进教学中的真实发生情况\",\"titleEn\":\"Continuously track real teaching situations\"},{\"title\":\"通过教研评估推动改进与迭代\",\"titleEn\":\"Drive improvement and iteration through teaching research evaluation\"}]}]},\"sectionScene\":{\"title\":\"AI 教育在学校中如何真正发生？\",\"titleEn\":\"How Does AI Education Actually Happen in Schools?\",\"scenes\":[{\"title\":\"在课堂中，学生从\\\"使用 AI\\\"走向\\\"理解 AI\\\"\",\"titleEn\":\"In Classrooms: From \\\"Using AI\\\" to \\\"Understanding AI\\\"\",\"items\":[{\"title\":\"在教师引导下理解 AI 的能力、边界与适用情境\",\"titleEn\":\"Understand AI capabilities, boundaries, and applicable contexts under teacher guidance\"},{\"title\":\"通过真实问题学习提出好问题与作出判断\",\"titleEn\":\"Learn to ask good questions and make judgments through real problems\"},{\"title\":\"在学习过程中形成负责任使用 AI 的意识\",\"titleEn\":\"Develop responsible AI usage awareness during learning\"}],\"case\":{\"title\":\"深圳某中学｜L1–L4 课程体系｜学生项目获全国性展示\",\"titleEn\":\"Shenzhen School | L1–L4 Curriculum | Student Projects Nationally Showcased\"},\"imageUrl\":\"https://images.unsplash.com/photo-1686945448867-6047dfcd1654?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Students learning with AI\"},{\"title\":\"在真实教学中，教师逐步建立信心与方法\",\"titleEn\":\"In Real Teaching: Teachers Build Confidence and Methods\",\"items\":[{\"title\":\"从\\\"不确定如何开始\\\"到在课堂中自然使用 AI\",\"titleEn\":\"From \\\"uncertain how to start\\\" to naturally using AI in classrooms\"},{\"title\":\"在教研与同伴交流中不断反思与优化教学实践\",\"titleEn\":\"Continuously reflect and optimize teaching through collaboration and peer exchange\"},{\"title\":\"将 AI 融入学科教学，而非作为额外负担\",\"titleEn\":\"Integrate AI into subject teaching, not as an additional burden\"}],\"case\":{\"title\":\"上海某国际学校｜40+ 教师参与｜校本 AI 素养课程持续实施\",\"titleEn\":\"Shanghai International School | 40+ Teachers | School-based AI Curriculum Ongoing\"},\"imageUrl\":\"https://images.unsplash.com/photo-1571260899304-425eee4c7efc?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Teachers professional development\"},{\"title\":\"通过 Camp 与 Workshop，形成关键的深度体验\",\"titleEn\":\"Through Camps & Workshops: Deep Learning Experiences\",\"items\":[{\"title\":\"以项目制与集中式学习方式展开跨学科探索\",\"titleEn\":\"Conduct interdisciplinary exploration through project-based and intensive learning\"},{\"title\":\"在短周期内获得对 AI 的整体理解与实践经验\",\"titleEn\":\"Gain holistic AI understanding and practical experience in short cycles\"},{\"title\":\"常作为课程体系的补充或实施起点\",\"titleEn\":\"Often serves as curriculum supplement or implementation starting point\"}],\"case\":{\"title\":\"AI Camp / Workshop｜项目制学习｜短周期深度体验\",\"titleEn\":\"AI Camp / Workshop | Project-based Learning | Short-cycle Deep Experience\"},\"imageUrl\":\"https://images.unsplash.com/photo-1520569495996-b5e1219cb625?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"AI Camp and Workshop\"}]}}');
INSERT INTO `aiedu_solution` VALUES (2, 'teachers', '#49ef8b', '#49ef8b', '为教师提供真正有效的AI教学与教研支持', 'Providing Truly Effective AI Teaching and Research Support for Teachers', '为教师提供真正有效的AI教学与教研支持', 'Providing Truly Effective AI Teaching and Research Support for Teachers', '为教师提供真正有效的<br/>AI教学与教研支持', 'Providing Truly Effective AI Teaching<br/>and Research Support for Teachers', '即用课件｜智能工具｜专业发展｜教研赋能', 'Ready-to-use Materials | Smart Tools | Professional Development | Research Empowerment', 'https://images.unsplash.com/photo-1544191046-397b734b0891?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHx0ZWFjaGVyJTIwY2xhc3Nyb29tJTIwZWR1Y2F0aW9ufGVufDF8fHx8MTc2NjQ2NjcxMHww&ixlib=rb-4.1.0&q=80&w=1080', 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/9553c12a-9c5a-4a28-ba6a-aa4bde02285b.png', '{\"sectionHero\":{\"title\":\"为什么 AI 教学支持现在必须被认真对待？\",\"titleEn\":\"Why Does AI Teaching Support Matter Now?\",\"description\":\"AI 正在进入课堂，但教师往往缺乏清晰的教学判断与可行路径。如果没有合适的支持，AI 容易成为额外负担，而非教学助力。教师需要的是可落地的教学支持，而不是更多工具要求。\",\"descriptionEn\":\"AI is entering classrooms, but teachers often lack clear pedagogical judgment and viable pathways. Without proper support, AI easily becomes an additional burden rather than teaching assistance. Teachers need implementable teaching support, not more tool requirements.\",\"imageUrl\":\"https://images.unsplash.com/photo-1524178232363-1fb2b075b655?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Teacher AI support\"},\"sectionSupport\":{\"title\":\"我们如何支持教师真正开展 AI 教学？\",\"titleEn\":\"How Do We Support Teachers in Real AI Teaching?\",\"description\":\"我们不是提供单一课程或工具，而是围绕教师的教学判断、课堂实践与专业成长，构建一套可持续的支持体系。\",\"descriptionEn\":\"We don\'t provide a single curriculum or tool, but build a sustainable support system around teachers\' pedagogical judgment, classroom practice, and professional growth.\",\"supports\":[{\"title\":\"课程与教学资源支持\",\"titleEn\":\"Curriculum & Teaching Resources\",\"subTitle\":\"提供可灵活选用的教学资源，而非固定课件\",\"subTitleEn\":\"Flexible teaching resources, not fixed courseware\",\"items\":[{\"title\":\"提供与学科教学相关的 AI 教学资源与课程示例\",\"titleEn\":\"AI teaching resources and course examples related to subject teaching\"},{\"title\":\"支持教师根据课堂需要灵活选用与调整\",\"titleEn\":\"Support teachers to flexibly select and adjust based on classroom needs\"},{\"title\":\"聚焦教学目标与学生能力，而非技术演示\",\"titleEn\":\"Focus on teaching goals and student abilities, not tech demos\"}]},{\"title\":\"教师专业发展支持\",\"titleEn\":\"Teacher Professional Development\",\"subTitle\":\"持续支持，而非一次培训\",\"subTitleEn\":\"Continuous support, not one-time training\",\"items\":[{\"title\":\"以教师的教学判断与课堂实践为核心\",\"titleEn\":\"Centered on teachers\' pedagogical judgment and classroom practice\"},{\"title\":\"通过持续支持而非一次培训建立信心\",\"titleEn\":\"Build confidence through ongoing support, not one-time training\"},{\"title\":\"在真实教学中逐步理解与使用 AI\",\"titleEn\":\"Gradually understand and use AI in real teaching\"}]},{\"title\":\"教学实践与教研支持\",\"titleEn\":\"Teaching Practice & Research Support\",\"subTitle\":\"在实践中反思，在教研中成长\",\"subTitleEn\":\"Reflect in practice, grow through research\",\"items\":[{\"title\":\"支持教师在教学实践中进行反思与改进\",\"titleEn\":\"Support teachers to reflect and improve in teaching practice\"},{\"title\":\"提供清晰、可理解的教学反馈与教研支持\",\"titleEn\":\"Provide clear, understandable teaching feedback and research support\"},{\"title\":\"帮助教师逐步形成可复用的教学经验\",\"titleEn\":\"Help teachers gradually form reusable teaching experience\"}]}]},\"sectionScene\":{\"title\":\"AI 教学在课堂中如何真正发生？\",\"titleEn\":\"How Does AI Teaching Actually Happen in Classrooms?\",\"scenes\":[{\"title\":\"在课堂中，教师找到 AI 的教学位置\",\"titleEn\":\"In Classrooms: Teachers Find AI\'s Pedagogical Position\",\"items\":[{\"title\":\"明确 AI 在教学中的作用与边界\",\"titleEn\":\"Clarify AI\'s role and boundaries in teaching\"},{\"title\":\"围绕学习目标判断是否、如何使用 AI\",\"titleEn\":\"Judge whether and how to use AI around learning objectives\"},{\"title\":\"保持教学主导权，而非技术先行\",\"titleEn\":\"Maintain pedagogical autonomy, not technology-first\"}],\"case\":{\"title\":\"课堂教学实践案例\",\"titleEn\":\"Classroom Teaching Practice Cases\"},\"imageUrl\":\"https://images.unsplash.com/photo-1524178232363-1fb2b075b655?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Teacher using AI in classroom\"},{\"title\":\"在教研中，教师逐步形成教学方法\",\"titleEn\":\"In Research: Teachers Gradually Form Teaching Methods\",\"items\":[{\"title\":\"在同伴交流中分享与反思教学实践\",\"titleEn\":\"Share and reflect on teaching practice in peer exchange\"},{\"title\":\"从尝试走向稳定可用的教学设计\",\"titleEn\":\"Move from experimentation to stable, usable teaching design\"},{\"title\":\"将经验沉淀为可复用的教学方案\",\"titleEn\":\"Distill experience into reusable teaching plans\"}],\"case\":{\"title\":\"校本教研 / 教师工作坊\",\"titleEn\":\"School-based Research / Teacher Workshops\"},\"imageUrl\":\"https://images.unsplash.com/photo-1552664730-d307ca884978?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Teachers in professional development\"},{\"title\":\"通过 Workshop 与培训，获得关键支持\",\"titleEn\":\"Through Workshops & Training: Gain Key Support\",\"items\":[{\"title\":\"通过集中式体验快速理解教学可能性\",\"titleEn\":\"Quickly understand teaching possibilities through intensive experience\"},{\"title\":\"在安全环境中尝试新的教学方式\",\"titleEn\":\"Try new teaching methods in a safe environment\"},{\"title\":\"常作为教学转型或课程引入的起点\",\"titleEn\":\"Often serves as starting point for teaching transformation or curriculum introduction\"}],\"case\":{\"title\":\"教师 Workshop / 专项培训\",\"titleEn\":\"Teacher Workshop / Specialized Training\"},\"imageUrl\":\"https://images.unsplash.com/photo-1531482615713-2afd69097998?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Teacher workshop and training\"}]}}');
INSERT INTO `aiedu_solution` VALUES (3, 'parents', '#ffb2ed', '#ffb2ed', '为家庭提供清晰可靠的AI学习与成长支持', 'Offering Clear and Reliable AI Learning and Growth Support for Families', '为家庭提供清晰可靠的AI学习与成长支持', 'Offering Clear and Reliable AI Learning and Growth Support for Families', '为家庭提供清晰可靠的<br/>AI学习与成长支持', 'Offering Clear and Reliable AI Learning<br/>and Growth Support for Families', '家庭指南｜免费课程｜学习报告｜陪伴系统', 'Home Guidance | Free Courses | Learning Reports | Companion System', 'https://images.unsplash.com/photo-1476703993599-0035a21b17a9?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&ixid=M3w3Nzg4Nzd8MHwxfHNlYXJjaHwxfHxmYW1pbHklMjBsZWFybmluZyUyMHRvZ2V0aGVyfGVufDF8fHx8MTc2NjQ3NTI3Mnww&ixlib=rb-4.1.0&q=80&w=1080', 'https://braight-dc-resource.oss-cn-shanghai.aliyuncs.com/edu_product/cms/7ef39be1-4a7b-48c0-9101-d6ac8fcfba42.png', '{\"sectionHero\":{\"title\":\"为什么家庭需要认真面对孩子的 AI 学习？\",\"titleEn\":\"Why Do Families Need to Take Children\'s AI Learning Seriously?\",\"description\":\"AI 正在快速进入孩子的学习与生活，但家庭往往缺乏清晰判断与可靠指引。如果缺少合适的支持，孩子容易陷入工具依赖或信息焦虑。家长需要的不是更多技术，而是理解方向、陪伴方式与可实践的学习支持。\",\"descriptionEn\":\"AI is rapidly entering children\'s learning and life, but families often lack clear judgment and reliable guidance. Without proper support, children can easily fall into tool dependency or information anxiety. Parents need not more technology, but understanding of direction, accompaniment methods, and practical learning support.\",\"imageUrl\":\"https://images.unsplash.com/photo-1609220136736-443140cffec6?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Parent and child learning with AI\"},\"sectionSupport\":{\"title\":\"我们如何支持家庭中的 AI 学习？\",\"titleEn\":\"How Do We Support AI Learning in Families?\",\"description\":\"我们不是提供单一工具或课程，而是围绕家庭的理解需求、陪伴方式与学习资源，构建一套可依靠的支持体系。\",\"descriptionEn\":\"We don\'t provide a single tool or course, but build a reliable support system around families\' understanding needs, accompaniment methods, and learning resources.\",\"supports\":[{\"title\":\"家庭学习支持\",\"titleEn\":\"Home Learning Support\",\"subTitle\":\"适合家庭环境的学习引导与陪伴建议\",\"subTitleEn\":\"Learning guidance and accompaniment suitable for home environment\",\"items\":[{\"title\":\"提供适合家庭环境的 AI 学习引导与陪伴建议\",\"titleEn\":\"Provide AI learning guidance and accompaniment advice suitable for home\"},{\"title\":\"帮助家长理解孩子在不同年龄阶段的学习重点\",\"titleEn\":\"Help parents understand learning priorities at different ages\"},{\"title\":\"支持亲子共同参与，而非单向监督\",\"titleEn\":\"Support parent-child participation, not one-way supervision\"}]},{\"title\":\"免费课程与学习资源\",\"titleEn\":\"Free Courses & Learning Resources\",\"subTitle\":\"面向家庭的免费学习课程与活动\",\"subTitleEn\":\"Free learning courses and activities for families\",\"items\":[{\"title\":\"提供面向家庭的免费 AI 学习课程与活动\",\"titleEn\":\"Provide free AI learning courses and activities for families\"},{\"title\":\"内容聚焦认知、思维与使用习惯，而非技术细节\",\"titleEn\":\"Focus on cognition, thinking, and usage habits, not technical details\"},{\"title\":\"支持孩子在轻松环境中建立基本理解\",\"titleEn\":\"Support children to build basic understanding in a relaxed environment\"}]},{\"title\":\"社区与交流平台\",\"titleEn\":\"Community & Communication\",\"subTitle\":\"与其他家庭共同学习与成长\",\"subTitleEn\":\"Learn and grow with other families\",\"items\":[{\"title\":\"与其他家庭分享经验与遇到的挑战\",\"titleEn\":\"Share experiences and challenges with other families\"},{\"title\":\"在社区中获得真实案例与实践反馈\",\"titleEn\":\"Get real cases and practical feedback in the community\"},{\"title\":\"通过交流建立信心与方向感\",\"titleEn\":\"Build confidence and direction through communication\"}]}]},\"sectionScene\":{\"title\":\"家庭中的 AI 学习如何真正发生？\",\"titleEn\":\"How Does AI Learning Actually Happen in Families?\",\"scenes\":[{\"title\":\"在日常生活中，孩子逐步理解 AI 的作用与边界\",\"titleEn\":\"In Daily Life: Children Gradually Understand AI\'s Role and Boundaries\",\"items\":[{\"title\":\"在真实生活情境中认识 AI 的能力与局限\",\"titleEn\":\"Recognize AI\'s capabilities and limitations in real-life contexts\"},{\"title\":\"学会提出问题，而不是盲目依赖工具\",\"titleEn\":\"Learn to ask questions, not blindly depend on tools\"},{\"title\":\"形成负责任使用 AI 的基本意识\",\"titleEn\":\"Develop basic awareness of responsible AI use\"}],\"case\":{\"title\":\"家庭学习场景｜亲子共学\",\"titleEn\":\"Home Learning Scenarios | Parent-Child Co-learning\"},\"imageUrl\":\"https://images.unsplash.com/photo-1609220136736-443140cffec6?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Parent and child learning together\"},{\"title\":\"在陪伴过程中，家长找到合适的支持方式\",\"titleEn\":\"In Accompaniment: Parents Find Appropriate Support Methods\",\"items\":[{\"title\":\"从\\\"担心与焦虑\\\"转向\\\"理解与引导\\\"\",\"titleEn\":\"Move from \\\"worry and anxiety\\\" to \\\"understanding and guidance\\\"\"},{\"title\":\"学会与孩子讨论 AI 的使用与选择\",\"titleEn\":\"Learn to discuss AI usage and choices with children\"},{\"title\":\"在陪伴中建立信任与学习习惯\",\"titleEn\":\"Build trust and learning habits through accompaniment\"}],\"case\":{\"title\":\"家长陪伴实践\",\"titleEn\":\"Parent Accompaniment Practice\"},\"imageUrl\":\"https://images.unsplash.com/photo-1491013516836-7db643ee125a?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Parent supporting child learning\"},{\"title\":\"通过课程与活动，获得关键学习体验\",\"titleEn\":\"Through Courses & Activities: Gain Key Learning Experiences\",\"items\":[{\"title\":\"通过轻量课程与活动激发学习兴趣\",\"titleEn\":\"Stimulate learning interest through light courses and activities\"},{\"title\":\"在安全环境中体验 AI 的学习可能性\",\"titleEn\":\"Experience AI learning possibilities in a safe environment\"},{\"title\":\"常作为家庭 AI 学习的起点\",\"titleEn\":\"Often serves as starting point for family AI learning\"}],\"case\":{\"title\":\"免费课程 / 家庭 Workshop\",\"titleEn\":\"Free Courses / Family Workshops\"},\"imageUrl\":\"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?crop=entropy&cs=tinysrgb&fit=max&fm=jpg\",\"imageAlt\":\"Family workshop activities\"}]}}');

-- ----------------------------
-- Table structure for aiedu_student
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_student`;
CREATE TABLE `aiedu_student`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '学生记录ID',
  `class_id` int NOT NULL COMMENT '班级ID',
  `student_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '学号',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '学生姓名',
  `gender` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '性别',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL COMMENT '备注',
  `created_at` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_class_id`(`class_id` ASC) USING BTREE,
  INDEX `idx_student_id`(`student_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci COMMENT = '班级学生信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aiedu_student
-- ----------------------------


-- ----------------------------
-- Table structure for aiedu_teachers
-- ----------------------------
DROP TABLE IF EXISTS `aiedu_teachers`;
CREATE TABLE `aiedu_teachers`  (
  `teacher_id` int NOT NULL AUTO_INCREMENT COMMENT '教师ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '教师姓名',
  `school` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '学校名称',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '邮箱地址',
  `phone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '手机号码',
  `avatar` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '头像URL',
  `department` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NULL DEFAULT NULL COMMENT '系',
  `user_id` bigint NULL DEFAULT NULL COMMENT '关联sys_user.user_id',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`teacher_id`) USING BTREE,
  UNIQUE INDEX `email`(`email` ASC) USING BTREE,
